import { Request, Response } from 'express';
import prisma from '../utils/prisma.js';
import { upload, validateUploadedFileContent } from '../utils/upload.js';
import { v2 as cloudinary } from 'cloudinary';
import { sendInternalServerError } from '../utils/errorResponse.js';
import { sanitizeWebUrl } from '../utils/sanitizeUrl.js';
import fs from 'fs';

type PublicRoleRequest = Request & { user?: { id: string; role: string } };

function toInt(value: unknown, fallback: number) {
  const n =
    typeof value === 'string' ? parseInt(value, 10) : typeof value === 'number' ? value : NaN;
  return Number.isFinite(n) ? n : fallback;
}

function slugify(input: string) {
  return input
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

function normalizeYoutubeEmbedUrl(input: string): string | null {
  const raw = String(input ?? '').trim();
  if (!raw) return null;

  if (/^https?:\/\//i.test(raw) && raw.includes('tiktok.com/embed')) {
    return raw.startsWith('http://') ? raw.replace(/^http:\/\//, 'https://') : raw;
  }
  if (/^https?:\/\//i.test(raw) && raw.includes('instagram.com') && raw.includes('/embed')) {
    return raw.startsWith('http://') ? raw.replace(/^http:\/\//, 'https://') : raw;
  }

  const directId = raw.match(/^[a-zA-Z0-9_-]{6,}$/)?.[0];
  if (directId) return `https://www.youtube.com/embed/${directId}`;

  if (raw.includes('youtube.com/embed/') || raw.includes('youtube-nocookie.com/embed/')) {
    return raw.startsWith('http://') ? raw.replace(/^http:\/\//, 'https://') : raw;
  }

  try {
    const url = new URL(raw.startsWith('http') ? raw : `https://${raw}`);
    const host = url.hostname.replace(/^www\./, '');
    let id = '';

    if (host.endsWith('tiktok.com')) {
      const m = url.pathname.match(/\/video\/(\d+)/);
      const vid = m?.[1] || '';
      if (vid) return `https://www.tiktok.com/embed/v2/${vid}`;
      const embed =
        url.pathname.match(/\/embed\/v2\/(\d+)/)?.[1] ||
        url.pathname.match(/\/embed\/(\d+)/)?.[1] ||
        '';
      if (embed) return `https://www.tiktok.com/embed/v2/${embed}`;
      return null;
    }

    if (host.endsWith('instagram.com')) {
      const parts = url.pathname.split('/').filter(Boolean);
      const kind = parts[0] || '';
      const code = parts[1] || '';
      if (!kind || !code) return null;
      if (kind !== 'p' && kind !== 'reel' && kind !== 'tv') return null;
      return `https://www.instagram.com/${kind}/${code}/embed/`;
    }

    if (host === 'youtu.be') {
      id = url.pathname.split('/').filter(Boolean)[0] || '';
    } else if (host.endsWith('youtube.com')) {
      if (url.pathname === '/watch') {
        id = url.searchParams.get('v') || '';
      } else if (url.pathname.startsWith('/shorts/')) {
        id = url.pathname.split('/')[2] || '';
      } else if (url.pathname.startsWith('/embed/')) {
        id = url.pathname.split('/')[2] || '';
      } else if (url.pathname.startsWith('/live/')) {
        id = url.pathname.split('/')[2] || '';
      }
    }

    id = id.trim();
    if (!id) return null;
    if (!/^[a-zA-Z0-9_-]{6,}$/.test(id)) return null;
    return `https://www.youtube.com/embed/${id}`;
  } catch {
    return null;
  }
}

async function ensureUniquePostSlug(base: string) {
  const clean = base || 'post';
  let slug = clean;
  let i = 2;
  while (true) {
    const exists = await prisma.publicPost.findUnique({ where: { slug } });
    if (!exists) return slug;
    slug = `${clean}-${i}`;
    i += 1;
  }
}

