  const clean = base || 'kategori';
  let slug = clean;
  let i = 2;
  while (true) {
    const exists = await prisma.publicCategory.findUnique({ where: { slug } });
    if (!exists) return slug;
    slug = `${clean}-${i}`;
    i += 1;
  }
}

