function validateRecruitmentPublishFields(payload: {
  isPublished?: boolean;
  dateRange?: string;
  formUrl?: string;
}): string | null {
  if (!payload.isPublished) return null;
  if (!String(payload.dateRange ?? '').trim()) {
    return 'Periode pendaftaran wajib diisi sebelum publish.';
  }
  const formUrl = String(payload.formUrl ?? '').trim();
  if (!formUrl || !/^https:\/\/.+/i.test(formUrl)) {
    return 'Link form pendaftaran (https://) wajib diisi sebelum publish.';
  }
  return null;
}

export const createAdminRecruitment = async (
  req: PublicRoleRequest,
  res: Response
): Promise<void> => {
  try {
    const payload = req.body ?? {};
    const title = String(payload.title ?? '').trim();
    if (!title) {
      res.status(400).json({ success: false, error: 'Judul wajib diisi' });
      return;
    }
    const publishErr = validateRecruitmentPublishFields({
      isPublished: payload.isPublished,
      dateRange: payload.dateRange,
      formUrl: payload.formUrl,
    });
    if (publishErr) {
      res.status(400).json({ success: false, error: publishErr });
      return;
    }
    const committee = Array.isArray(payload.committee) ? payload.committee : [];
    const contacts = Array.isArray(payload.contacts) ? payload.contacts : [];
    const row = await prisma.publicRecruitment.create({
      data: {
        title,
        date_range: String(payload.dateRange ?? '').trim() || null,
        description: String(payload.description ?? '').trim() || null,
        form_url: sanitizeWebUrl(payload.formUrl),
        poster_image_url: String(payload.posterImageUrl ?? '').trim() || null,
        is_published: Boolean(payload.isPublished ?? false),
        committee: {
          create: committee
            .map((x: any, idx: number) => ({
              name: String(x?.name ?? '').trim(),
              role: String(x?.role ?? '').trim(),
              sort_order: toInt(x?.sortOrder, idx),
            }))
            .filter((x: any) => Boolean(x.name) && Boolean(x.role)),
        },
        contacts: {
          create: contacts
            .map((x: any, idx: number) => ({
              name: String(x?.name ?? '').trim(),
              contact: String(x?.contact ?? '').trim(),
              sort_order: toInt(x?.sortOrder, idx),
            }))
            .filter((x: any) => Boolean(x.name) && Boolean(x.contact)),
        },
      },
      include: { committee: true, contacts: true },
    });
    res.status(201).json({ success: true, data: row });
  } catch (error) {
    console.error('Error creating recruitment:', error);
    sendInternalServerError(res, error);
  }
};

export const updateAdminRecruitment = async (
  req: PublicRoleRequest,
  res: Response
): Promise<void> => {
  try {
    const { id } = req.params;
    const existing = await prisma.publicRecruitment.findUnique({
      where: { id },
      include: { committee: true, contacts: true },
    });
    if (!existing) {
      res.status(404).json({ success: false, error: 'Open recruitment tidak ditemukan' });
      return;
    }
    const payload = req.body ?? {};
    const title = String(payload.title ?? existing.title).trim();
    if (!title) {
      res.status(400).json({ success: false, error: 'Judul wajib diisi' });
      return;
    }
    const willPublish =
      typeof payload.isPublished === 'boolean' ? payload.isPublished : existing.is_published;
    const publishErr = validateRecruitmentPublishFields({
      isPublished: willPublish,
      dateRange:
        typeof payload.dateRange === 'string' ? payload.dateRange : (existing.date_range ?? ''),
      formUrl: typeof payload.formUrl === 'string' ? payload.formUrl : (existing.form_url ?? ''),
    });
    if (publishErr) {
      res.status(400).json({ success: false, error: publishErr });
      return;
    }
    const committee = Array.isArray(payload.committee) ? payload.committee : null;
    const contacts = Array.isArray(payload.contacts) ? payload.contacts : null;
    const row = await prisma.publicRecruitment.update({
      where: { id },
      data: {
        title,
        date_range:
          typeof payload.dateRange === 'string'
            ? payload.dateRange.trim() || null
            : existing.date_range,
        description:
          typeof payload.description === 'string'
            ? payload.description.trim() || null
            : existing.description,
        form_url:
          typeof payload.formUrl === 'string' ? sanitizeWebUrl(payload.formUrl) : existing.form_url,
        poster_image_url:
          typeof payload.posterImageUrl === 'string'
            ? payload.posterImageUrl.trim() || null
            : existing.poster_image_url,
        is_published:
          typeof payload.isPublished === 'boolean' ? payload.isPublished : existing.is_published,
        committee: committee
          ? {
              deleteMany: {},
              create: committee
                .map((x: any, idx: number) => ({
                  name: String(x?.name ?? '').trim(),
                  role: String(x?.role ?? '').trim(),
                  sort_order: toInt(x?.sortOrder, idx),
                }))
                .filter((x: any) => Boolean(x.name) && Boolean(x.role)),
            }
          : undefined,
        contacts: contacts
          ? {
              deleteMany: {},
              create: contacts
                .map((x: any, idx: number) => ({
                  name: String(x?.name ?? '').trim(),
                  contact: String(x?.contact ?? '').trim(),
                  sort_order: toInt(x?.sortOrder, idx),
                }))
                .filter((x: any) => Boolean(x.name) && Boolean(x.contact)),
            }
          : undefined,
      },
      include: { committee: true, contacts: true },
    });
    res.status(200).json({ success: true, data: row });
  } catch (error) {
    console.error('Error updating recruitment:', error);
    sendInternalServerError(res, error);
  }
};

