        data: {
          action: 'UPDATE_SETTING',
          target_table: 'setting',
          target_id: 'FACULTIES_AND_DEPARTMENTS',
          actor_id: user.id,
          ip_address: req.ip,
          old_value: oldSetting ? oldSetting.value : null,
          new_value: JSON.stringify(data),
