export const importUsers = async (req: Request, res: Response): Promise<void> => {
  const filePath = req.file?.path;
  try {
    if (!req.file || !filePath) {
      res.status(400).json({ success: false, error: 'File Excel tidak ditemukan' });
      return;
    }

    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.readFile(filePath);

    const worksheet = workbook.worksheets[0]; // Get the first sheet
    if (!worksheet) {
      res.status(400).json({ success: false, error: 'Format Excel tidak valid atau kosong' });
      return;
    }

    const actor = (req as any).user;
    const parsedRows: ParsedImportUserRow[] = [];
    const seenEmails = new Set<string>();
    let duplicateRowCount = 0;
    let missingNimNipRowCount = 0;
    const defaultPasswordHash = await bcrypt.hash('password123', 12);
    const requestedImportYearMode =
      typeof req.body?.importEnrollmentYearMode === 'string'
        ? req.body.importEnrollmentYearMode.trim().toUpperCase()
        : '';
    const importYear =
      requestedImportYearMode === 'PREVIOUS_YEAR'
        ? new Date().getFullYear() - 1
        : new Date().getFullYear();
    const importEnrollmentDate = new Date(importYear, 7, 1);

    let isFirstRow = true;
    worksheet.eachRow((row, _rowNumber) => {
      if (isFirstRow) {
        isFirstRow = false; // Skip header
        return;
      }

      // Expected Columns: A=Nama, B=Email, C=NIM_NIP, D=Departemen, E=Semester, F=No_HP, G=Role
      const name = row.getCell(1).value?.toString().trim();
      const email = normalizeImportEmail(row.getCell(2).value);
      const nim_nip = normalizeNimNip(row.getCell(3).value);
      const department = row.getCell(4).value?.toString().trim();
      const semester = parseInt(row.getCell(5).value?.toString().trim() || '1') || 1;
      const phone = row.getCell(6).value?.toString().trim();
      const rawRole = row.getCell(7).value?.toString().trim().toUpperCase();
      const classNames = parseImportClassNames(row.getCell(8).value);

      const role =
        rawRole === 'ADMIN' || rawRole === 'SUPER_ADMIN' || rawRole === 'CONTENT_ADMIN'
          ? rawRole
          : 'USER';

      if (name && email) {
        if (!nim_nip) {
          missingNimNipRowCount++;
          return;
        }
        if (seenEmails.has(email)) {
          duplicateRowCount++;
          return;
        }
        seenEmails.add(email);
        parsedRows.push({
          name,
          email,
          nim_nip,
          department: department || null,
          semester: role === 'USER' ? semester : null,
          phone: phone || null,
          role,
          classNames: role === 'USER' ? classNames : [],
        });
      }
    });

    if (parsedRows.length === 0) {
      res
        .status(400)
        .json({ success: false, error: 'Tidak ada data valid yang ditemukan di Excel' });
      return;
    }

    const parsedEmails = parsedRows.map((row) => row.email);
    const existingUsers = await prisma.user.findMany({
      where: { email: { in: parsedEmails } },
      select: { email: true },
    });
    const existingEmailSet = new Set(existingUsers.map((user) => user.email.toLowerCase()));
    const rowsToCreate = parsedRows.filter((row) => !existingEmailSet.has(row.email));

    const requiredClasses = new Map<
      string,
      { name: string; semester: number; lecturer_id: string }
    >();
    for (const row of rowsToCreate) {
      if (row.role !== 'USER' || !row.semester) continue;
      for (const className of row.classNames) {
        const key = classIdentityKey(actor.id, row.semester, className);
        if (!requiredClasses.has(key)) {
          requiredClasses.set(key, {
            name: className,
            semester: row.semester,
            lecturer_id: actor.id,
          });
        }
      }
    }

    const requiredClassList = Array.from(requiredClasses.values());
    let createdClassCount = 0;
    const classMap = new Map<string, { id: string; name: string; semester: number }>();

    if (requiredClassList.length > 0) {
      const existingClasses = await prisma.class.findMany({
        where: {
          lecturer_id: actor.id,
          name: { in: Array.from(new Set(requiredClassList.map((item) => item.name))) },
          semester: { in: Array.from(new Set(requiredClassList.map((item) => item.semester))) },
        },
        select: { id: true, name: true, semester: true },
      });

      for (const existingClass of existingClasses) {
        classMap.set(
          classIdentityKey(actor.id, existingClass.semester ?? 1, existingClass.name),
          existingClass
        );
      }

      const missingClasses = requiredClassList.filter(
        (item) => !classMap.has(classIdentityKey(actor.id, item.semester, item.name))
      );

      for (const item of missingClasses) {
        const createdClass = await prisma.class.create({
          data: {
            name: item.name,
            semester: item.semester,
            lecturer_id: item.lecturer_id,
            course_code: null,
            description: null,
          },
          select: { id: true, name: true, semester: true },
        });
        classMap.set(classIdentityKey(actor.id, item.semester, item.name), createdClass);
        createdClassCount++;
      }
    }

    const usersToCreate = rowsToCreate.map((row) => ({
      name: row.name,
      email: row.email,
      nim_nip: row.nim_nip,
      department: row.department,
      semester: row.role === 'USER' ? (row.semester ?? 1) : undefined,
      phone: row.phone,
      role: row.role,
      password: defaultPasswordHash,
      enrollment_date: importEnrollmentDate,
    }));

    const createdUsers =
      usersToCreate.length > 0
        ? await prisma.user.createMany({
            data: usersToCreate,
            skipDuplicates: true,
          })
        : { count: 0 };

    const createdUserRecords =
      rowsToCreate.length > 0
        ? await prisma.user.findMany({
            where: { email: { in: rowsToCreate.map((row) => row.email) } },
            select: { id: true, email: true },
          })
        : [];
    const createdUserByEmail = new Map(
      createdUserRecords.map((user) => [user.email.toLowerCase(), user.id])
    );

    const enrollmentData: { class_id: string; student_id: string }[] = [];
    for (const row of rowsToCreate) {
      if (row.role !== 'USER' || !row.semester || row.classNames.length === 0) continue;
      const studentId = createdUserByEmail.get(row.email);
      if (!studentId) continue;

      for (const className of row.classNames) {
        const cls = classMap.get(classIdentityKey(actor.id, row.semester, className));
        if (!cls) continue;
        enrollmentData.push({
          class_id: cls.id,
          student_id: studentId,
        });
      }
    }

    const createdEnrollments =
      enrollmentData.length > 0
        ? await prisma.classEnrollment.createMany({
            data: enrollmentData,
            skipDuplicates: true,
          })
        : { count: 0 };

    await prisma.auditLog.create({
      data: {
        actor_id: actor.id,
        action: 'IMPORT_USERS',
        target_table: 'User',
        target_id: 'MULTIPLE',
        new_value: JSON.stringify({
          imported_users: createdUsers.count,
          created_classes: createdClassCount,
          created_enrollments: createdEnrollments.count,
          skipped_existing_users: parsedRows.length - rowsToCreate.length,
          skipped_duplicate_rows: duplicateRowCount,
          skipped_missing_nim_nip_rows: missingNimNipRowCount,
        }),
        ip_address: req.ip,
      },
    });

    res.status(200).json({
      success: true,
      message: `${createdUsers.count} pengguna berhasil diimpor, ${createdClassCount} kelas dibuat otomatis, dan ${createdEnrollments.count} enrollment kelas berhasil dibuat. Enrollment date disetel ke 1 Agustus ${importEnrollmentDate.getFullYear()}.`,
      data: {
        count: createdUsers.count,
        enrollment_date: importEnrollmentDate.toISOString(),
        classes_created: createdClassCount,
        class_enrollments_created: createdEnrollments.count,
        skipped_existing_users: parsedRows.length - rowsToCreate.length,
        skipped_duplicate_rows: duplicateRowCount,
        skipped_missing_nim_nip_rows: missingNimNipRowCount,
      },
    });
  } catch (error: unknown) {
    console.error('Error importing users:', error);
    res
      .status(500)
      .json({ success: false, error: 'Gagal mengimpor file Excel. Pastikan format benar.' });
  } finally {
    if (filePath) {
      await fs.promises.unlink(filePath).catch(() => {});
    }
  }
};

// Reset Device Fingerprint
export const resetDeviceFingerprint = async (req: Request, res: Response): Promise<void> => {
  try {
    const { id } = req.params;
    const actor = (req as any).user;

    if (actor.role === 'ADMIN') {
      const target = await prisma.user.findUnique({ where: { id }, select: { role: true } });
      if (!target || target.role !== 'USER') {
        res.status(403).json({ success: false, error: 'Akses ditolak' });
        return;
      }
      const allowed = await adminCanViewStudent(actor.id, id);
      if (!allowed) {
        res.status(403).json({ success: false, error: 'Akses ditolak' });
        return;
      }
    }

    await prisma.user.update({
      where: { id },
      data: { device_fingerprint: null },
    });

    res.json({ success: true, message: 'Perangkat mahasiswa berhasil di-reset' });
  } catch (error: unknown) {
    console.error('Error resetting device:', error);
    res.status(500).json({ success: false, error: 'Internal server error' });
  }
};

import cron from 'node-cron';
import prisma from '../utils/prisma.js';
import fs from 'fs';
import path from 'path';
import { v2 as cloudinary } from 'cloudinary';

let isRunning = false;
let lastRunTime = 0;

export const runCronJob = async () => {
  // Prevent concurrent runs and enforce 1-minute minimum interval
  const nowTime = Date.now();
  if (isRunning || nowTime - lastRunTime < 60000) return;

  isRunning = true;
  lastRunTime = nowTime;

  try {
    const resolveExpectedUserIds = async (session: any) => {
      if (session.class_id) {
        const enrollments = await prisma.classEnrollment.findMany({
          where: { class_id: session.class_id },
          select: { student_id: true },
        });
        return enrollments.map((e) => e.student_id);
      }
      const linked = await prisma.sessionClass.findMany({
        where: { session_id: session.id },
        select: { class_id: true },
      });
      const classIds = linked.map((x) => x.class_id);
      if (classIds.length > 0) {
        const enrollments = await prisma.classEnrollment.findMany({
          where: { class_id: { in: classIds } },
          select: { student_id: true },
        });
        return Array.from(new Set(enrollments.map((e) => e.student_id)));
      }
      // WARNING: Falling back to ALL active users because session has no class linked
      console.warn(
        `[Cron] resolveExpectedUserIds: Session id=${session.id} (title="${session.title}") has no linked classes. Falling back to ALL active USER role users.`
      );
      const activeUsers = await prisma.user.findMany({
        where: { role: 'USER', is_active: true },
        select: { id: true },
      });
      return activeUsers.map((u) => u.id);
    };

    const now = new Date();

    // Pembukaan sesi mengikuti jendela check-in, sedangkan penutupan final
    // mengikuti `session_end` agar check-out tetap dapat dilakukan sampai kelas selesai.
    // UPCOMING -> ACTIVE (when check_in_open_at is reached and before check_in_close_at + 2 min grace period)
    const twoMinutesAgo = new Date(now.getTime() - 2 * 60000);
    const twoMinutesFuture = new Date(now.getTime() + 2 * 60000);
    // Cooldown 1 menit: sesi yang baru dibuat / di-update tidak langsung kena cron,
    // memberi admin buffer untuk edit ulang jika salah set jam.
    const oneMinuteAgo = new Date(now.getTime() - 60_000);

    const sessionsToActivate = await prisma.session.findMany({
      where: {
        status: 'UPCOMING',
        updated_at: { lte: oneMinuteAgo },
        // Active when now >= check_in_open_at - 2 min
        check_in_open_at: { lte: twoMinutesFuture },
        // Must not have reached check_in_close_at + 2 min yet
        check_in_close_at: { gt: twoMinutesAgo },
      },
    });

    if (sessionsToActivate.length > 0) {
      await prisma.session.updateMany({
        where: { id: { in: sessionsToActivate.map((s) => s.id) } },
        data: { status: 'ACTIVE' },
      });

      // Notify creator that session is active
      for (const session of sessionsToActivate) {
        // Create notification for creator
        await prisma.notification.create({
          data: {
            user_id: session.created_by_id,
            title: 'Sesi absensi dibuka',
            message: `Sesi "${session.title}" sudah aktif. Mahasiswa dapat melakukan check-in sekarang.`,
            type: 'SUCCESS',
          },
        });

        // Notify students
        const expectedUserIds: string[] = await resolveExpectedUserIds(session);

        if (expectedUserIds.length > 0) {
          await prisma.notification.createMany({
            data: expectedUserIds.map((id) => ({
              user_id: id,
              title: 'Waktunya absen',
              message: `Sesi "${session.title}" sudah dibuka. Buka aplikasi dan lakukan check-in sebelum batas waktu.`,
              type: 'INFO',
            })),
          });
        }
      }
      console.log(`[Cron] Marked ${sessionsToActivate.length} sessions as ACTIVE`);
    }

    // ACTIVE/UPCOMING -> CLOSED (when the session has actually ended, plus a short grace period)
    const activatedSessionIds = sessionsToActivate.map((s) => s.id);
    const sessionsToClose = await prisma.session.findMany({
      where: {
        id: { notIn: activatedSessionIds },
        status: { in: ['ACTIVE', 'UPCOMING'] },
        updated_at: { lte: oneMinuteAgo },
        // Keep sessions ACTIVE until shortly after `session_end` so required
        // check-out remains possible for students who already checked in.
        session_end: { lte: twoMinutesAgo },
      },
    });

    if (sessionsToActivate.length > 0 || sessionsToClose.length > 0) {
      console.log(
        `[Cron] now=${now.toISOString()} activated=${sessionsToActivate.length} closed=${sessionsToClose.length}`
      );
    }

    if (sessionsToClose.length > 0) {
      await prisma.session.updateMany({
        where: { id: { in: sessionsToClose.map((s) => s.id) } },
        data: { status: 'CLOSED' },
      });

      // Auto-Absent Job
      for (const session of sessionsToClose) {
        // Determine which users are supposed to attend
        const expectedUserIds: string[] = await resolveExpectedUserIds(session);

        // Get all present users for this session
        const presentAttendances = await prisma.attendance.findMany({
          where: { session_id: session.id },
          select: { user_id: true },
        });
        const presentUserIds = presentAttendances.map((a) => a.user_id);

        // Find users who didn't check in
        const absentUserIds = expectedUserIds.filter((id) => !presentUserIds.includes(id));

        // Create ABSENT records
        if (absentUserIds.length > 0) {
          await prisma.attendance.createMany({
            data: absentUserIds.map((id) => ({
              session_id: session.id,
              user_id: id,
              status: 'ABSENT',
              check_in_time: new Date(),
              check_in_ip: 'SYSTEM',
              check_in_device: 'AUTO_JOB',
            })),
          });
        }

        // Notify creator that session is closed
        await prisma.notification.create({
          data: {
            user_id: session.created_by_id,
            title: 'Sesi absensi ditutup',
            message: `Sesi "${session.title}" telah ditutup. ${absentUserIds.length} mahasiswa ditandai tidak hadir (Alfa).`,
            type: 'INFO',
          },
        });

        // Notify absent students
        if (absentUserIds.length > 0) {
          await prisma.notification.createMany({
            data: absentUserIds.map((id) => ({
              user_id: id,
              title: 'Tidak hadir (Alfa)',
              message: `Anda ditandai tidak hadir pada sesi "${session.title}" karena sesi telah berakhir tanpa check-in.`,
              type: 'WARNING',
            })),
          });
        }

        // Check Early Warning System (EWS) for < 75% attendance for absent users (Optimized N+1)
        const linked = await prisma.sessionClass.findMany({
          where: { session_id: session.id },
          select: { class_id: true },
        });
        const classIds = session.class_id ? [session.class_id] : linked.map((x) => x.class_id);

        if (classIds.length > 0 && absentUserIds.length > 0) {
          const notificationsToCreate: any[] = [];

          const totalSessionsMap: Record<string, number> = {};
          for (const classId of classIds) {
            const count = await prisma.session.count({
              where: {
                status: 'CLOSED',
                OR: [{ class_id: classId }, { session_classes: { some: { class_id: classId } } }],
              },
            });
            totalSessionsMap[classId] = count;
          }

          const enrollments = await prisma.classEnrollment.findMany({
            where: { class_id: { in: classIds }, student_id: { in: absentUserIds } },
          });

          const userClassAttendances = await prisma.attendance.findMany({
            where: {
              user_id: { in: absentUserIds },
              status: { in: ['PRESENT', 'LATE', 'SICK', 'EXCUSED'] },
              session: {
                status: 'CLOSED',
                OR: [
                  { class_id: { in: classIds } },
                  { session_classes: { some: { class_id: { in: classIds } } } },
                ],
              },
            },
            select: {
              user_id: true,
              session: {
                select: { class_id: true, session_classes: { select: { class_id: true } } },
              },
            },
          });

          const attendanceCounts: Record<string, Record<string, number>> = {};
          for (const att of userClassAttendances) {
            const attClassIds = att.session.class_id
              ? [att.session.class_id]
              : att.session.session_classes.map((x: any) => x.class_id);
            for (const cId of attClassIds) {
              if (classIds.includes(cId)) {
                if (!attendanceCounts[att.user_id]) attendanceCounts[att.user_id] = {};
                attendanceCounts[att.user_id][cId] = (attendanceCounts[att.user_id][cId] || 0) + 1;
              }
            }
          }

          for (const enr of enrollments) {
            const total = totalSessionsMap[enr.class_id] || 0;
            if (total > 0) {
              const attended =
                (attendanceCounts[enr.student_id] &&
                  attendanceCounts[enr.student_id][enr.class_id]) ||
                0;
              const percentage = (attended / total) * 100;
              if (percentage < 75) {
                notificationsToCreate.push({
                  user_id: enr.student_id,
                  title: 'Peringatan Dini Kehadiran (EWS)',
                  message: `Tingkat kehadiran Anda di salah satu kelas telah turun menjadi ${Math.round(percentage)}% (Di bawah batas minimal 75%). Harap perhatikan kehadiran Anda.`,
                  type: 'WARNING',
                });
              }
            }
          }

          // Deduplicate notifications so a user doesn't get spammed if multiple classes drop below 75% simultaneously
          const uniqueNotifications = Array.from(
            new Map(notificationsToCreate.map((item) => [item.user_id, item])).values()
          );
          if (uniqueNotifications.length > 0) {
            await prisma.notification.createMany({ data: uniqueNotifications });
          }
        }
      }
      console.log(
        `[Cron] Marked ${sessionsToClose.length} sessions as CLOSED and processed absences.`
      );
    }
  } catch (error) {
    console.error('[Cron] Error updating session statuses:', error);
  } finally {
    isRunning = false;
  }
};

export const runNonceCleanupJob = async () => {
  const now = new Date();
  const nonceRetentionCutoff = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
  const cleaned = await prisma.challengeNonce.deleteMany({
    where: { expires_at: { lt: nonceRetentionCutoff } },
  });
  if (cleaned.count > 0) {
    console.log(`[Cron] Cleaned ${cleaned.count} expired nonces`);
  }
};

export const runPhotoCleanupJob = async () => {
  console.log('[Cron] Running daily photo cleanup job...');
  const oneWeekAgo = new Date();
  oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);

  const oldAttendances = await prisma.attendance.findMany({
    where: {
      photo_url: { not: null },
      check_in_time: { lt: oneWeekAgo },
    },
    select: { id: true, photo_url: true },
  });

  let deletedCount = 0;
  for (const att of oldAttendances) {
    if (!att.photo_url) continue;
    let deleteSuccess = false;
    const photoUrl = att.photo_url;

    if (photoUrl.includes('cloudinary') || photoUrl.includes('res.cloudinary.com')) {
      try {
        // Extract public ID correctly: remove version prefix (like /v1234567/) if exists
        // Example: https://res.cloudinary.com/.../v1234567/attendance/abc123.jpg ΓåÆ publicId = attendance/abc123
        const urlParts = photoUrl.split('/');
        let startIndex = 0;
        // Find the part that starts with 'v' followed by digits (version)
        for (let i = 0; i < urlParts.length; i++) {
          if (/^v\d+$/.test(urlParts[i])) {
            startIndex = i + 1; // public ID starts right after version part
            break;
          }
        }
        // Join from startIndex, then remove the file extension
        const publicIdWithExt = urlParts.slice(startIndex).join('/');
        const publicId = publicIdWithExt.replace(/\.[^/.]+$/, ''); // remove file extension

        await cloudinary.uploader.destroy(publicId);
        deleteSuccess = true;
      } catch (err) {
        console.error(
          `[Cron] PHOTO_CLEANUP_FAILED attendanceId=${att.id} publicId=${att.photo_url}`,
          err
        );
        deleteSuccess = false;
      }
    } else {
      // Local file handling
      const fileName = path.basename(photoUrl);
      const filePath = path.join(process.cwd(), 'uploads', 'attendance', fileName);
      if (fs.existsSync(filePath)) {
        fs.unlinkSync(filePath);
        deleteSuccess = true;
      } else {
        // If local file doesn't exist, we can still mark it as deleted (orphaned)
        deleteSuccess = true;
      }
    }

    if (deleteSuccess) {
      await prisma.attendance.update({
        where: { id: att.id },
        data: { photo_url: null },
      });
      deletedCount++;
    }
  }

  if (deletedCount > 0) {
    console.log(
      `[Cron] Berhasil menghapus ${deletedCount} foto bukti yang berumur lebih dari 1 minggu.`
    );
  }
};

export const runSemesterUpdateJob = async () => {
  console.log('[Cron] Running daily semester update job...');
  const users = await prisma.user.findMany({
    where: { role: 'USER', is_active: true },
    select: { id: true, enrollment_date: true, semester: true },
  });

  let updatedCount = 0;
  const now = new Date();

  for (const user of users) {
    const enrollmentDate = new Date((user as any).enrollment_date);
    const monthsDiff =
      (now.getFullYear() - enrollmentDate.getFullYear()) * 12 +
      (now.getMonth() - enrollmentDate.getMonth());
    const newSemester = Math.max(1, Math.min(14, Math.floor(monthsDiff / 6) + 1));

    // Deactivate users at semester >=10: this is end of typical 4-year (8-semester) program + 2-semester buffer for extensions
    if (newSemester !== (user as any).semester || newSemester >= 10) {
      await prisma.user.update({
        where: { id: user.id },
        data:
          newSemester >= 10
            ? { semester: newSemester, is_active: false, refresh_token_hash: null }
            : { semester: newSemester },
      });
      updatedCount++;
    }
  }

  console.log(`[Cron] Semester update complete. Updated ${updatedCount} users.`);
};

/** Fire-and-forget session status sync (throttled inside runCronJob). Safe on Vercel. */
export const triggerSessionCronLazy = () => {
  void runCronJob().catch((err) => console.error('[Cron] Lazy session sync error:', err));
};

export const startCronJobs = () => {
  console.log('[Cron] Starting session status updater (Interval: 1 minute)...');

  setInterval(runCronJob, 60000);

  cron.schedule('0 0 * * *', () => {
    runNonceCleanupJob().catch((err) => console.error('[Cron] Error cleaning nonces:', err));
  });

  cron.schedule('0 2 * * *', () => {
    runPhotoCleanupJob().catch((err) => console.error('[Cron] Error cleaning up photos:', err));
  });

  cron.schedule('0 1 * * *', () => {
    runSemesterUpdateJob().catch((err) => console.error('[Cron] Error updating semesters:', err));
  });
};

import { Response, NextFunction } from 'express';
import { verifyAccessToken } from '../utils/jwt.js';
import type { AuthRequest } from '../types/index.js';

export const authenticate = (req: AuthRequest, res: Response, next: NextFunction): void => {
  const bypass =
    (process.env.NODE_ENV === 'development' || process.env.NODE_ENV === 'test') &&
    (process.env.DEV_BYPASS_AUTH === 'true' || process.env.DEV_BYPASS_AUTH === '1');
  if (bypass) {
    req.user = {
      id: process.env.DEV_BYPASS_USER_ID || 'dev-preview',
      role: process.env.DEV_BYPASS_ROLE || 'SUPER_ADMIN',
    };
    next();
    return;
  }

  // Read token from cookies first, fallback to Authorization header
  let token = req.cookies.accessToken;

  if (!token) {
    const authHeader = req.headers.authorization;
    if (authHeader?.startsWith('Bearer ')) {
      token = authHeader.split(' ')[1];
    }
  }

  if (!token) {
    res.status(401).json({ success: false, error: 'Unauthorized: No token provided' });
    return;
  }

  try {
    const decoded = verifyAccessToken(token);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(401).json({ success: false, error: 'Unauthorized: Invalid or expired token' });
    return;
  }
};

export const authorize = (roles: string[]) => {
  return (req: AuthRequest, res: Response, next: NextFunction): void => {
    const bypass =
      (process.env.NODE_ENV === 'development' || process.env.NODE_ENV === 'test') &&
      (process.env.DEV_BYPASS_AUTH === 'true' || process.env.DEV_BYPASS_AUTH === '1');
    if (bypass) {
      next();
      return;
    }

    if (!req.user) {
      res.status(401).json({ success: false, error: 'Unauthorized: No user found' });
      return;
    }
    if (!roles.includes(req.user.role)) {
      res.status(403).json({ success: false, error: 'Forbidden: Insufficient permissions' });
      return;
    }
    next();
  };
};

import type { Request, Response, NextFunction } from 'express';

function isSafeMethod(method: string): boolean {
  const m = method.toUpperCase();
  return m === 'GET' || m === 'HEAD' || m === 'OPTIONS';
}

function shouldSkipPath(pathname: string): boolean {
  if (pathname === '/api/auth/login') return true;
  if (pathname === '/api/auth/refresh') return true;
  if (pathname === '/api/auth/seed') return true;
  if (pathname === '/api/auth/flush-db') return true;
  if (pathname === '/api/health') return true;
  if (pathname === '/api/health/db') return true;
  if (pathname === '/api/status') return true;
  if (pathname.startsWith('/api/cron')) return true;
  return false;
}

export function csrfProtect(req: Request, res: Response, next: NextFunction): void {
  if (isSafeMethod(req.method)) {
    next();
    return;
  }

  const pathname = req.path || '';
  if (shouldSkipPath(pathname)) {
    next();
    return;
  }

  const csrfCookie = (req as any).cookies?.csrfToken as string | undefined;
  const csrfHeader = (req.headers['x-csrf-token'] as string | undefined) ?? undefined;

  if (!csrfCookie || !csrfHeader || csrfCookie !== csrfHeader) {
    res.status(403).json({ success: false, error: 'CSRF validation failed' });
    return;
  }

  next();
}

import { Router, Request, Response } from 'express';
import {
  runCronJob,
  runNonceCleanupJob,
  runPhotoCleanupJob,
  runSemesterUpdateJob,
} from '../jobs/cron.js';

const router = Router();

type CronJobType = 'session' | 'photo' | 'semester' | 'daily' | 'all';

router.get('/trigger', async (req: Request, res: Response): Promise<void> => {
  const job = (String(req.query.job || 'session').toLowerCase() as CronJobType) || 'session';

  const startedAt = Date.now();
  try {
    const allowedJobs: CronJobType[] = ['session', 'photo', 'semester', 'daily', 'all'];
    if (!allowedJobs.includes(job)) {
      res.status(400).json({ success: false, error: 'Invalid cron job' });
      return;
    }

    const jobs: Array<Promise<void>> = [];
    if (job === 'session' || job === 'all') {
      jobs.push(runCronJob());
    }
    if (job === 'daily' || job === 'all') {
      jobs.push(runNonceCleanupJob());
    }
    if (job === 'photo' || job === 'daily' || job === 'all') {
      jobs.push(runPhotoCleanupJob());
    }
    if (job === 'semester' || job === 'daily' || job === 'all') {
      jobs.push(runSemesterUpdateJob());
    }
    await Promise.all(jobs);

    const durationMs = Date.now() - startedAt;
    console.info('[Cron] job completed', { job, durationMs });

    res.status(200).json({
      success: true,
      message: 'Cron job triggered',
      job,
      triggeredAt: new Date().toISOString(),
      durationMs,
    });
  } catch (error) {
    res.status(500).json({ success: false, error: 'Failed to trigger cron job' });
  }
});

export default router;

