                    }
                  />
                  <Route
                    path="/students/:studentId/attendance"
                    element={
                      <PageSuspense>
                        <ProtectedRoute allowedRoles={['SUPER_ADMIN', 'ADMIN']}>
                          <StudentAttendanceRecap />
                        </ProtectedRoute>
                      </PageSuspense>
                    }
                  />
                  <Route
                    path="/excuses"
                    element={
                      <PageSuspense>
                        <ProtectedRoute allowedRoles={['SUPER_ADMIN', 'ADMIN', 'USER']}>
                          <Excuses />
                        </ProtectedRoute>
                      </PageSuspense>
                    }
                  />
                  <Route
                    path="/users"
                    element={
                      <PageSuspense>
