import { useEffect, useRef, useCallback } from 'react';
import { useAuthStore } from '@/stores/authStore';
import { toast } from 'sonner';
import api, { verifySession } from '@/services/api';

const INACTIVITY_TIMEOUT_MS = 30 * 60 * 1000; // 30 minutes
const PROACTIVE_REFRESH_INTERVAL_MS = 10 * 60 * 1000; // 10 minutes

export function useAutoLogout() {
  const { isAuthenticated, logout } = useAuthStore();
  const inactivityTimerRef = useRef<NodeJS.Timeout | null>(null);
  const refreshTimerRef = useRef<NodeJS.Timeout | null>(null);

  // Use useCallback so the function always sees the latest isAuthenticated
  // and doesn't suffer from stale closures when called by event listeners.
  const resetInactivityTimer = useCallback(() => {
    if (inactivityTimerRef.current) {
      clearTimeout(inactivityTimerRef.current);
      inactivityTimerRef.current = null;
    }

    if (isAuthenticated) {
      inactivityTimerRef.current = setTimeout(async () => {
        try {
          await api.post('/auth/logout');
        } catch (e) {
          // ignore
        }
        logout();
        toast.info('Anda telah logout otomatis karena tidak ada aktivitas selama 30 menit.');
        if (window.location.pathname !== '/login') {
          window.location.href = '/login';
        }
      }, INACTIVITY_TIMEOUT_MS);
    }
  }, [isAuthenticated, logout]);

  const startProactiveRefresh = useCallback(() => {
    const refresh = async () => {
      if (!isAuthenticated) return;
      try {
        await verifySession();
      } catch (e) {
        // Ignore refresh errors - the response interceptor will handle it if needed
      }
    };

    // Initial refresh if authenticated
    if (isAuthenticated) {
      void refresh();
    }

    // Set up interval
    if (refreshTimerRef.current) {
      clearInterval(refreshTimerRef.current);
      refreshTimerRef.current = null;
    }

    if (isAuthenticated) {
      refreshTimerRef.current = setInterval(() => {
        void refresh();
      }, PROACTIVE_REFRESH_INTERVAL_MS);
    }
  }, [isAuthenticated]);

  useEffect(() => {
    if (!isAuthenticated) {
      // Clear any lingering timers when not authenticated
      if (inactivityTimerRef.current) {
        clearTimeout(inactivityTimerRef.current);
        inactivityTimerRef.current = null;
      }
      if (refreshTimerRef.current) {
        clearInterval(refreshTimerRef.current);
        refreshTimerRef.current = null;
      }
      return;
    }

    // Set initial timers
    resetInactivityTimer();
    startProactiveRefresh();

    // Events that reset the inactivity timer
    const events = ['mousedown', 'mousemove', 'keydown', 'scroll', 'touchstart'];

    const handleActivity = () => {
      resetInactivityTimer();
    };

    events.forEach((event) => {
      document.addEventListener(event, handleActivity, { passive: true });
    });

    return () => {
      if (inactivityTimerRef.current) {
        clearTimeout(inactivityTimerRef.current);
        inactivityTimerRef.current = null;
      }
      if (refreshTimerRef.current) {
        clearInterval(refreshTimerRef.current);
        refreshTimerRef.current = null;
      }
      events.forEach((event) => {
        document.removeEventListener(event, handleActivity);
      });
    };
  }, [isAuthenticated, resetInactivityTimer, startProactiveRefresh]);
}

import { useEffect, useMemo, useState } from 'react';
import type { PaginationMeta } from '@/types/common';

/** Paginasi client-side untuk data yang sudah difilter di frontend */
export function useClientPagination<T>(
  items: T[],
  options: { pageSize?: number; resetDeps?: readonly unknown[] } = {},
) {
  const pageSize = options.pageSize ?? 20;
  const [page, setPage] = useState(1);

  useEffect(() => {
    setPage(1);
  }, [items.length, ...(options.resetDeps ?? [])]);

  const totalPages = Math.max(1, Math.ceil(items.length / pageSize));
  const safePage = Math.min(page, totalPages);

  useEffect(() => {
    if (page > totalPages) setPage(totalPages);
  }, [page, totalPages]);

  const paginatedItems = useMemo(
    () => items.slice((safePage - 1) * pageSize, safePage * pageSize),
    [items, safePage, pageSize],
  );

  const meta: PaginationMeta = useMemo(
    () => ({
      total: items.length,
      page: safePage,
      limit: pageSize,
      totalPages,
    }),
    [items.length, safePage, pageSize, totalPages],
  );

  return { page: safePage, setPage, paginatedItems, meta };
}

import { useEffect, useRef, type RefObject } from 'react';

const FOCUSABLE =
  'a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])';

/** [A11y] P-02 ΓÇö focus trap, Escape, restore focus ke trigger */
export function useDialogA11y(
  open: boolean,
  onClose: () => void,
  options?: { containerRef?: RefObject<HTMLElement | null>; triggerRef?: RefObject<HTMLElement | null> },
) {
  const fallbackRef = useRef<HTMLElement | null>(null);
  const containerRef = options?.containerRef ?? fallbackRef;
  const triggerRef = options?.triggerRef;

  useEffect(() => {
    if (!open) return;

    const previousFocus = document.activeElement as HTMLElement | null;
    const root = containerRef.current;
    if (!root) return;

    const getFocusable = () => Array.from(root.querySelectorAll<HTMLElement>(FOCUSABLE)).filter((el) => !el.hasAttribute('disabled'));

    const focusFirst = () => {
      const list = getFocusable();
      (list[0] ?? root).focus();
    };

    const t = window.setTimeout(focusFirst, 0);

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        onClose();
        return;
      }
      if (e.key !== 'Tab') return;
      const list = getFocusable();
      if (!list.length) {
        e.preventDefault();
        return;
      }
      const first = list[0];
      const last = list[list.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    };

    document.addEventListener('keydown', onKeyDown);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    return () => {
      window.clearTimeout(t);
      document.removeEventListener('keydown', onKeyDown);
      document.body.style.overflow = prevOverflow;
      (triggerRef?.current ?? previousFocus)?.focus?.();
    };
  }, [open, onClose, containerRef, triggerRef]);
}

import { useState, useEffect, useMemo } from 'react';
import api from '@/services/api';

export function useFacultyDirectory() {
  const [facultiesData, setFacultiesData] = useState<{ name: string; departments: string[] }[]>([]);
  const [departmentQuery, setDepartmentQuery] = useState('');

  const fetchFaculties = async () => {
    try {
      const res = await api.get('/settings/departments');
      if (res.data.data) {
        setFacultiesData(res.data.data);
      }
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    fetchFaculties();
  }, []);

  const totalDepartments = useMemo(() => {
    return facultiesData.reduce((acc, f) => acc + (f?.departments?.length ?? 0), 0);
  }, [facultiesData]);

  const filteredFacultiesData = useMemo(() => {
    const q = departmentQuery.trim().toLowerCase();
    if (!q) return facultiesData;
    return facultiesData
      .map((f) => {
        const filteredDepartments = (f?.departments ?? []).filter((d) => {
          const name =
            typeof d === 'object' && d !== null ? (d as any).name || (d as any).id : String(d);
          return String(name).toLowerCase().includes(q);
        });
        return { ...f, departments: filteredDepartments };
      })
      .filter((f) => (f?.departments?.length ?? 0) > 0);
  }, [facultiesData, departmentQuery]);

  return {
    facultiesData,
    setFacultiesData,
    departmentQuery,
    setDepartmentQuery,
    totalDepartments,
    filteredFacultiesData,
    fetchFaculties,
  };
}

