import { useCallback, useEffect, useRef, useState } from 'react';
import type { WheelEvent as ReactWheelEvent } from 'react';

export default function useHorizontalWheelScroll(enabled: boolean) {
  const [node, setNode] = useState<HTMLElement | null>(null);
  const rafId = useRef<number | null>(null);
  const targetLeft = useRef<number>(0);
  const lastEl = useRef<HTMLElement | null>(null);

  const stop = () => {
    if (rafId.current) cancelAnimationFrame(rafId.current);
    rafId.current = null;
  };

  const animateToTarget = () => {
    const el = lastEl.current;
    if (!el) return;
    const max = el.scrollWidth - el.clientWidth;
    if (max <= 0) return;
    const target = Math.min(max, Math.max(0, targetLeft.current));
    const cur = el.scrollLeft;
    const diff = target - cur;
    if (Math.abs(diff) < 0.75) {
      el.scrollLeft = target;
      stop();
      return;
    }
    el.scrollLeft = cur + diff * 0.22;
    rafId.current = requestAnimationFrame(animateToTarget);
  };

  const handle = useCallback(
    (
      el: HTMLElement,
      deltaX: number,
      deltaY: number,
      preventDefault: () => void,
      stopPropagation: () => void
    ) => {
      if (!enabled) return;
      const max = el.scrollWidth - el.clientWidth;
      if (max <= 0) return;

      const ax = Math.abs(deltaX);
      const ay = Math.abs(deltaY);
      if (ax === 0 && ay === 0) return;

      if (ax > ay * 1.15) return;
      const delta = deltaY || deltaX;
      if (!delta) return;

      preventDefault();
      stopPropagation();

      lastEl.current = el;
      targetLeft.current = Math.min(max, Math.max(0, el.scrollLeft + delta * 0.9));
      if (!rafId.current) rafId.current = requestAnimationFrame(animateToTarget);
    },
    [enabled]
  );

  const onWheel = useCallback(
    (e: ReactWheelEvent<HTMLElement>) => {
      handle(
        e.currentTarget,
        e.deltaX,
        e.deltaY,
        () => e.preventDefault(),
        () => e.stopPropagation()
      );
    },
    [handle]
  );

  useEffect(() => {
    if (!enabled || !node) return;
    const listener = (e: WheelEvent) => {
      handle(
        node,
        e.deltaX,
        e.deltaY,
        () => e.preventDefault(),
        () => e.stopPropagation()
      );
    };
    node.addEventListener('wheel', listener, { passive: false });
    return () => node.removeEventListener('wheel', listener);
  }, [enabled, handle, node]);

  useEffect(() => {
    if (!enabled) stop();
    return () => stop();
  }, [enabled]);

  const ref = useCallback((el: HTMLElement | null) => setNode(el), []);

  return { ref, onWheel };
}

export function getChunkLoadUserMessage(err: unknown): string | null {
  const msg = err instanceof Error ? err.message : String(err ?? '');
  if (
    msg.includes('Failed to fetch dynamically imported module') ||
    msg.includes('Importing a module script failed') ||
    msg.includes('dynamically imported module')
  ) {
    return 'Versi aplikasi di perangkat Anda sudah usang (biasanya setelah pembaruan situs). Muat ulang halaman untuk memuat file terbaru.';
  }
  return null;
}

export function getErrorMessage(err: any, fallback: string) {
  const chunkMsg = getChunkLoadUserMessage(err);
  if (chunkMsg) return chunkMsg;

  const status = err?.response?.status;
  const url = String(err?.response?.config?.url || '');
  const method = String(err?.response?.config?.method || '').toUpperCase();

  const errorCode = err?.response?.data?.error_code;
  if (typeof errorCode === 'string') {
    if (errorCode === 'MISSING_CREDENTIALS')
      return 'Sistem membutuhkan NIM dan kata sandi Anda untuk masuk. Mari lengkapi kolom yang kosong.';
    if (errorCode === 'INVALID_CREDENTIALS')
      return 'Data login tidak cocok dengan catatan kami. Silakan periksa kembali NIM dan kata sandi Anda.';
    if (errorCode === 'ACCOUNT_INACTIVE')
      return 'Akun Anda sedang dinonaktifkan demi keamanan. Silakan hubungi tim Admin untuk mengaktifkannya kembali.';
    if (errorCode === 'DEVICE_BOUND')
      return 'Sistem mendeteksi perangkat lain terhubung dengan akun Anda. Hubungi tim Admin untuk mengalihkan akun ke perangkat ini.';
    if (errorCode === 'BOLA_UNAUTHORIZED_CLASS')
      return 'Kode QR ini bukan untuk kelas Anda. Pastikan Anda memindai kode yang benar.';
    if (errorCode === 'SESSION_OUT_OF_SCOPE')
      return 'Sesi ini tidak termasuk dalam kelas yang Anda ampu.';
    if (errorCode === 'CLASS_OUT_OF_SCOPE') return 'Kelas ini di luar akses Anda.';
    if (errorCode === 'LOCATION_OUT_OF_SCOPE') return 'Lokasi ini di luar akses Anda.';
    if (errorCode === 'ADMIN_SESSION_REQUIRES_CLASS')
      return 'Untuk Admin, sesi harus terkait minimal 1 kelas.';
    if (errorCode === 'ADMIN_CANNOT_CHANGE_LECTURER')
      return 'Admin tidak dapat memindahkan kelas ke dosen lain.';
    if (
      errorCode === 'NO_REFRESH_TOKEN' ||
      errorCode === 'INVALID_REFRESH_TOKEN' ||
      errorCode === 'INVALID_USER'
    ) {
      return 'Sesi masuk Anda telah berakhir demi kenyamanan dan keamanan. Mari masuk kembali ke akun Anda.';
    }
  }

  const code = err?.code;
  if (
    !err?.response &&
    (code === 'ERR_NETWORK' ||
      String(err?.message || '')
        .toLowerCase()
        .includes('network'))
  ) {
    return 'Sistem kami sedang mengalami gangguan koneksi. Tenang, kami sedang memperbaikinya. Silakan segarkan halaman dalam beberapa saat.';
  }

  const value = err?.response?.data?.error ?? err?.response?.data?.message ?? err?.message ?? err;

  if (typeof value === 'string') {
    const raw = value.trim();
    const lowered = raw.toLowerCase();

    // Login 401 fallback
    if (status === 401 && method === 'POST' && url.includes('/auth/login')) {
      return 'Data login tidak cocok dengan catatan kami. Silakan periksa kembali NIM dan kata sandi Anda.';
    }
    if (
      lowered.includes('no token provided') ||
      lowered.includes('invalid or expired token') ||
      lowered.includes('invalid or expired refresh token')
    ) {
      return 'Sesi masuk Anda telah berakhir demi kenyamanan dan keamanan. Mari masuk kembali ke akun Anda.';
    }
    if (lowered.includes('too many requests') || lowered.includes('rate limit')) {
      return 'Permintaan dari perangkat Anda terlalu padat saat ini. Silakan tunggu sekitar 15 menit sebelum mencoba kembali.';
    }
    if (
      raw === 'Internal server error' ||
      lowered.includes('db_unavailable') ||
      lowered.includes('database') ||
      lowered.includes('prisma')
    ) {
      return 'Sistem kami sedang mengalami gangguan koneksi. Tenang, kami sedang memperbaikinya. Silakan segarkan halaman dalam beberapa saat.';
    }
    return raw;
  }
  if (value && typeof value === 'object') {
    const msg = (value as any).message;
    if (typeof msg === 'string' && msg.trim()) {
      const msgLower = msg.toLowerCase();
      if (msgLower.includes('too many requests') || msgLower.includes('rate limit')) {
        return 'Permintaan dari perangkat Anda terlalu padat saat ini. Silakan tunggu sekitar 15 menit sebelum mencoba kembali.';
      }
      if (
        msg === 'Internal server error' ||
        msgLower.includes('db_unavailable') ||
        msgLower.includes('database') ||
        msgLower.includes('prisma')
      ) {
        return 'Sistem kami sedang mengalami gangguan koneksi. Tenang, kami sedang memperbaikinya. Silakan segarkan halaman dalam beberapa saat.';
      }
      return msg;
    }
    try {
      return JSON.stringify(value);
    } catch {
      return fallback;
    }
  }
  if (status === 401)
    return 'Sesi masuk Anda telah berakhir demi kenyamanan dan keamanan. Mari masuk kembali ke akun Anda.';
  if (status === 403) return 'Anda tidak memiliki akses.';
  if (status === 404) return 'Data tidak ditemukan.';
  if (status === 413) return 'File terlalu besar. Maksimal 5MB.';
  if (status === 429)
    return 'Terlalu banyak percobaan dalam waktu singkat. Tunggu 1ΓÇô2 menit lalu coba lagi.';
  if (typeof status === 'number' && status >= 500)
    return 'Sistem kami sedang mengalami gangguan koneksi. Tenang, kami sedang memperbaikinya. Silakan segarkan halaman dalam beberapa saat.';
  return fallback;
}

