};

export default function Attend() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const sessionParam = searchParams.get('session');
  const tokenParam = searchParams.get('token');
  const isCheckoutMode = searchParams.get('checkout') === 'true'; // [UX] A-01, D-02
  const attendanceParam = searchParams.get('attendance');
  const NO_QR_TOKEN = 'NO_QR_REQUIRED';

  const [scanResult, setScanResult] = useState<string | null>(tokenParam);
  const [scanning, setScanning] = useState(!tokenParam);
  const [loading, setLoading] = useState(false);
  const [location, setLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);
  const [gpsError, setGpsError] = useState<string | null>(null);
  const [ipAddress, setIpAddress] = useState<string>('');
  const [isOffline, setIsOffline] = useState(!navigator.onLine);

  useEffect(() => {
    const handleBrowserOnline = () => setIsOffline(false);
    const handleBrowserOffline = () => setIsOffline(true);
    window.addEventListener('online', handleBrowserOnline);
    window.addEventListener('offline', handleBrowserOffline);
    return () => {
      window.removeEventListener('online', handleBrowserOnline);
      window.removeEventListener('offline', handleBrowserOffline);
    };
  }, []);

  // Camera state for photo evidence
  const [photoBlob, setPhotoBlob] = useState<Blob | null>(null);
  const [photoPreview, setPhotoPreview] = useState<string | null>(null);
  const videoRef = React.useRef<HTMLVideoElement>(null);
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const pendingStreamRef = React.useRef<MediaStream | null>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const scannerRef = React.useRef<Html5Qrcode | null>(null);
  const qrCameraIdRef = React.useRef<string | null>(null);
  const qrBootGenRef = React.useRef(0);
  type QrErrorType = 'PERMISSION' | 'SCAN_TIMEOUT' | 'BAD_SIG' | 'NOT_ENROLLED';
  const [qrError, setQrError] = useState<{ code: QrErrorType; detail?: string } | null>(null);
  const qrDecodeTimeoutRef = React.useRef<number | null>(null);
  const qrDecodedSuccessRef = React.useRef(false);
  const [camerasReady, setCamerasReady] = useState(false);
  const [qrBootNonce, setQrBootNonce] = useState(0);
  const isSubmittingRef = React.useRef(false);
  const [qrFacingMode, setQrFacingMode] = useState<'user' | 'environment'>('environment');
  const [submitError, setSubmitError] = useState<{ message: string; hint?: string } | null>(null);
  const [storageSaveFailed, setStorageSaveFailed] = useState(false);
  const storagePermanentlyFailedRef = React.useRef(false);

  const loadQrCamera = useCallback(async (preferRear: boolean) => {
    try {
      const cameras = await Html5Qrcode.getCameras();
      const preferredId = pickPreferredCameraId(
        cameras.map((c) => ({ id: c.id, label: c.label })),
        { preferRear }
      );
      qrCameraIdRef.current = preferredId;
    } catch {
      qrCameraIdRef.current = null;
      const msg = 'Kamera tidak diizinkan. Buka pengaturan browser.';
      setQrError({ code: 'PERMISSION' });
      toast.error(msg);
    } finally {
      setCamerasReady(true);
    }
  }, []);

  useEffect(() => {
    loadQrCamera(true);
  }, [loadQrCamera]);

  // Derived session ID from parameter or scan result
  const extractSessionIdAndToken = (rawResult: string | null) => {
    if (!rawResult) return { sid: sessionParam, tkn: tokenParam };

    try {
      // 1. Check if it's a URL
      if (rawResult.includes('http') || rawResult.includes('?session=')) {
        const urlObj = new URL(
          rawResult.startsWith('http') ? rawResult : `http://localhost${rawResult}`
        );
        const sid = urlObj.searchParams.get('session');
        const tkn = urlObj.searchParams.get('token');
        return { sid: sid || sessionParam, tkn: tkn || rawResult };
      }
    } catch (e) {
      // Not a valid URL, fallback
    }

    // 2. Check if it's a dynamic token string (sessionId:timestamp:signature)
    if (rawResult.includes(':') && rawResult.split(':').length === 3) {
      return { sid: rawResult.split(':')[0].trim(), tkn: rawResult.trim() };
    }

    // 3. Fallback: Assume it's a raw static token
    return { sid: sessionParam, tkn: rawResult.trim() };
  };

  const { sid: derivedSessionId, tkn: parsedToken } = extractSessionIdAndToken(scanResult);

  const [sessionDetails, setSessionDetails] = useState<any>(null);
  const [sessionLoading, setSessionLoading] = useState(Boolean(sessionParam && !tokenParam));
  const [sessionLoadError, setSessionLoadError] = useState<string | null>(null); // [UX] A-03
  const [myAttendance, setMyAttendance] = useState<Pick<
    Report,
    'id' | 'check_in_time' | 'session_title'
  > | null>(null);
  const [checkoutLoading, setCheckoutLoading] = useState(isCheckoutMode);
  const [checkoutError, setCheckoutError] = useState<string | null>(null);
  const [checkoutSubmitting, setCheckoutSubmitting] = useState(false);

  const sessionIdForLoad = isCheckoutMode ? sessionParam : derivedSessionId;

  const reloadSession = useCallback(async () => {
    if (!sessionIdForLoad || sessionIdForLoad === NO_QR_TOKEN) {
      setSessionLoading(false);
      return;
    }
    if (isOffline && !isCheckoutMode) {
      setSessionLoading(false);
      return;
    }

    setSessionLoading(true);
    setSessionLoadError(null);

    try {
      const res = await api.get(`/sessions/${sessionIdForLoad}`);
      const s = res.data.data;
      setSessionDetails(s);
      if (!isCheckoutMode && s.qr_mode === 'NONE') {
        setScanning(false);
        setScanResult(NO_QR_TOKEN);
      }
    } catch (err) {
      const msg = getErrorMessage(err, 'Gagal memuat data sesi absensi.');
      setSessionLoadError(msg);
      setSessionDetails(null);
    } finally {
      setSessionLoading(false);
    }
  }, [sessionIdForLoad, isCheckoutMode, isOffline]);

  useEffect(() => {
    void reloadSession();
  }, [reloadSession]);

  const reloadCheckout = useCallback(async () => {
    if (!isCheckoutMode || !sessionParam) return;
    setCheckoutLoading(true);
    setCheckoutError(null);
    try {
      const res = await api.get('/reports', { params: { sessionId: sessionParam, limit: 5 } });
      const rows: Report[] = res.data?.data ?? [];
      const match =
        rows.find((r) => r.id === attendanceParam) ??
        rows.find((r) => r.session_id === sessionParam) ??
        null;
      if (!match) {
        setCheckoutError('Data check-in tidak ditemukan. Pastikan Anda sudah absen di sesi ini.');
        setMyAttendance(null);
        return;
      }
      setMyAttendance({
        id: match.id,
        check_in_time: match.check_in_time,
        session_title: match.session_title,
      });
    } catch (err) {
      setCheckoutError(getErrorMessage(err, 'Gagal memuat data kehadiran Anda.'));
    } finally {
      setCheckoutLoading(false);
    }
  }, [isCheckoutMode, sessionParam, attendanceParam]);

  useEffect(() => {
    if (isCheckoutMode) void reloadCheckout();
  }, [isCheckoutMode, reloadCheckout]);

  useEffect(() => {
    const resumeAfterOnline = () => {
      setIsOffline(false);
      setSubmitError(null);
      toast.success(ONLINE_USER_MESSAGE, { id: 'attend-online' });
      void reloadSession();
      if (isCheckoutMode) void reloadCheckout();
    };
    window.addEventListener(APP_ONLINE_EVENT, resumeAfterOnline);
    return () => window.removeEventListener(APP_ONLINE_EVENT, resumeAfterOnline);
  }, [reloadSession, reloadCheckout, isCheckoutMode]);

  const handleCheckOut = async () => {
    if (!myAttendance?.id || checkoutSubmitting || isOffline) return;
    if (!location || !gpsAccuracy || gpsAccuracy <= 0) {
      toast.error('Menunggu lokasi GPS yang validΓÇª');
      return;
    }
    if (!photoBlob) {
      toast.error('Silakan ambil foto bukti check-out terlebih dahulu.');
      return;
    }
    const sessionId = sessionIdForLoad?.trim();
    if (!sessionId) {
      toast.error('Sesi tidak ditemukan.');
      return;
    }
    if (sessionDetails?.qr_mode && sessionDetails.qr_mode !== 'NONE' && !scanResult) {
      toast.error('Silakan scan QR Code terlebih dahulu.');
      return;
    }

    setCheckoutSubmitting(true);
    setCheckoutError(null);
    try {
      const { sid: _s, tkn: qrToken } = extractSessionIdAndToken(scanResult);
      const photoType = photoBlob.type || 'image/jpeg';
      const challengeRes = await api.get('/attendance/challenge', {
        params: {
          action: 'checkout',
          attendance_id: myAttendance.id,
          session_id: sessionId,
          latitude: location.lat,
          longitude: location.lng,
          accuracy: gpsAccuracy,
          photo_size: photoBlob.size,
          photo_type: photoType,
        },
      });
      const nonce = challengeRes.data?.data?.nonce;
      const signature = challengeRes.data?.data?.signature;
      if (!nonce || !signature) {
        throw new Error('Gagal mendapatkan security token dari server');
      }

      const deviceFingerprint = await getDeviceFingerprint();
      const formData = new FormData();
      if (qrToken && qrToken !== NO_QR_TOKEN) {
        formData.append('qr_token', qrToken);
      }
      formData.append('latitude', location.lat.toString());
      formData.append('longitude', location.lng.toString());
      formData.append('accuracy', gpsAccuracy.toString());
      formData.append('device_fingerprint', deviceFingerprint);
      formData.append('nonce', nonce);
      formData.append('signature', signature);
      formData.append('photo_size', photoBlob.size.toString());
      formData.append('photo_type', photoType);
      formData.append('photo', photoBlob, 'checkout.jpg');

      const res = await api.put(`/attendance/${myAttendance.id}/check-out`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      toast.success(res.data?.message || 'Check-out berhasil!');
      navigate('/dashboard');
    } catch (err) {
      const msg = getErrorMessage(err, 'Check-out gagal. Coba lagi.');
      setCheckoutError(msg);
      toast.error(msg);
    } finally {
      setCheckoutSubmitting(false);
    }
  };

  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');
  const [cameraPermissionError, setCameraPermissionError] = useState<string | null>(null);
  const [cameraStarting, setCameraStarting] = useState(false);

  useEffect(() => {
    fetch('https://api.ipify.org?format=json')
      .then((res) => res.json())
      .then((data) => setIpAddress(data.ip))
      .catch((err) => console.error('Gagal mengambil IP', err));
  }, []);

  const isSpoofedLocation = (pos: GeolocationPosition) => {
    // Basic heuristics for web-based fake GPS
    // 1. Extremely low accuracy that is highly unusual for real devices
    if (pos.coords.accuracy !== null && pos.coords.accuracy < 2) {
      return true;
    }
    // 2. Suspiciously round coordinates often seen in emulators
    if (pos.coords.latitude % 1 === 0 && pos.coords.longitude % 1 === 0) {
      return true;
    }
    return false;
  };

  const handlePosition = (pos: GeolocationPosition) => {
    if (isSpoofedLocation(pos)) {
      setGpsError('Terdeteksi aplikasi Fake GPS atau anomali lokasi.');
      toast.error('Lokasi ditolak: Terdeteksi aplikasi Fake GPS.');
      setLocation(null);
      return;
    }

    const acc = pos.coords.accuracy;
    setGpsAccuracy(acc);

    if (acc > 150) {
      setGpsError(`Akurasi lokasi terlalu rendah (${Math.round(acc)}m). Silakan ke area terbuka.`);
      toast.warning('Akurasi lokasi rendah. Cari tempat terbuka.');
      setLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
      return;
    }

    setLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
    setGpsError(null);
  };

  const requestLocationOnce = () => {
    if (!navigator.geolocation) {
      setGpsError('Browser tidak mendukung Geolocation');
      toast.error('Browser Anda tidak mendukung Geolocation.');
      return;
    }
    setGpsError(null);
    toast.loading('Meminta izin lokasi GPSΓÇª', { id: 'gps-loc' });
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        toast.dismiss('gps-loc');
        handlePosition(pos);
      },
      (err) => {
        toast.dismiss('gps-loc');
        setGpsError(err.message || 'Gagal mendapatkan lokasi GPS');
        toast.error('Gagal mendapatkan lokasi GPS. Pastikan izin lokasi aktif.');
      },
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
    );
  };

  const hasIpRestriction = Boolean(sessionDetails?.location?.ip_restriction_enabled);

  const isIpValid = () => {
    if (!hasIpRestriction) return true;
    return Boolean(ipAddress);
  };

  useEffect(() => {
    requestLocationOnce();
    if (!navigator.geolocation) return;

    const watchId = navigator.geolocation.watchPosition(
      handlePosition,
      (err) => {
        setGpsError(err.message || 'Gagal mendapatkan lokasi GPS');
      },
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
    );

    return () => {
      navigator.geolocation.clearWatch(watchId);
    };
  }, []);

  const releaseQrScanner = useCallback(async () => {
    const instance = scannerRef.current;
    if (instance) {
      try {
        if (instance.isScanning) {
          await instance.stop();
        }
        instance.clear();
      } catch {
        void 0;
      }
      scannerRef.current = null;
    }
    await waitForCameraRelease();
  }, []);

  useEffect(() => {
    if (!scanning || scanResult || !camerasReady) return;

    const bootGen = ++qrBootGenRef.current;
    let cancelled = false;
    qrDecodedSuccessRef.current = false;

    const clearQrTimeout = () => {
      if (qrDecodeTimeoutRef.current !== null) {
        window.clearTimeout(qrDecodeTimeoutRef.current);
        qrDecodeTimeoutRef.current = null;
      }
    };

    const bootScanner = async () => {
      setQrError(null);
      await waitForCameraRelease(350);
      if (cancelled || bootGen !== qrBootGenRef.current || scannerRef.current) return;

      const cameraConfig: string | MediaTrackConstraints = qrCameraIdRef.current
        ? qrCameraIdRef.current
        : { facingMode: qrFacingMode };

      const qr = new Html5Qrcode('qr-reader', {
        formatsToSupport: [Html5QrcodeSupportedFormats.QR_CODE],
        verbose: false,
      });

      try {
        await qr.start(
          cameraConfig,
          {
            fps: 10,
            qrbox: { width: 250, height: 250 },
            aspectRatio: 1.0,
            disableFlip: qrFacingMode === 'user',
          },
          async (decodedText) => {
            if (cancelled || bootGen !== qrBootGenRef.current) return;
            qrDecodedSuccessRef.current = true;
            clearQrTimeout();
            await releaseQrScanner();
            setScanResult(decodedText);
            setScanning(false);
          },
          () => {
            // Abaikan kegagalan scan berulang sampai QR terbaca
          }
        );
        if (cancelled || bootGen !== qrBootGenRef.current) {
          try {
            if (qr.isScanning) await qr.stop();
            qr.clear();
          } catch {
            void 0;
          }
          return;
        }
        scannerRef.current = qr;

        qrDecodeTimeoutRef.current = window.setTimeout(() => {
          if (cancelled || bootGen !== qrBootGenRef.current) return;
          if (qrDecodedSuccessRef.current) return;
          const msg =
            'Tidak dapat membaca kode. Pastikan QR berada di tengah layar dan cahaya cukup.';
          setQrError({ code: 'SCAN_TIMEOUT' });
          toast.error(msg);
          void (async () => {
            try {
              if (qr.isScanning) await qr.stop();
              qr.clear();
            } catch {
              void 0;
            }
            if (scannerRef.current === qr) {
              scannerRef.current = null;
            }
          })();
        }, 15000);
      } catch (err) {
        clearQrTimeout();
        const msg = 'Kamera tidak diizinkan. Buka pengaturan browser.';
        setQrError({ code: 'PERMISSION' });
        toast.error(msg);
        try {
          qr.clear();
        } catch {
          void 0;
        }
      }
    };

    void bootScanner();

    return () => {
      cancelled = true;
      clearQrTimeout();
      qrBootGenRef.current += 1;
      const instance = scannerRef.current;
      scannerRef.current = null;
      if (instance) {
        void (async () => {
          try {
            if (instance.isScanning) await instance.stop();
            instance.clear();
          } catch {
            void 0;
          }
          await waitForCameraRelease(200);
        })();
      }
    };
  }, [scanning, scanResult, camerasReady, qrFacingMode, qrBootNonce, releaseQrScanner]);

  const switchQrCamera = async () => {
    const nextMode = qrFacingMode === 'environment' ? 'user' : 'environment';
    await releaseQrScanner();
    setQrFacingMode(nextMode);
    await loadQrCamera(nextMode === 'environment');
    setScanResult(null);
    setQrError(null);
    setScanning(true);
    setQrBootNonce((n) => n + 1);
  };

  const stopCamera = () => {
    // Release any pending stream that hasn't been assigned yet
    if (pendingStreamRef.current) {
      releaseMediaStream(pendingStreamRef.current);
      pendingStreamRef.current = null;
    }
    if (videoRef.current?.srcObject) {
      releaseMediaStream(videoRef.current.srcObject as MediaStream);
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
  };

  // When isCameraActive flips to true, assign the pending stream to the <video>
  // after the DOM has painted (requestAnimationFrame). This avoids the mobile
  // Android Chrome bug where play() on a display:none element skips decoder init.
  useEffect(() => {
    if (isCameraActive && pendingStreamRef.current && videoRef.current) {
      const stream = pendingStreamRef.current;
      pendingStreamRef.current = null;
      requestAnimationFrame(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.play().catch(() => undefined);
        }
      });
    }
  }, [isCameraActive]);

  // Cleanup saat unmount: lepas video camera DAN QR scanner
  // Tanpa ini, Html5Qrcode tetap memegang hardware kamera setelah navigasi,
  // sehingga halaman lain (misal Excuses) mendapat error "camera already in use".
  useEffect(() => {
    return () => {
      // 1. Lepas video camera
      stopCamera();

      // 2. Lepas QR scanner ΓÇö Html5Qrcode punya MediaStream tersendiri
      //    yang TIDAK dibersihkan oleh stopCamera().
      //    Kita bungkus proses async ini dalam Promise dan mendaftarkannya
      //    secara global agar halaman lain (Excuses) bisa menunggunya
      //    sebelum membuka kamera baru.
      const instance = scannerRef.current;
      scannerRef.current = null;

      const teardown = (async () => {
        if (instance) {
          try {
            if (instance.isScanning) await instance.stop();
            instance.clear();
          } catch {
            void 0;
          }
        }
        // Force-stop any remaining tracks after the library finishes
        await releaseActiveVideoTracks();
        // Extra settle time so hardware is truly released
        await new Promise<void>((r) => setTimeout(r, 300));
      })();

      // Register so acquireCameraStream() can await this before opening
      registerPendingCameraRelease(teardown);
    };
  }, []);

  const startCamera = useCallback(
    async (mode = facingMode) => {
      setCameraStarting(true);
      setCameraPermissionError(null);
      try {
        stopCamera();
        if (scannerRef.current) {
          await releaseQrScanner();
        } else {
          await waitForCameraRelease(400);
        }

        let lastErr: unknown;
        for (let attempt = 0; attempt < 4; attempt++) {
          if (attempt > 0) {
            await waitForCameraRelease(700 + attempt * 350);
          }
          try {
            const stream = await acquireCameraStream({
              facingMode: mode,
              preferRear: mode === 'environment',
            });
            // Store stream in ref ΓÇö the useEffect watching isCameraActive will
            // assign it to the <video> after React re-renders and the element
            // is visible (no longer display:none).
            pendingStreamRef.current = stream;
            setIsCameraActive(true);
            return;
          } catch (err) {
            lastErr = err;
          }
        }

        const msg = humanizeCameraError(lastErr);
        setCameraPermissionError(msg);
        toast.error(msg);
      } finally {
        setCameraStarting(false);
      }
    },
    [facingMode, releaseQrScanner]
  );

  const switchCamera = () => {
    const newMode = facingMode === 'user' ? 'environment' : 'user';
    setFacingMode(newMode);
    if (isCameraActive) {
      startCamera(newMode);
    }
  };

  const takePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      // Calculate scaled dimensions to prevent massive payloads
      const MAX_WIDTH = 800;
      let width = video.videoWidth;
      let height = video.videoHeight;

      if (width > MAX_WIDTH) {
        height = Math.round((height * MAX_WIDTH) / width);
        width = MAX_WIDTH;
      }

      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Balik canvas secara horizontal jika menggunakan kamera depan agar hasil foto tidak mirror (sama dengan yang dilihat user)
        if (facingMode === 'user') {
          ctx.translate(canvas.width, 0);
          ctx.scale(-1, 1);
        }

        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

        // Kembalikan transformasi sebelum menulis teks agar teks tidak terbalik
        if (facingMode === 'user') {
          ctx.translate(canvas.width, 0);
          ctx.scale(-1, 1);
        }

        // Add watermark
        ctx.font = '14px Arial';
        ctx.fillStyle = 'yellow';
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 4;
        ctx.fillText(`${new Date().toLocaleString()}`, 10, canvas.height - 30);
        if (location) {
          ctx.fillText(
            `Lat: ${location.lat.toFixed(5)}, Lng: ${location.lng.toFixed(5)}`,
            10,
            canvas.height - 10
          );
        }
        ctx.shadowBlur = 0; // reset

        canvas.toBlob(
          (blob) => {
            if (blob) {
              setPhotoBlob(blob);
              setPhotoPreview(URL.createObjectURL(blob));
              stopCamera();
            }
          },
          'image/jpeg',
          0.7
        ); // Compress to 70% quality
      }
    }
  };

  const retakePhoto = () => {
    setPhotoBlob(null);
    setPhotoPreview(null);
    startCamera();
  };

  const handleCheckIn = async () => {
    if (isSubmittingRef.current) return;
    if (gpsError) {
      toast.error(`GPS bermasalah: ${gpsError}`);
      return;
    }
    if (!scanResult) {
      toast.error('Silakan scan QR Code terlebih dahulu.');
      return;
    }
    if (!location) {
      toast.error('Menunggu lokasi GPS...');
      return;
    }
    if (!gpsAccuracy || gpsAccuracy <= 0) {
      toast.error('Menunggu akurasi GPS yang valid...');
      return;
    }
    // We require photo evidence for this iteration as requested
    if (!photoBlob) {
      toast.error('Silakan ambil foto bukti terlebih dahulu.');
      return;
    }

    isSubmittingRef.current = true;
    setLoading(true);
    setSubmitError(null); // [UX] bersihkan error sebelum percobaan baru
    try {
      let sessionId = derivedSessionId;
      const qrToken = parsedToken;

      if (!sessionId) {
        throw new Error('Sesi tidak ditemukan dalam QR Code atau URL.');
      }

      // Bersihkan whitespace jika ada (misal dari hasil scan)
      sessionId = sessionId.trim();

      const deviceFingerprint = await getDeviceFingerprint();

      if (isOffline) {
        if (storagePermanentlyFailedRef.current) {
          toast.error('Penyimpanan foto gagal.');
          setStorageSaveFailed(true);
          return;
        }
        let offlineId: number | null = null;
        try {
          offlineId = await saveOfflineAttendance({
            session_id: sessionId,
            token: qrToken && qrToken !== NO_QR_TOKEN ? qrToken : undefined,
            lat: location.lat,
            lng: location.lng,
            accuracy: gpsAccuracy,
            deviceInfo: deviceFingerprint,
          });
          if (photoBlob) {
            await saveOfflinePhoto(offlineId, photoBlob);
          } else {
            throw new Error('Foto bukti tidak tersedia untuk simpan offline.');
          }
        } catch (storageErr) {
          console.error('Offline storage failed', storageErr);
          if (offlineId !== null) {
            try {
              await deleteOfflineAttendance(offlineId);
            } catch (cleanupErr) {
              console.error(
                'Failed to rollback queued attendance after photo save failure',
                cleanupErr
              );
            }
          }
          storagePermanentlyFailedRef.current = true;
          setStorageSaveFailed(true);
          toast.error('Penyimpanan foto gagal.');
          return;
        }
        toast.success('Tersimpan offline. Akan terkirim otomatis saat internet kembali.');
        navigate('/dashboard');
        return;
      }

      // --- ANTI-CHEAT LAYER 2: Request server-signed one-time proof ---
      const photoType = photoBlob.type || 'image/jpeg';
      const challengeRes = await api.get('/attendance/challenge', {
        params: {
          action: 'checkin',
          session_id: sessionId,
          latitude: location.lat,
          longitude: location.lng,
          accuracy: gpsAccuracy,
          photo_size: photoBlob.size,
          photo_type: photoType,
        },
      });
      const nonce = challengeRes.data?.data?.nonce;
      const signature = challengeRes.data?.data?.signature;
      if (!nonce || !signature) {
        throw new Error('Gagal mendapatkan security token dari server');
      }

      const formData = new FormData();
      formData.append('session_id', sessionId);
      if (qrToken && qrToken !== NO_QR_TOKEN) {
        formData.append('qr_token', qrToken);
      }
      formData.append('latitude', location.lat.toString());
      formData.append('longitude', location.lng.toString());
      formData.append('accuracy', (gpsAccuracy || 0).toString());
      formData.append('ip_address', ipAddress);
      formData.append('device_fingerprint', deviceFingerprint);
      formData.append('nonce', nonce);
      formData.append('signature', signature);
      formData.append('photo_size', photoBlob.size.toString());
      formData.append('photo_type', photoType);

      if (photoBlob) {
        formData.append('photo', photoBlob, 'attendance.jpg');
      }

      const res = await api.post('/attendance/check-in', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });

      toast.success(res.data.message || 'Check-in berhasil!');
      track('checkin_success');
      navigate('/dashboard');
    } catch (error: unknown) {
      const apiMsg = getErrorMessage(error, 'Absensi gagal dikirim');
      const lower = apiMsg.toLowerCase();
      const isBadSigQrError =
        lower.includes('qr') ||
        lower.includes('token') ||
        lower.includes('kadaluwarsa') ||
        lower.includes('signature') ||
        lower.includes('nonce') ||
        lower.includes('tidak valid') ||
        lower.includes('security proof');
      const isNotEnrolled = lower.includes('terdaftar di kelas');

      if (isNotEnrolled) {
        const code = derivedSessionId || '-';
        const notEnrolledMsg = `Anda tidak terdaftar di sesi ini (Kode: ${code}). Pindai kode sesi aktif Anda.`;
        setScanResult(null);
        setScanning(true);
        setPhotoBlob(null);
        setPhotoPreview(null);
        setQrError({ code: 'NOT_ENROLLED', detail: code });
        toast.error(notEnrolledMsg);
      } else if (isBadSigQrError) {
        const badSigMsg = 'Kode QR tidak valid atau sudah digunakan.';
        setScanResult(null);
        setScanning(true);
        setPhotoBlob(null);
        setPhotoPreview(null);
        setQrError({ code: 'BAD_SIG' });
        setSubmitError({
          message: badSigMsg,
          hint: 'Scan ulang QR Code dari layar dosen, lalu lanjutkan langkah berikutnya.',
        });
        toast.error(badSigMsg);
      } else {
        setSubmitError({
          message: apiMsg,
          hint: 'Periksa koneksi internet atau lokasi GPS, lalu tekan "Coba kirim lagi" tanpa mengulang dari awal.',
        });
        toast.error(apiMsg);
      }
    } finally {
      setLoading(false);
      isSubmittingRef.current = false;
    }
  };

  const isLocationValid = () => {
    if (!location || !sessionDetails?.location) return false;
    const dist = getDistanceMeters(location, {
      lat: sessionDetails.location.latitude,
      lng: sessionDetails.location.longitude,
    });
    return dist <= sessionDetails.location.radius;
  };

  const ipStatusLabel = () => {
    if (!hasIpRestriction) return 'Tidak diwajibkan';
    if (!ipAddress) return 'MemuatΓÇª';
    return 'Dicek server saat kirim';
  };

  const actionOverlayLabel = loading
    ? 'Mengirim data absensiΓÇª'
    : checkoutSubmitting
      ? 'Memproses check-outΓÇª'
      : sessionLoading
        ? 'Memuat data sesiΓÇª'
        : checkoutLoading
          ? 'Memuat data check-outΓÇª'
          : null;

  // [UX] A-03 ΓÇö halaman error penuh saat sesi gagal dimuat
  if (sessionLoadError && (sessionParam || isCheckoutMode)) {
    return (
      <div className="mx-auto flex min-h-[calc(100vh-4rem)] max-w-lg flex-col items-center justify-center p-6 text-center">
        <AlertCircle className="mb-4 size-12 text-red-500" aria-hidden="true" />
        <h1 className="text-xl font-bold text-foreground">Gagal memuat sesi</h1>
        <p className="mt-2 text-sm text-muted-foreground" role="alert">
          {sessionLoadError}
        </p>
        <div className="mt-6 flex flex-col gap-3 sm:flex-row">
          <Button
            type="button"
            className="min-h-11"
            onClick={() => {
              setSessionLoadError(null);
              setSessionLoading(true);
              const sid = sessionIdForLoad;
              if (!sid) return;
              api
                .get(`/sessions/${sid}`)
                .then((res) => {
                  setSessionDetails(res.data.data);
                  setSessionLoadError(null);
                })
                .catch((err) =>
                  setSessionLoadError(getErrorMessage(err, 'Gagal memuat data sesi absensi.'))
                )
                .finally(() => setSessionLoading(false));
            }}
          >
            Muat ulang
          </Button>
          <Button
            type="button"
            variant="outline"
            className="min-h-11"
            onClick={() => navigate('/dashboard')}
          >
            Kembali ke dashboard
          </Button>
        </div>
      </div>
    );
  }

  if (isCheckoutMode) {
    return (
      <>
        <ActionLoadingOverlay show={!!actionOverlayLabel} label={actionOverlayLabel ?? ''} />
        <div className="mx-auto min-h-[calc(100vh-4rem)] max-w-3xl px-4 py-6 sm:px-6 sm:py-8">
          <div className="mb-8 space-y-2">
            <h1 className="text-2xl font-bold text-foreground">Check-out Kehadiran</h1>
            <p className="text-muted-foreground">
              Konfirmasi untuk menyelesaikan kehadiran di sesi ini.
            </p>
          </div>

          <div className="flex flex-1 flex-col overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-card">
            {isOffline && (
              <div
                className="flex items-center justify-center gap-2 bg-amber-100 p-3 text-center text-sm font-medium text-amber-900"
                role="status"
              >
                <WifiOff size={16} aria-hidden="true" />
                {OFFLINE_USER_MESSAGE}
              </div>
            )}

            {checkoutLoading || sessionLoading ? (
              <div
                className="flex flex-1 flex-col items-center justify-center gap-3 p-10"
                aria-busy="true"
              >
                <div className="size-10 animate-spin rounded-full border-4 border-indigo-200 border-t-indigo-600" />
                <p className="text-sm text-muted-foreground">Memuat dataΓÇª</p>
              </div>
            ) : checkoutError || !myAttendance ? (
              <div className="p-6" role="alert">
                <p className="font-semibold text-red-800 dark:text-red-300">
                  {checkoutError || 'Data check-in tidak ditemukan.'}
                </p>
                <Button
                  type="button"
                  variant="outline"
                  className="mt-4 min-h-11 w-full"
                  onClick={() => navigate('/dashboard')}
                >
                  Kembali ke dashboard
                </Button>
              </div>
            ) : (
              <div className="flex flex-1 flex-col gap-6 p-6 sm:p-8">
                <div className="space-y-4 text-center">
                  <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    Kelas / Sesi
                  </p>
                  <p className="text-lg font-bold text-foreground">
                    {sessionDetails?.title || myAttendance.session_title}
                  </p>
                  <p className="text-base font-medium text-brand">
                    Check-in:{' '}
                    {format(new Date(myAttendance.check_in_time), 'dd MMM yyyy ┬╖ HH:mm', {
                      locale: idLocale,
                    })}{' '}
                    WIB
                  </p>
                </div>
                {sessionDetails?.qr_mode && sessionDetails.qr_mode !== 'NONE' && !scanResult ? (
                  <p className="text-center text-sm text-amber-700 dark:text-amber-400">
                    Scan QR sesi terlebih dahulu (sama seperti check-in).
                  </p>
                ) : null}
                <div className="relative mx-auto aspect-[3/4] w-full max-w-sm overflow-hidden rounded-xl bg-muted">
                  {photoPreview ? (
                    <img
                      src={photoPreview}
                      alt="Pratinjau foto check-out"
                      className="size-full object-cover"
                    />
                  ) : (
                    <video
                      ref={videoRef}
                      autoPlay
                      playsInline
                      muted
                      className="size-full object-cover"
                    />
                  )}
                  <canvas ref={canvasRef} className="hidden" />
                </div>
                <div className="flex flex-col gap-3">
                  {!photoPreview && !isCameraActive ? (
                    <Button
                      type="button"
                      className="w-full"
                      disabled={cameraStarting}
                      onClick={() => void startCamera()}
                    >
                      {cameraStarting ? 'Menyiapkan kameraΓÇª' : 'Buka Kamera'}
                    </Button>
                  ) : null}
                  {!photoPreview && isCameraActive ? (
                    <Button type="button" className="w-full" onClick={takePhoto}>
                      Ambil Foto Check-out
                    </Button>
                  ) : null}
                  {photoPreview ? (
                    <Button
                      type="button"
                      variant="outline"
                      className="w-full"
                      onClick={retakePhoto}
                    >
                      Ambil Ulang Foto
                    </Button>
                  ) : null}
                  <Button
                    type="button"
                    size="lg"
                    className="w-full py-6 text-lg font-bold"
                    onClick={() => void handleCheckOut()}
                    disabled={
                      checkoutSubmitting ||
                      isOffline ||
                      !photoBlob ||
                      !location ||
                      !isLocationValid()
                    }
                    aria-busy={checkoutSubmitting}
                  >
                    {checkoutSubmitting ? (
                      <Loader2 className="mr-2 size-5 animate-spin" aria-hidden="true" />
                    ) : (
                      <LogOut size={20} className="mr-2" aria-hidden="true" />
                    )}
                    {checkoutSubmitting ? 'MemprosesΓÇª' : 'Kirim Check-out'}
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    className="min-h-11 w-full"
                    disabled={checkoutSubmitting}
                    onClick={() => navigate('/dashboard')}
                  >
                    Batal
                  </Button>
                </div>
                {checkoutError ? (
                  <p className="text-center text-sm text-red-600 dark:text-red-400" role="alert">
                    {checkoutError}
                  </p>
                ) : null}
              </div>
            )}
          </div>
        </div>
      </>
    );
  }

  return (
    <>
      <ActionLoadingOverlay show={!!actionOverlayLabel} label={actionOverlayLabel ?? ''} />
      <div className="mx-auto min-h-[calc(100vh-4rem)] max-w-3xl px-4 py-6 sm:px-6 sm:py-8">
        <div className="mb-8 space-y-2">
          <h1 className="text-2xl font-bold text-foreground">Check-in Kehadiran</h1>
          <p className="text-sm text-muted-foreground">
            Scan QR Code kelas dan pastikan Anda berada di lokasi.
          </p>
        </div>

        <AttendPrivacyBanner />

        <div className="flex flex-1 flex-col overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-card">
          {isOffline && (
            <div
              className="flex items-center justify-center gap-2 bg-amber-100 p-3 text-center text-sm font-medium text-amber-900"
              role="status"
            >
              <WifiOff size={16} aria-hidden="true" />
              {OFFLINE_USER_MESSAGE}
            </div>
          )}

          {submitError && (
            <div
              className="mx-5 mt-5 rounded-xl border border-red-200 bg-red-50 p-5 dark:border-red-900/50 dark:bg-red-950/40"
              role="alert"
              aria-live="assertive"
            >
              <div className="flex gap-3">
                <AlertCircle className="mt-0.5 size-5 shrink-0 text-red-600" aria-hidden="true" />
                <div className="min-w-0 flex-1">
                  <p className="font-semibold text-red-800 dark:text-red-300">
                    {submitError.message}
                  </p>
                  {submitError.hint ? (
                    <p className="mt-1 text-sm text-red-700 dark:text-red-400">
                      {submitError.hint}
                    </p>
                  ) : null}
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    className="mt-3 min-h-11 border-red-300"
                    onClick={() => {
                      setSubmitError(null);
                      void handleCheckIn();
                    }}
                    disabled={loading}
                  >
                    Coba kirim lagi
                  </Button>
                </div>
              </div>
            </div>
          )}

          {/* Status Indicators */}
          <div className="grid grid-cols-2 divide-x divide-y divide-border border-b border-border bg-muted/40 md:grid-cols-4 md:divide-y-0">
            <div className="flex flex-col items-center gap-2 p-5 text-center">
              <QrCode
                className={
                  scanResult ? 'text-green-600 dark:text-green-400' : 'text-muted-foreground'
                }
                size={24}
                aria-hidden="true"
              />
              <span className="text-xs font-medium text-muted-foreground">QR Code</span>
              <span className="text-xs font-semibold text-foreground">
                {sessionDetails?.qr_mode === 'NONE'
                  ? 'Tidak Perlu'
                  : scanResult
                    ? 'Terscan'
                    : 'Menunggu'}
              </span>
            </div>
            <div className="flex flex-col items-center gap-2 p-5 text-center">
              <MapPin
                className={
                  !location
                    ? 'text-amber-600 animate-pulse dark:text-amber-400'
                    : isLocationValid()
                      ? 'text-green-600 dark:text-green-400'
                      : 'text-red-600 dark:text-red-400'
                }
                size={24}
                aria-hidden="true"
              />
              <span className="text-xs font-medium text-muted-foreground">GPS Lokasi</span>
              <span className="text-xs font-semibold text-foreground">
                {!location
                  ? gpsError
                    ? 'Error'
                    : 'MencariΓÇª'
                  : isLocationValid()
                    ? 'Akurat'
                    : 'Di Luar Radius'}
              </span>
            </div>
            <div className="flex flex-col items-center gap-2 p-5 text-center">
              <ShieldAlert
                className={
                  !ipAddress
                    ? 'text-muted-foreground'
                    : isIpValid()
                      ? 'text-green-600 dark:text-green-400'
                      : 'text-red-600 dark:text-red-400'
                }
                size={24}
                aria-hidden="true"
              />
              <span className="text-xs font-medium text-muted-foreground">IP Validasi</span>
              <span className="text-xs font-semibold text-foreground">{ipStatusLabel()}</span>
            </div>
            <div className="flex flex-col items-center gap-2 p-5 text-center">
              <Camera
                className={
                  photoBlob
                    ? 'text-green-600 dark:text-green-400'
                    : cameraStarting
                      ? 'text-brand animate-pulse'
                      : 'text-amber-600 dark:text-amber-400'
                }
                size={24}
                aria-hidden="true"
              />
              <span className="text-xs font-medium text-muted-foreground">Foto Bukti</span>
              <span className="text-xs font-semibold text-foreground">
                {photoBlob ? 'Tersimpan' : cameraStarting ? 'MenyiapkanΓÇª' : 'Menunggu'}
              </span>
            </div>
          </div>

          {(cameraPermissionError || gpsError) && (
            <div
              className="mx-4 mt-4 rounded-xl border border-red-200 bg-red-50 p-4 dark:border-red-900/50 dark:bg-red-950/40 sm:mx-6"
              role="alert"
              aria-live="assertive"
            >
              <div className="flex gap-3">
                <AlertCircle className="mt-0.5 size-5 shrink-0 text-red-600" aria-hidden="true" />
                <div className="min-w-0 space-y-1">
                  <p className="font-semibold text-red-800 dark:text-red-300">
                    Perlu perbaikan sebelum absen
                  </p>
                  {gpsError ? (
                    <p className="text-sm text-red-700 dark:text-red-400">GPS: {gpsError}</p>
                  ) : null}
                  {cameraPermissionError ? (
                    <p className="text-sm text-red-700 dark:text-red-400">
                      Kamera: {cameraPermissionError}
                    </p>
                  ) : null}
                </div>
              </div>
            </div>
          )}

          <div className="flex flex-1 flex-col gap-8 p-5 sm:p-8">
            {location && sessionDetails?.location && (
              <div className="z-0 h-52 w-full overflow-hidden rounded-xl border border-border shadow-inner border-border">
                <MapContainer
                  center={[location.lat, location.lng]}
                  zoom={16}
                  style={{ height: '100%', width: '100%' }}
                  scrollWheelZoom={false}
                >
                  <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                  <MapUpdater center={[location.lat, location.lng]} />

                  <Marker position={[location.lat, location.lng]}>
                    <Popup>Lokasi Anda Saat Ini</Popup>
                  </Marker>

                  {sessionDetails?.location && (
                    <Circle
                      center={[sessionDetails.location.latitude, sessionDetails.location.longitude]}
                      radius={sessionDetails.location.radius}
                      pathOptions={{
                        color: isLocationValid() ? 'green' : 'red',
                        fillColor: isLocationValid() ? 'green' : 'red',
                        fillOpacity: 0.2,
                      }}
                    >
                      <Popup>Area Absensi ({sessionDetails.location.radius}m)</Popup>
                    </Circle>
                  )}
                </MapContainer>
              </div>
            )}

            <div className="flex flex-1 flex-col items-center justify-center">
              {scanning ? (
                <div className="attend-qr-root w-full max-w-md">
                  <div className="relative overflow-hidden rounded-2xl border-4 border-border bg-slate-900 shadow-2xl border-border">
                    <div className="pointer-events-none absolute inset-0 z-10 m-8 rounded-xl border-[3px] border-dashed border-indigo-500/50" />
                    <div id="qr-reader" className="min-h-[300px] w-full bg-black" />
                  </div>
                  <div className="mt-8 space-y-4 text-center">
                    {qrError ? (
                      <div
                        className="rounded-xl border border-red-200 bg-red-50 p-4 text-left text-sm text-red-800 dark:border-red-900/50 dark:bg-red-950/40 dark:text-red-300"
                        role="alert"
                        aria-live="assertive"
                      >
                        <p className="font-semibold">
                          {qrError.code === 'PERMISSION' && 'Kamera tidak diizinkan'}
                          {qrError.code === 'SCAN_TIMEOUT' && 'Tidak dapat membaca kode QR'}
                          {qrError.code === 'BAD_SIG' && 'Kode QR tidak valid'}
                          {qrError.code === 'NOT_ENROLLED' && 'Tidak terdaftar di sesi ini'}
                        </p>
                        <p className="mt-1">
                          {qrError.code === 'PERMISSION' &&
                            'Kamera tidak diizinkan. Buka pengaturan browser.'}
                          {qrError.code === 'SCAN_TIMEOUT' &&
                            'Tidak dapat membaca kode. Pastikan QR berada di tengah layar dan cahaya cukup.'}
                          {qrError.code === 'BAD_SIG' &&
                            'Kode QR tidak valid atau sudah digunakan.'}
                          {qrError.code === 'NOT_ENROLLED' &&
                            `Anda tidak terdaftar di sesi ini (Kode: ${qrError.detail ?? '-'}). Pindai kode sesi aktif Anda.`}
                        </p>
                        <Button
                          type="button"
                          variant="outline"
                          size="sm"
                          className="mt-3 min-h-11"
                          onClick={() => {
                            void releaseQrScanner().then(() => {
                              setQrError(null);
                              setScanning(true);
                              setQrBootNonce((n) => n + 1);
                            });
                          }}
                        >
                          Coba Lagi
                        </Button>
                      </div>
                    ) : (
                      <p className="text-sm font-medium text-muted-foreground">
                        Arahkan kamera ke QR Code yang ditampilkan oleh Dosen.
                      </p>
                    )}
                    <div className="flex justify-center">
                      <Button
                        type="button"
                        variant="outline"
                        onClick={() => void switchQrCamera()}
                        className="min-h-11 gap-2"
                      >
                        <RefreshCw size={16} aria-hidden="true" />
                        Kamera QR {qrFacingMode === 'environment' ? 'Belakang' : 'Depan'}
                      </Button>
                    </div>
                  </div>
                </div>
              ) : !photoBlob ? (
                <div className="flex w-full max-w-md animate-in flex-col items-center gap-6 duration-300 zoom-in">
                  <h2 className="text-center text-xl font-bold text-foreground">
                    Ambil Foto Bukti Kehadiran
                  </h2>

                  <div className="relative flex aspect-video w-full items-center justify-center overflow-hidden rounded-2xl border border-border bg-black shadow-inner border-border">
                    <video
                      ref={videoRef}
                      autoPlay
                      playsInline
                      muted
                      className={`w-full h-full object-cover absolute inset-0 z-10 ${isCameraActive ? 'block' : 'hidden'} ${facingMode === 'user' ? 'scale-x-[-1]' : ''} pointer-events-none`}
                    ></video>

                    {!isCameraActive && (
                      <div className="relative z-20 flex flex-col items-center justify-center gap-3 p-6 text-center text-muted-foreground">
                        {cameraStarting ? (
                          <Loader2
                            className="size-10 animate-spin text-indigo-500"
                            aria-hidden="true"
                          />
                        ) : (
                          <Camera size={48} className="opacity-50" aria-hidden="true" />
                        )}
                        <p className="max-w-xs text-sm leading-relaxed">
                          {cameraStarting
                            ? 'Menyiapkan kameraΓÇª Izinkan akses jika diminta browser.'
                            : cameraPermissionError
                              ? cameraPermissionError
                              : 'Ketuk tombol di bawah untuk membuka kamera.'}
                        </p>
                      </div>
                    )}
                    <canvas ref={canvasRef} className="hidden"></canvas>
                  </div>

                  <div className="relative z-10 flex w-full flex-col justify-center gap-3 sm:flex-row">
                    {!isCameraActive ? (
                      <Button
                        type="button"
                        className="min-h-11 w-full gap-2 sm:w-auto"
                        disabled={cameraStarting}
                        onClick={() => void startCamera()}
                      >
                        {cameraStarting ? (
                          <Loader2 size={20} className="animate-spin" aria-hidden="true" />
                        ) : (
                          <Camera size={20} aria-hidden="true" />
                        )}
                        {cameraStarting ? 'MenyiapkanΓÇª' : 'Buka Kamera'}
                      </Button>
                    ) : (
                      <>
                        <Button
                          type="button"
                          variant="secondary"
                          className="min-h-11 w-full gap-2 sm:w-auto"
                          onClick={() => switchCamera()}
                        >
                          <RefreshCw size={20} aria-hidden="true" />
                          Kamera {facingMode === 'user' ? 'Depan' : 'Belakang'}
                        </Button>
                        <Button
                          type="button"
                          className="min-h-11 w-full gap-2 bg-emerald-600 hover:bg-emerald-700 sm:w-auto"
                          onClick={() => takePhoto()}
                        >
                          <Camera size={20} aria-hidden="true" />
                          Ambil Foto
                        </Button>
                      </>
                    )}
                  </div>
                </div>
              ) : (
                <div className="flex w-full max-w-md animate-in flex-col items-center gap-6 duration-300 zoom-in">
                  <div className="aspect-video w-full overflow-hidden rounded-2xl border border-border shadow-md border-border">
                    <img
                      src={photoPreview!}
                      alt="Bukti Kehadiran"
                      className="w-full h-full object-cover"
                    />
                  </div>

                  <div className="space-y-2 px-2 text-center">
                    <h2 className="text-xl font-bold text-foreground">Data Siap Dikirim</h2>
                    <p className="text-sm leading-relaxed text-muted-foreground">
                      Sistem telah mendapatkan token QR, lokasi GPS, foto bukti, dan informasi
                      perangkat Anda.
                    </p>
                  </div>

                  <div className="w-full space-y-4">
                    <Button
                      size="lg"
                      onClick={handleCheckIn}
                      disabled={
                        loading || !location || !!gpsError || storagePermanentlyFailedRef.current
                      }
                      className="w-full py-6 text-lg font-bold shadow-lg shadow-indigo-200 dark:shadow-indigo-900/20"
                      aria-busy={loading}
                    >
                      {loading ? (
                        <>
                          <Loader2 className="mr-2 size-5 animate-spin" aria-hidden="true" />
                          Mengirim absensiΓÇª
                        </>
                      ) : (
                        'Kirim Data Absensi'
                      )}
                    </Button>
                    <div className="grid grid-cols-2 gap-3">
                      <Button
                        variant="outline"
                        size="lg"
                        onClick={retakePhoto}
                        disabled={loading}
                        className="w-full font-bold"
                      >
                        <Camera size={18} className="mr-2" /> Ulang Foto
                      </Button>
                      <Button
                        variant="outline"
                        size="lg"
                        onClick={() => {
                          stopCamera();
                          setPhotoBlob(null);
                          setPhotoPreview(null);
                          if (sessionDetails?.qr_mode === 'NONE') {
                            setScanResult(NO_QR_TOKEN);
                            setScanning(false);
                          } else {
                            setScanResult(null);
                            void releaseQrScanner().then(() => {
                              setScanning(true);
                              setQrBootNonce((n) => n + 1);
                            });
                          }
                        }}
                        disabled={loading}
                        className="w-full font-bold"
                      >
                        <QrCode size={18} className="mr-2" /> Ulang QR
                      </Button>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
      <Dialog open={storageSaveFailed}>
        <DialogContent
          onEscapeKeyDown={(e) => e.preventDefault()}
          onPointerDownOutside={(e) => e.preventDefault()}
        >
          <DialogHeader>
            <DialogTitle className="text-red-700 dark:text-red-400">Penyimpanan Gagal</DialogTitle>
            <DialogDescription className="pt-2">
              Penyimpanan foto gagal (ruang penyimpanan penuh?). Harap bersihkan cache browser atau
              gunakan perangkat lain.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              type="button"
              onClick={() => {
                navigate('/dashboard');
              }}
              className="min-h-11"
            >
              Kembali ke Dashboard
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import React, { useState, useEffect } from 'react';
import api from '@/services/api';
import { Search, Activity, Calendar, Shield, Database, Trash2, LogIn, User } from 'lucide-react';
import { format } from 'date-fns';
import { id } from 'date-fns/locale';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Button } from '@/components/ui/button';
import AdminPageShell from '@/components/AdminPageShell';
import { ErrorWithRetry } from '@/components/ErrorWithRetry';
import { TablePagination } from '@/components/ui/TablePagination';
import { AdminEmptyState } from '@/components/admin/AdminEmptyState';
import { Skeleton } from '@/components/ui/skeleton';
import type { AuditLog } from '@/types/audit';
import type { PaginationMeta } from '@/types/common';
import {
  formatAuditDetail,
  getAuditActionLabel,
  getAuditActionVariant,
  getAuditTableLabel,
} from '@/lib/utils/auditActionLabel';

export default function AuditLogs() {
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [fetchError, setFetchError] = useState<unknown>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');

  const [page, setPage] = useState(1);
  const [meta, setMeta] = useState<PaginationMeta | null>(null);

  const loadLogs = async () => {
    setLoading(true);
    setFetchError(null);
    try {
      const params = new URLSearchParams({ page: String(page), limit: '20' });
      if (debouncedSearch.trim()) params.set('search', debouncedSearch.trim());
      const res = await api.get(`/audit-logs?${params.toString()}`);
      setLogs(res.data.data);
      setMeta(res.data.meta);
    } catch (error) {
      setFetchError(error);
      setLogs([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadLogs();
  }, [page, debouncedSearch]);

  useEffect(() => {
    const t = setTimeout(() => setDebouncedSearch(searchTerm), 300);
    return () => clearTimeout(t);
  }, [searchTerm]);

  useEffect(() => {
    setPage(1);
  }, [debouncedSearch]);

  const getActionIcon = (action: string) => {
    const upper = action.toUpperCase();
    if (upper.includes('LOGIN')) return <LogIn size={16} />;
    if (upper.includes('CREATE') || upper.includes('IMPORT')) return <Database size={16} />;
    if (upper.includes('UPDATE') || upper.includes('OVERRIDE')) return <Activity size={16} />;
    if (upper.includes('DELETE')) return <Trash2 size={16} />;
    return <Shield size={16} />;
  };

  const renderLogRow = (log: AuditLog) => {
    const detail = formatAuditDetail(log);
    return (
      <>
        <Badge
          variant={getAuditActionVariant(log.action) as 'default' | 'destructive' | 'secondary'}
          className="gap-1.5 font-normal"
        >
          {getActionIcon(log.action)}
          {getAuditActionLabel(log.action)}
        </Badge>
        <p className="mt-1 font-mono text-[10px] text-slate-400">{log.action}</p>
        <p className="mt-2 text-sm font-medium text-muted-foreground">
          {getAuditTableLabel(log.target_table)}
        </p>
        {detail ? <p className="mt-1 text-sm text-muted-foreground">{detail}</p> : null}
        <div className="mt-2 flex flex-wrap gap-3 text-xs text-muted-foreground">
          <span>{log.actor_id ? `Pengguna ${log.actor_id.slice(0, 8)}ΓÇª` : 'Sistem'}</span>
          <span>{log.ip_address || 'ΓÇö'}</span>
          <span>{format(new Date(log.created_at), 'dd MMM yyyy HH:mm', { locale: id })}</span>
        </div>
      </>
    );
  };

  return (
    <AdminPageShell
      title="Audit Log Sistem"
      description="Jejak aktivitas penting: masuk sistem, perubahan pengguna, dan penyesuaian kehadiran."
      variant="plain"
      icon={<Shield className="size-5" />}
    >
      {fetchError ? (
        <ErrorWithRetry title="Gagal memuat audit log" error={fetchError} onRetry={loadLogs} />
      ) : (
        <div className="overflow-hidden rounded-xl border border-border bg-card shadow-card dark:shadow-none dark:ring-1 dark:ring-white/10">
          <div className="border-b border-border p-5">
            <div className="relative max-w-md">
              <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-400" />
              <Input
                type="text"
                placeholder="Cari aktivitas, tabel, ID pengguna, atau IP..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9"
              />
            </div>
          </div>

          <ul className="space-y-3 p-5 md:hidden" aria-label="Daftar audit log">
            {loading ? (
              Array.from({ length: 4 }).map((_, i) => (
                <li key={i} className="rounded-2xl border border-border bg-card p-4">
                  <Skeleton className="h-6 w-32 rounded-full" />
                  <Skeleton className="mt-3 h-3 w-20" />
                  <Skeleton className="mt-4 h-4 w-36" />
                  <Skeleton className="mt-2 h-4 w-full" />
                  <Skeleton className="mt-4 h-3 w-40" />
                </li>
              ))
            ) : logs.length === 0 ? (
              <li>
                <AdminEmptyState
                  compact
                  icon={Shield}
                  title={searchTerm ? 'Tidak ada hasil' : 'Belum ada aktivitas'}
                  description={
                    searchTerm
                      ? 'Ubah kata kunci pencarian.'
                      : 'Aktivitas sistem akan tercatat di sini.'
                  }
                />
              </li>
            ) : (
              logs.map((log) => (
                <li key={log.id} className="rounded-2xl border border-border bg-card p-4">
                  {renderLogRow(log)}
                </li>
              ))
            )}
          </ul>

          <div className="hidden overflow-x-auto md:block">
            <Table>
              <TableHeader className="sticky top-0 z-10 bg-muted/50 [&_tr]:border-b">
                <TableRow>
                  <TableHead>Aktivitas</TableHead>
                  <TableHead>Target</TableHead>
                  <TableHead>Pengguna</TableHead>
                  <TableHead>Detail</TableHead>
                  <TableHead>IP</TableHead>
                  <TableHead>Waktu</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                  Array.from({ length: 6 }).map((_, i) => (
                    <TableRow key={i}>
                      <TableCell colSpan={6}>
                        <Skeleton className="h-10 w-full" />
                      </TableCell>
                    </TableRow>
                  ))
                ) : logs.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={6} className="p-0">
                      <AdminEmptyState
                        compact
                        icon={Shield}
                        title={searchTerm ? 'Tidak ada hasil' : 'Belum ada aktivitas'}
                        description={
                          searchTerm
                            ? 'Ubah kata kunci pencarian.'
                            : 'Aktivitas sistem akan tercatat di sini.'
                        }
                        className="border-0 shadow-none"
                      />
                    </TableCell>
                  </TableRow>
                ) : (
                  logs.map((log) => {
                    const detail = formatAuditDetail(log);
                    return (
                      <TableRow key={log.id}>
                        <TableCell>
                          <Badge
                            variant={
                              getAuditActionVariant(log.action) as
                                | 'default'
                                | 'destructive'
                                | 'secondary'
                            }
                            className="gap-1.5 font-normal"
                          >
                            {getActionIcon(log.action)}
                            {getAuditActionLabel(log.action)}
                          </Badge>
                          <p className="mt-1 font-mono text-[10px] text-slate-400">{log.action}</p>
                        </TableCell>
                        <TableCell>
                          <p className="font-medium text-muted-foreground">
                            {getAuditTableLabel(log.target_table)}
                          </p>
                          {log.target_id ? (
                            <p
                              className="mt-0.5 truncate font-mono text-xs text-slate-400"
                              title={log.target_id}
                            >
                              {log.target_id.slice(0, 8)}ΓÇª
                            </p>
                          ) : null}
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-2 text-sm text-muted-foreground dark:text-zinc-300">
                            <User size={14} className="shrink-0 text-slate-400" />
                            {log.actor_id ? (
                              <span className="font-mono text-xs" title={log.actor_id}>
                                {log.actor_id.slice(0, 8)}ΓÇª
                              </span>
                            ) : (
                              <span className="text-slate-400">Sistem</span>
                            )}
                          </div>
                        </TableCell>
                        <TableCell className="max-w-[200px] text-sm text-muted-foreground">
                          {detail ?? 'ΓÇö'}
                        </TableCell>
                        <TableCell className="font-mono text-sm text-muted-foreground">
                          {log.ip_address || 'ΓÇö'}
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-2 text-sm text-muted-foreground dark:text-zinc-300">
                            <Calendar size={14} className="shrink-0 text-slate-400" />
                            <span>
                              {format(new Date(log.created_at), 'dd MMM yyyy', { locale: id })}
                              <br />
                              <span className="text-xs text-slate-400">
                                {format(new Date(log.created_at), 'HH:mm:ss')}
                              </span>
                            </span>
                          </div>
                        </TableCell>
                      </TableRow>
                    );
                  })
                )}
              </TableBody>
            </Table>
          </div>

          {meta ? <TablePagination meta={meta} onPageChange={setPage} itemLabel="log" /> : null}
        </div>
      )}
    </AdminPageShell>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import useSWR from 'swr';
import { useSwrPageState } from '@/hooks/useSwrPageState';
import { useClientPagination } from '@/hooks/useClientPagination';
import { ErrorWithRetry } from '@/components/ErrorWithRetry';
import { SlowLoadingHint } from '@/components/admin/SlowLoadingHint';
import { TablePagination } from '@/components/ui/TablePagination';
import { AdminEmptyState } from '@/components/admin/AdminEmptyState';
import api from '@/services/api';
import { useAuthStore } from '@/stores/authStore';
import { Plus, Search, BookOpen, Pencil, Trash2 } from 'lucide-react';
import ClassCard from '@/components/classes/ClassCard';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { ConfirmModal } from '@/components/ConfirmModal';
import ActionLoadingOverlay from '@/components/ActionLoadingOverlay';
import { toastErrorMessage } from '@/lib/utils/toastMessage';
import { Skeleton } from '@/components/ui/skeleton';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import AdminPageShell from '@/components/AdminPageShell';
import { AdminTableShell, adminTableHeaderClass } from '@/components/admin/AdminTableShell';
import type { ClassItem } from '@/types/class';
import type { User } from '@/types/user';

export default function Classes() {
  const navigate = useNavigate();
  const { user: currentUser } = useAuthStore();
  const [searchTerm, setSearchTerm] = useState('');
  const [semesterFilter, setSemesterFilter] = useState<string>('ALL');

  // Modal state
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClass, setEditingClass] = useState<ClassItem | null>(null);

  const [lecturers, setLecturers] = useState<User[]>([]);
  const [subjectsData, setSubjectsData] = useState<{ code: string; name: string }[]>([]);

  // Form state
  const [formData, setFormData] = useState({
    name: '',
    semester: 1,
    course_code: '',
    description: '',
    lecturer_id: '',
  });

  // Delete Confirmation Modal state
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [classToDelete, setClassToDelete] = useState<string | null>(null);

  // Loading state untuk aksi tulis
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  // Save confirmation
  const [isSaveConfirmOpen, setIsSaveConfirmOpen] = useState(false);

  const fetcher = (url: string) => api.get(url).then((res) => res.data.data);
  const swr = useSWR<ClassItem[]>('/classes', fetcher, { revalidateOnFocus: false });
  const {
    data: classes = [],
    isPending: loading,
    isError,
    showSlowLoadingHint,
    retry,
    mutate,
  } = useSwrPageState(swr);
  const hasSearch = Boolean(searchTerm.trim());

  const fetchLecturers = async () => {
    if (currentUser?.role === 'SUPER_ADMIN') {
      try {
        const res = await api.get('/classes/enrollment-options');
        setLecturers(res.data.data?.lecturers ?? []);
      } catch (error) {
        console.error('Failed to fetch lecturers');
      }
    }
  };

  const fetchSubjects = async () => {
    try {
      const res = await api.get('/settings/subjects');
      if (res.data.data) {
        setSubjectsData(res.data.data);
      }
    } catch (error) {
      console.error('Failed to fetch subjects');
    }
  };

  useEffect(() => {
    fetchLecturers();
    fetchSubjects();
  }, [currentUser]);

  const handleOpenModal = (cls: ClassItem | null = null) => {
    if (cls) {
      setEditingClass(cls);
      setFormData({
        name: cls.name,
        semester: cls.semester || 1,
        course_code: cls.course_code || '',
        description: cls.description || '',
        lecturer_id: cls.lecturer_id,
      });
    } else {
      setEditingClass(null);
      setFormData({
        name: '',
        semester: 1,
        course_code: '',
        description: '',
        lecturer_id: currentUser?.role === 'ADMIN' ? currentUser.id : '',
      });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (saving) return;
    if (!formData.lecturer_id) {
      toast.error('Silakan pilih dosen pengampu');
      return;
    }
    setSaving(true);
    try {
      if (editingClass) {
        await api.put(`/classes/${editingClass.id}`, formData);
        toast.success('Kelas berhasil diperbarui');
      } else {
        await api.post('/classes', formData);
        toast.success('Kelas berhasil ditambahkan');
      }
      setIsSaveConfirmOpen(false);
      setIsModalOpen(false);
      mutate();
    } catch (error: unknown) {
      toast.error(toastErrorMessage(error, 'Terjadi kesalahan'));
    } finally {
      setSaving(false);
    }
  };

  const openDeleteConfirm = (id: string) => {
    setClassToDelete(id);
    setIsDeleteModalOpen(true);
  };

  const confirmDeleteClass = async () => {
    if (!classToDelete || deleting) return;
    setDeleting(true);
    try {
      await api.delete(`/classes/${classToDelete}`);
      toast.success('Kelas berhasil dihapus');
      setIsDeleteModalOpen(false);
      setClassToDelete(null);
      mutate();
    } catch (error) {
      toast.error('Gagal menghapus kelas');
    } finally {
      setDeleting(false);
    }
  };

  const openClassStudents = (classId: string) => {
    navigate(`/classes/${classId}`);
  };

  const actionOverlayLabel = saving
    ? editingClass
      ? 'Menyimpan perubahan kelasΓÇª'
      : 'Menambah kelasΓÇª'
    : deleting
      ? 'Menghapus kelasΓÇª'
      : null;

  const semesterOptions = useMemo(() => {
    const set = new Set(classes.map((c) => c.semester).filter((s) => s != null));
    return Array.from(set).sort((a, b) => a - b);
  }, [classes]);

  const filteredClasses = classes.filter((c) => {
    const matchesSearch =
      c.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (c.course_code && c.course_code.toLowerCase().includes(searchTerm.toLowerCase())) ||
      c.lecturer.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesSemester = semesterFilter === 'ALL' || String(c.semester) === semesterFilter;
    return matchesSearch && matchesSemester;
  });

  const canManage = currentUser?.role !== 'USER';
  const isSuperAdmin = currentUser?.role === 'SUPER_ADMIN';

  const {
    paginatedItems: paginatedClasses,
    meta: classesPaginationMeta,
    setPage: setClassesPage,
  } = useClientPagination(filteredClasses, {
    pageSize: 12,
    resetDeps: [searchTerm],
  });

  return (
    <>
      <ActionLoadingOverlay show={!!actionOverlayLabel} label={actionOverlayLabel ?? ''} />
      <AdminPageShell
        title="Manajemen Kelas"
        description="Pilih kartu kelas untuk melihat dan mengelola daftar mahasiswa terdaftar."
        variant="plain"
        icon={<BookOpen className="size-5" />}
        actions={
          currentUser?.role !== 'USER' ? (
            <Button onClick={() => handleOpenModal()}>
              <Plus className="size-4 mr-2" />
              Buat Kelas Baru
            </Button>
          ) : null
        }
      >
        {isError ? (
          <ErrorWithRetry title="Gagal memuat kelas" error={swr.error} onRetry={retry} />
        ) : showSlowLoadingHint ? (
          <SlowLoadingHint onRetry={retry} />
        ) : (
          <AdminTableShell
            filter={
              <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center">
                <div className="relative w-full min-w-0 flex-1">
                  <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    type="search"
                    placeholder="Cari nama kelas, kode MK, atau dosenΓÇª"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pl-9"
                  />
                </div>
                {semesterOptions.length > 1 ? (
                  <Select value={semesterFilter} onValueChange={setSemesterFilter}>
                    <SelectTrigger className="w-full sm:w-[180px]">
                      <SelectValue placeholder="Semester" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="ALL">Semua semester</SelectItem>
                      {semesterOptions.map((s) => (
                        <SelectItem key={s} value={String(s)}>
                          Semester {s}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : null}
              </div>
            }
            mobile={
              loading ? (
                <div className="grid gap-4 sm:grid-cols-2">
                  {Array.from({ length: 6 }).map((_, i) => (
                    <div
                      key={i}
                      className="flex h-full min-h-[220px] flex-col rounded-2xl border border-border p-5"
                    >
                      <Skeleton className="mb-4 size-14 rounded-full" />
                      <Skeleton className="mb-2 h-6 w-40" />
                      <Skeleton className="h-4 w-28" />
                    </div>
                  ))}
                </div>
              ) : filteredClasses.length === 0 ? (
                <AdminEmptyState
                  compact
                  icon={BookOpen}
                  title={
                    hasSearch || semesterFilter !== 'ALL' ? 'Tidak ada hasil' : 'Belum ada kelas'
                  }
                  description={
                    hasSearch || semesterFilter !== 'ALL'
                      ? 'Ubah filter atau kata kunci pencarian.'
                      : canManage
                        ? 'Buat kelas baru untuk mengelola mahasiswa dan sesi.'
                        : 'Anda belum terdaftar di kelas manapun.'
                  }
                />
              ) : (
                <div className="grid gap-4 sm:grid-cols-2">
                  {paginatedClasses.map((c) => (
                    <ClassCard
                      key={c.id}
                      classItem={c}
                      canManage={canManage}
                      isSuperAdmin={isSuperAdmin}
                      onOpen={() => openClassStudents(c.id)}
                      onEdit={canManage ? () => handleOpenModal(c) : undefined}
                      onDelete={isSuperAdmin ? () => openDeleteConfirm(c.id) : undefined}
                    />
                  ))}
                </div>
              )
            }
            footer={
              <TablePagination
                meta={classesPaginationMeta}
                onPageChange={setClassesPage}
                itemLabel="kelas"
              />
            }
          >
            <Table>
              <TableHeader className={adminTableHeaderClass}>
                <TableRow>
                  <TableHead className="w-12">No</TableHead>
                  <TableHead>Nama Kelas</TableHead>
                  <TableHead>Semester</TableHead>
                  <TableHead>Kode MK</TableHead>
                  <TableHead>Pengampu</TableHead>
                  <TableHead className="text-right">Mahasiswa</TableHead>
                  <TableHead className="text-right">Sesi</TableHead>
                  <TableHead className="text-right">Aksi</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                  Array.from({ length: 6 }).map((_, i) => (
                    <TableRow key={i}>
                      <TableCell colSpan={8}>
                        <Skeleton className="h-10 w-full" />
                      </TableCell>
                    </TableRow>
                  ))
                ) : filteredClasses.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={8} className="p-0">
                      <AdminEmptyState
                        compact
                        icon={BookOpen}
                        title={
                          hasSearch || semesterFilter !== 'ALL'
                            ? 'Tidak ada hasil'
                            : 'Belum ada kelas'
                        }
                        description={
                          hasSearch || semesterFilter !== 'ALL'
                            ? 'Ubah filter atau kata kunci pencarian.'
                            : canManage
                              ? 'Buat kelas baru untuk mengelola mahasiswa dan sesi.'
                              : 'Anda belum terdaftar di kelas manapun.'
                        }
                        className="border-0 shadow-none"
                      />
                    </TableCell>
                  </TableRow>
                ) : (
                  paginatedClasses.map((c, idx) => (
                    <TableRow
                      key={c.id}
                      role="button"
                      tabIndex={0}
                      onClick={() => openClassStudents(c.id)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' || e.key === ' ') openClassStudents(c.id);
                      }}
                      className="cursor-pointer"
                    >
                      <TableCell className="text-muted-foreground">
                        {(classesPaginationMeta.page - 1) * classesPaginationMeta.limit + idx + 1}
                      </TableCell>
                      <TableCell className="font-medium">{c.name}</TableCell>
                      <TableCell className="text-muted-foreground">Sem {c.semester}</TableCell>
                      <TableCell className="font-mono text-sm text-muted-foreground">
                        {c.course_code || 'ΓÇö'}
                      </TableCell>
                      <TableCell className="text-muted-foreground">{c.lecturer.name}</TableCell>
                      <TableCell className="text-right text-muted-foreground">
                        {c._count.enrollments}
                      </TableCell>
                      <TableCell className="text-right text-muted-foreground">
                        {c._count.sessions}
                      </TableCell>
                      <TableCell className="text-right">
                        <div
                          className="flex justify-end gap-1"
                          onClick={(e) => e.stopPropagation()}
                        >
                          {canManage ? (
                            <Button
                              type="button"
                              variant="ghost"
                              size="icon"
                              className="size-9"
                              onClick={() => handleOpenModal(c)}
                              title="Edit kelas"
                            >
                              <Pencil className="size-4" />
                            </Button>
                          ) : null}
                          {isSuperAdmin ? (
                            <Button
                              type="button"
                              variant="ghost"
                              size="icon"
                              className="size-9 text-destructive hover:text-destructive"
                              onClick={() => openDeleteConfirm(c.id)}
                              title="Hapus kelas"
                            >
                              <Trash2 className="size-4" />
                            </Button>
                          ) : null}
                        </div>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </AdminTableShell>
        )}

        {/* Modal Form */}
        <Dialog open={isModalOpen} onOpenChange={setIsModalOpen}>
          <DialogContent className="max-w-lg p-0">
            <div className="border-b border-border px-6 py-4 border-border">
              <DialogHeader>
                <DialogTitle className="text-xl font-bold text-foreground">
                  {editingClass ? 'Edit Kelas' : 'Tambah Kelas Baru'}
                </DialogTitle>
                <DialogDescription className="sr-only">Form kelas</DialogDescription>
              </DialogHeader>
            </div>

            <form onSubmit={handleSubmit} className="max-h-[70vh] space-y-4 overflow-y-auto p-6">
              <div className="space-y-2">
                <Label>
                  Pilih Mata Kuliah <span className="text-red-500">*</span>
                </Label>
                {subjectsData.length > 0 ? (
                  <Select
                    required
                    value={formData.course_code}
                    onValueChange={(val) => {
                      const selectedSubject = subjectsData.find((s) => s.code === val);
                      if (selectedSubject) {
                        setFormData({
                          ...formData,
                          course_code: selectedSubject.code,
                          name: selectedSubject.name,
                        });
                      }
                    }}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Pilih Mata Kuliah" />
                    </SelectTrigger>
                    <SelectContent>
                      {subjectsData.map((s) => (
                        <SelectItem key={s.code} value={s.code}>
                          {s.code} - {s.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : (
                  <div className="text-sm text-amber-600 bg-amber-50 p-2 rounded border border-amber-200">
                    Anda belum menambahkan Mata Kuliah di menu Fakultas & Prodi. Silakan tambahkan
                    terlebih dahulu.
                  </div>
                )}
              </div>
              <div className="space-y-2">
                <Label>
                  Nama Kelas Spesifik <span className="text-red-500">*</span>
                </Label>
                <Input
                  type="text"
                  required
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="Contoh: Pemrograman Web (A)"
                />
                <p className="text-xs text-muted-foreground">
                  Bisa diisi nama mata kuliah beserta grup/kelasnya (misal: Algoritma Kelas B).
                </p>
              </div>
              <div className="space-y-2">
                <Label>
                  Semester <span className="text-red-500">*</span>
                </Label>
                <Input
                  type="number"
                  min={1}
                  max={14}
                  required
                  value={formData.semester}
                  onChange={(e) =>
                    setFormData((p) => ({
                      ...p,
                      semester: Math.max(
                        1,
                        Math.min(14, Number.parseInt(e.target.value || '1', 10) || 1)
                      ),
                    }))
                  }
                />
                <p className="text-xs text-muted-foreground">
                  Digunakan sebagai label ΓÇ£Sem XΓÇ¥ di semua pilihan kelas.
                </p>
              </div>
              <div className="space-y-2">
                <Label>Deskripsi (Opsional)</Label>
                <Input
                  type="text"
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <Label>
                  Dosen Pengampu <span className="text-red-500">*</span>
                </Label>
                <Select
                  required
                  value={formData.lecturer_id}
                  onValueChange={(val) => setFormData({ ...formData, lecturer_id: val })}
                  disabled={currentUser?.role !== 'SUPER_ADMIN'}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Pilih Dosen" />
                  </SelectTrigger>
                  <SelectContent>
                    {lecturers.map((l) => (
                      <SelectItem key={l.id} value={l.id}>
                        {l.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <DialogFooter className="mt-6">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setIsModalOpen(false)}
                  disabled={saving}
                >
                  Batal
                </Button>
                <Button
                  type="button"
                  onClick={() => setIsSaveConfirmOpen(true)}
                  disabled={saving}
                  aria-busy={saving}
                >
                  {saving ? 'MenyimpanΓÇª' : 'Simpan'}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>

        <ConfirmModal
          isOpen={isSaveConfirmOpen}
          onClose={() => setIsSaveConfirmOpen(false)}
          onConfirm={() => {
            void handleSubmit({ preventDefault: () => {} } as React.FormEvent);
          }}
          title={editingClass ? 'Simpan perubahan kelas?' : 'Tambah kelas baru?'}
          description={
            editingClass
              ? `Perubahan pada kelas "${formData.name || editingClass.name}" akan disimpan.`
              : `Kelas "${formData.name || 'tanpa nama'}" akan ditambahkan ke sistem.`
          }
          confirmText={editingClass ? 'Ya, Simpan' : 'Ya, Tambah'}
          variant="primary"
          loading={saving}
          loadingText="MenyimpanΓÇª"
        />

        {/* Delete Class Confirmation Modal */}
        <ConfirmModal
          isOpen={isDeleteModalOpen}
          onClose={() => setIsDeleteModalOpen(false)}
          onConfirm={confirmDeleteClass}
          title="Konfirmasi Hapus Kelas"
          description="Apakah Anda yakin ingin menghapus kelas ini? Semua data pendaftaran (enrollment) mahasiswa akan ikut terhapus secara permanen."
          confirmText="Ya, Hapus Kelas"
          variant="danger"
          loading={deleting}
          loadingText="MenghapusΓÇª"
        />
      </AdminPageShell>
    </>
  );
}

import React, { lazy, Suspense, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import useSWR from 'swr';
import { useAuthStore } from '@/stores/authStore';
import api from '@/services/api';
import {
  Users,
  Calendar,
  CheckCircle2,
  Clock,
  MapPin,
  FileText,
  BarChart3,
  QrCode,
} from 'lucide-react';
import AdminPageShell from '@/components/AdminPageShell';
import { ErrorWithRetry } from '@/components/ErrorWithRetry';
import { AttendanceChartLegend } from '@/components/charts/AttendanceChartLegend';
import { AttendanceChartLoadingOverlay } from '@/components/charts/AttendanceChartLoadingOverlay';
import { AttendanceChartSkeleton } from '@/components/charts/AttendanceChartSkeleton';
import { type ChartFilterValue } from '@/lib/utils/attendanceChartTheme';
import { cn } from '@/lib/utils/utils';
import { useSwrPageState } from '@/hooks/useSwrPageState';

const DashboardAttendanceBarChart = lazy(
  () => import('@/components/charts/DashboardAttendanceBarChart')
);
import { format } from 'date-fns';
import { id } from 'date-fns/locale';
import { Button } from '@/components/ui/button';
import {
