                      className="rounded-2xl border border-border bg-background/60 p-4"
                    >
                      <div className="flex flex-wrap items-start justify-between gap-2">
                        <div className="min-w-0 flex-1">
                          <p className="font-bold text-foreground">
                            {dashboardSessionTitle(session)}
                          </p>
                          {dashboardSessionClass(session) ? (
                            <p className="mt-0.5 text-sm text-muted-foreground">
                              {dashboardSessionClass(session)}
                            </p>
                          ) : null}
                        </div>
                        <Badge
                          variant="outline"
                          className={dashboardSessionStatusClass(session.status)}
                        >
                          {sessionStatusLabel(session.status)}
                        </Badge>
                      </div>
                      {session.location?.name ? (
                        <p className="mt-2 flex items-center gap-1.5 text-sm text-muted-foreground">
                          <MapPin size={14} className="shrink-0" aria-hidden="true" />
                          <span className="truncate">{session.location.name}</span>
                        </p>
                      ) : null}
                      <div className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
                        <span className="inline-flex items-center gap-1.5">
                          <Calendar size={14} className="shrink-0 text-brand" aria-hidden="true" />
                          {format(new Date(session.session_start), 'dd MMM yyyy', { locale: id })}
                        </span>
                        <span className="inline-flex items-center gap-1.5">
                          <Clock size={14} className="shrink-0 text-brand" aria-hidden="true" />
                          {format(new Date(session.session_start), 'HH:mm', { locale: id })} WIB
                        </span>
                        <span className="inline-flex items-center gap-1.5 font-medium text-foreground">
                          <Users size={14} className="shrink-0 text-brand" aria-hidden="true" />
                          {session._count?.attendances ?? 0} hadir
                        </span>
                      </div>
                    </li>
                  ))
                )}
              </ul>
            </div>
          </div>
        </div>
      )}
    </AdminPageShell>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import api from '@/services/api';
import useSWR from 'swr';
import { useAuthStore } from '@/stores/authStore';
import {
  Plus,
  Search,
  FileText,
  CheckCircle2,
  XCircle,
  Clock,
  Download,
  X,
  Loader2,
} from 'lucide-react';
import { format } from 'date-fns';
import { id } from 'date-fns/locale';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import type { Excuse } from '@/types/excuse';
import { cn } from '@/lib/utils/utils';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { formatClassLabel } from '@/lib/utils/classLabel';
import AdminPageShell from '@/components/AdminPageShell';
import { Skeleton } from '@/components/ui/skeleton';
import { ErrorWithRetry } from '@/components/ErrorWithRetry';
import { SlowLoadingHint } from '@/components/admin/SlowLoadingHint';
import { excuseStatusLabel } from '@/lib/utils/statusLabel';
import { toastErrorMessage } from '@/lib/utils/toastMessage';
import { AdminEmptyState } from '@/components/admin/AdminEmptyState';
import { useSwrPageState } from '@/hooks/useSwrPageState';
import { useClientPagination } from '@/hooks/useClientPagination';
import { TablePagination } from '@/components/ui/TablePagination';
import { FileText as FileTextIcon } from 'lucide-react';
import ActionLoadingOverlay from '@/components/ActionLoadingOverlay';
import { ConfirmModal } from '@/components/ConfirmModal';
import {
  acquireCameraStream,
  humanizeCameraError,
  releaseMediaStream,
  waitForCameraRelease,
  releaseActiveVideoTracks,
} from '@/lib/media/camera';

export default function Excuses() {
  const { user: currentUser } = useAuthStore();
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('ALL');
  const [reasonFilter, setReasonFilter] = useState('ALL');

  // Modal state
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [sessions, setSessions] = useState<
    {
      id: string;
      title: string;
      session_start: string;
      class?: { name: string; semester: number } | null;
      session_classes?: { class: { name: string; semester: number } }[];
    }[]
  >([]);

  const [formData, setFormData] = useState({
    session_id: '',
    reason: 'SICK',
    description: '',
  });
  const [photoBlob, setPhotoBlob] = useState<Blob | null>(null);
  const [photoPreviewUrl, setPhotoPreviewUrl] = useState<string | null>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [cameraStarting, setCameraStarting] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('environment');
  const [submitting, setSubmitting] = useState(false);
  const [reviewingId, setReviewingId] = useState<string | null>(null);
  const [reviewConfirm, setReviewConfirm] = useState<{
    id: string;
    status: 'APPROVED' | 'REJECTED';
    studentName: string;
  } | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const pendingStreamRef = useRef<MediaStream | null>(null);

  const clearPhoto = () => {
    setPhotoBlob(null);
    if (photoPreviewUrl) URL.revokeObjectURL(photoPreviewUrl);
    setPhotoPreviewUrl(null);
    setCameraError(null);
  };

  const stopCamera = () => {
    // Release any pending stream that hasn't been assigned yet
    if (pendingStreamRef.current) {
      releaseMediaStream(pendingStreamRef.current);
      pendingStreamRef.current = null;
    }
    const stream = videoRef.current?.srcObject as MediaStream | null;
    if (stream) {
      releaseMediaStream(stream);
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
  };

  // Camera: dilepas HANYA saat unmount ΓÇö jangan gabungkan dengan photoPreviewUrl
  // sebab cleanup effect dengan deps [photoPreviewUrl] akan memanggil stopCamera()
  // setiap kali URL berubah, termasuk saat retakePhoto() sedang mengakuisisi stream baru.

  useEffect(() => {
    return () => {
      stopCamera();
      void releaseActiveVideoTracks();
    };
  }, []);

  // When isCameraActive flips to true the container's `hidden` class is removed.
  // We use requestAnimationFrame so the browser has painted the now-visible <video>
  // before we assign the stream and call play(). This avoids the mobile Android
  // Chrome bug where play() on a display:none element silently skips decoder init.
  useEffect(() => {
    if (isCameraActive && pendingStreamRef.current && videoRef.current) {
      const stream = pendingStreamRef.current;
      pendingStreamRef.current = null;
      requestAnimationFrame(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.play().catch(() => undefined);
        }
      });
    }
  }, [isCameraActive]);

  // URL revocation: closure menangkap nilai lama ΓÇö ini benar untuk revoke URL lama
  useEffect(() => {
    return () => {
      if (photoPreviewUrl) URL.revokeObjectURL(photoPreviewUrl);
    };
  }, [photoPreviewUrl]);

  const startCamera = async (mode = facingMode) => {
    if (cameraStarting) return;
    setCameraStarting(true);
    setCameraError(null);
    try {
      stopCamera();
      await waitForCameraRelease(400);

      // Retry loop ΓÇö hardware kamera kadang butuh waktu extra untuk dilepas
      // (terutama setelah navigasi dari halaman Attend yang pakai QR scanner)
      let lastErr: unknown;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (attempt > 0) {
          await waitForCameraRelease(600 + attempt * 300); // 600ms, 900ms
        }
        try {
          const stream = await acquireCameraStream({
            facingMode: mode,
            preferRear: mode === 'environment',
          });
          // Store stream in ref ΓÇö the useEffect watching isCameraActive will
          // pick it up and assign it to the <video> after React re-renders
          // and the container's `hidden` class is removed.
          pendingStreamRef.current = stream;
          setIsCameraActive(true);
          return;
        } catch (err) {
          lastErr = err;
        }
      }

      const msg = humanizeCameraError(lastErr);
      setCameraError(msg);
      toast.error(msg);
    } finally {
      setCameraStarting(false);
    }
  };

  const switchCamera = () => {
    const next = facingMode === 'user' ? 'environment' : 'user';
    setFacingMode(next);
    if (isCameraActive) void startCamera(next);
  };

  const takePhoto = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;
    const MAX_WIDTH = 900;
    let width = video.videoWidth;
    let height = video.videoHeight;
    if (width > MAX_WIDTH) {
      height = Math.round((height * MAX_WIDTH) / width);
      width = MAX_WIDTH;
    }
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (facingMode === 'user') {
      ctx.translate(canvas.width, 0);
      ctx.scale(-1, 1);
    }
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

    if (facingMode === 'user') {
      ctx.translate(canvas.width, 0);
      ctx.scale(-1, 1);
    }

    ctx.font = '14px Arial';
    ctx.fillStyle = 'yellow';
    ctx.shadowColor = 'black';
    ctx.shadowBlur = 4;
    ctx.fillText(`${new Date().toLocaleString()}`, 10, canvas.height - 10);
    ctx.shadowBlur = 0;

    canvas.toBlob(
      (blob) => {
        if (!blob) return;
        setPhotoBlob(blob);
        if (photoPreviewUrl) URL.revokeObjectURL(photoPreviewUrl);
        setPhotoPreviewUrl(URL.createObjectURL(blob));
        stopCamera();
      },
      'image/jpeg',
      0.75
    );
  };

  const retakePhoto = () => {
    clearPhoto();
    void startCamera();
  };

  const fetcher = (url: string) => api.get(url).then((res) => res.data.data);
  const swr = useSWR<Excuse[]>('/excuses', fetcher, { revalidateOnFocus: false });
  const {
    data: excuses = [],
    isPending: loading,
    isError,
    showSlowLoadingHint,
    retry,
    mutate,
  } = useSwrPageState(swr);
  const hasFilters = Boolean(searchTerm.trim()) || statusFilter !== 'ALL' || reasonFilter !== 'ALL';

  const resolveProofUrl = (proofUrl: string | null | undefined) => {
    if (!proofUrl) return null;
    if (proofUrl.startsWith('http') || proofUrl.startsWith('data:')) return proofUrl;
    const apiBase = String(import.meta.env.VITE_API_BASE_URL || '/api');
    const assetBase = apiBase.startsWith('http')
      ? new URL(apiBase).origin
      : apiBase.replace(/\/api\/?$/, '');
    return `${assetBase}${proofUrl}`;
  };

  const fetchSessions = async () => {
    try {
      const res = await api.get('/sessions');
      // Filter sessions that are active or upcoming
      setSessions(res.data.data.filter((s: any) => s.status !== 'CLOSED'));
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    if (currentUser?.role === 'USER') {
      fetchSessions();
    }
  }, [currentUser]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (submitting) return;
    if (!formData.session_id) {
      toast.error('Pilih sesi kelas terlebih dahulu');
      return;
    }
    if (!photoBlob) {
      toast.error('Ambil foto bukti terlebih dahulu');
      return;
    }

    setSubmitting(true);
    try {
      const photoType = photoBlob.type || 'image/jpeg';
      const challengeRes = await api.get('/excuses/challenge', {
        params: {
          session_id: formData.session_id,
          photo_size: photoBlob.size,
          photo_type: photoType,
        },
      });
      const nonce = challengeRes.data?.data?.nonce;
      const signature = challengeRes.data?.data?.signature;
      if (!nonce || !signature) {
        throw new Error('Gagal mendapatkan security token dari server');
      }

      const form = new FormData();
      form.append('session_id', formData.session_id);
      form.append('reason', formData.reason);
      form.append('description', formData.description);
      form.append('nonce', nonce);
      form.append('signature', signature);
      form.append('photo_size', photoBlob.size.toString());
      form.append('photo_type', photoType);
      form.append('proof', photoBlob, 'excuse.jpg');

      await api.post('/excuses', form, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      toast.success('Pengajuan izin berhasil dikirim');
      setIsModalOpen(false);
      setFormData({ session_id: '', reason: 'SICK', description: '' });
      clearPhoto();
      mutate();
    } catch (error: unknown) {
      toast.error(toastErrorMessage(error, 'Terjadi kesalahan saat mengajukan izin'));
    } finally {
      setSubmitting(false);
    }
  };

  const openReviewConfirm = (id: string, status: 'APPROVED' | 'REJECTED', studentName: string) => {
    setReviewConfirm({ id, status, studentName });
  };

  const confirmReview = async () => {
    if (!reviewConfirm || reviewingId) return;
    const { id, status } = reviewConfirm;
    setReviewingId(id);
    try {
      await api.put(`/excuses/${id}/review`, { status });
      toast.success(`Pengajuan izin ${status === 'APPROVED' ? 'disetujui' : 'ditolak'}`);
      mutate();
      setReviewConfirm(null);
    } catch (error: unknown) {
      toast.error(toastErrorMessage(error, 'Gagal mereview pengajuan izin'));
    } finally {
      setReviewingId(null);
    }
  };

  const actionOverlayLabel = submitting
    ? 'Mengirim pengajuan izinΓÇª'
    : reviewingId
      ? 'Memproses tinjauanΓÇª'
      : null;

  const filteredExcuses = excuses.filter((ex) => {
    const matchSearch =
      (ex.user?.name && ex.user.name.toLowerCase().includes(searchTerm.toLowerCase())) ||
      (ex.session?.title && ex.session.title.toLowerCase().includes(searchTerm.toLowerCase()));
    if (!matchSearch) return false;

    if (statusFilter !== 'ALL' && ex.status !== statusFilter) return false;
    if (reasonFilter !== 'ALL' && ex.reason !== reasonFilter) return false;

    return true;
  });

  const {
    paginatedItems: paginatedExcuses,
    meta: excusesPaginationMeta,
    setPage: setExcusesPage,
  } = useClientPagination(filteredExcuses, {
    pageSize: 20,
    resetDeps: [searchTerm, statusFilter, reasonFilter],
  });

  const exportCsv = () => {
    const escapeCsv = (value: unknown) => {
      const raw = String(value ?? '');
      const normalized = raw.replace(/\r?\n/g, ' ').trim();
      if (/[",]/.test(normalized)) return `"${normalized.replace(/"/g, '""')}"`;
      return normalized;
    };

    const rows = filteredExcuses.map((ex) => {
      const proof =
        ex.proof_url && (ex.proof_url.startsWith('http') || ex.proof_url.startsWith('data:'))
          ? ex.proof_url
          : ex.proof_url
            ? resolveProofUrl(ex.proof_url)
            : '';
      return [
        ex.id,
        ex.user?.name ?? '',
        ex.user?.nim_nip ?? '',
        ex.session?.title ?? '',
        (() => {
          const labels =
            (ex.session as any)?.session_classes?.flatMap((x: any) => {
              const result = formatClassLabel(x?.class);
              return result ? [result] : [];
            }) ?? [];
          if (labels.length) return labels.join(', ');
          return ex.session?.class ? formatClassLabel(ex.session.class) : '';
        })(),
        ex.reason ?? '',
        ex.status ?? '',
        ex.description ?? '',
        ex.reviewer?.name ?? '',
        ex.created_at ?? '',
        ex.session?.session_start ?? '',
        proof,
      ]
        .map(escapeCsv)
        .join(',');
    });

    const header = [
      'id',
      'nama',
      'nim',
      'sesi',
      'kelas',
      'alasan',
      'status',
      'keterangan',
      'reviewer',
      'dibuat_pada',
      'jadwal_sesi',
      'bukti_url',
    ].join(',');

    const content = `\uFEFF${header}\n${rows.join('\n')}\n`;
    const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const date = new Date().toISOString().slice(0, 10);
    a.href = url;
    a.download = `pengajuan-izin-${date}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    toast.success('Unduh CSV berhasil');
  };

  return (
    <>
      <ActionLoadingOverlay show={!!actionOverlayLabel} label={actionOverlayLabel ?? ''} />
      <AdminPageShell
        title="Pengajuan Izin & Sakit"
        description={
          currentUser?.role === 'USER'
            ? 'Ajukan izin atau sakit untuk sesi yang Anda lewatkan.'
            : 'Tinjau dan setujui pengajuan mahasiswa.'
        }
        variant="plain"
        icon={<FileText className="size-5" />}
        actions={
          <>
            {currentUser?.role !== 'USER' ? (
              <Button
                variant="outline"
                onClick={exportCsv}
                disabled={loading || filteredExcuses.length === 0}
              >
                <Download className="mr-2 size-4" aria-hidden="true" />
                Unduh CSV
              </Button>
            ) : null}
            {currentUser?.role === 'USER' ? (
              <Button onClick={() => setIsModalOpen(true)}>
                <Plus className="mr-2 size-4" aria-hidden="true" />
                Pengajuan baru
              </Button>
            ) : null}
          </>
        }
      >
        {isError ? (
          <ErrorWithRetry title="Gagal memuat pengajuan izin" error={swr.error} onRetry={retry} />
        ) : showSlowLoadingHint ? (
          <SlowLoadingHint onRetry={retry} />
        ) : (
          <div className="overflow-hidden rounded-xl border border-border bg-card shadow-card dark:shadow-none dark:ring-1 dark:ring-white/10">
            <div className="flex flex-col gap-5 border-b border-border p-5 sm:flex-row">
              <div className="relative max-w-md flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 size-4" />
                <Input
                  type="text"
                  placeholder="Cari nama mahasiswa atau kelas..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-9"
                />
              </div>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-full sm:w-[150px]">
                  <SelectValue placeholder="Semua Status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ALL">Semua Status</SelectItem>
                  <SelectItem value="PENDING">Menunggu</SelectItem>
                  <SelectItem value="APPROVED">Disetujui</SelectItem>
                  <SelectItem value="REJECTED">Ditolak</SelectItem>
                </SelectContent>
              </Select>
              <Select value={reasonFilter} onValueChange={setReasonFilter}>
                <SelectTrigger className="w-full sm:w-[150px]">
                  <SelectValue placeholder="Semua Alasan" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ALL">Semua Alasan</SelectItem>
                  <SelectItem value="SICK">Sakit</SelectItem>
                  <SelectItem value="EXCUSED">Izin</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <ul className="space-y-3 p-5 md:hidden" aria-label="Daftar pengajuan izin">
              {loading ? (
                Array.from({ length: 3 }).map((_, i) => (
                  <li key={i} className="rounded-2xl border border-border p-4 border-border">
                    <Skeleton className="mb-2 h-5 w-40" />
                    <Skeleton className="h-4 w-32" />
                    <Skeleton className="mt-3 h-9 w-full" />
                  </li>
                ))
              ) : filteredExcuses.length === 0 ? (
                <li>
                  <AdminEmptyState
                    compact
                    icon={FileTextIcon}
                    title={hasFilters ? 'Tidak ada hasil' : 'Belum ada pengajuan'}
                    description={
                      hasFilters
                        ? 'Ubah filter atau kata kunci pencarian.'
                        : 'Pengajuan izin dan sakit akan muncul di sini.'
                    }
                  />
                </li>
              ) : (
                paginatedExcuses.map((excuse) => {
                  const proofHref = resolveProofUrl(excuse.proof_url);
                  const classLabel = (() => {
                    const labels = (excuse.session.session_classes ?? []).flatMap((x) => {
                      const result = formatClassLabel(x?.class);
                      return result ? [result] : [];
                    });
                    if (labels.length) return labels.join(', ');
                    return excuse.session.class ? formatClassLabel(excuse.session.class) : 'Umum';
                  })();
                  return (
                    <li
                      key={excuse.id}
                      className="rounded-2xl border border-border p-4 border-border"
                    >
                      {currentUser?.role !== 'USER' && (
                        <>
                          <p className="font-bold text-foreground">{excuse.user.name}</p>
                          <p className="text-xs text-muted-foreground">
                            {excuse.user.nim_nip || '-'}
                          </p>
                        </>
                      )}
                      <p className="mt-1 text-sm font-medium text-brand">{excuse.session.title}</p>
                      <p className="text-xs font-semibold text-brand">{classLabel}</p>
                      <p className="mt-1 text-xs text-muted-foreground">
                        {format(new Date(excuse.session.session_start), 'dd MMM yyyy HH:mm', {
                          locale: id,
                        })}
                      </p>
                      {excuse.description ? (
                        <p
                          className="mt-2 text-xs text-muted-foreground line-clamp-2"
                          title={excuse.description}
                        >
                          {excuse.description}
                        </p>
                      ) : null}
                      <div className="mt-2 flex items-center justify-between">
                        <Badge variant={excuse.reason === 'SICK' ? 'destructive' : 'warning'}>
                          {excuse.reason === 'SICK' ? 'Sakit' : 'Izin'}
                        </Badge>
                        <Badge
                          variant={
                            excuse.status === 'APPROVED'
                              ? 'success'
                              : excuse.status === 'REJECTED'
                                ? 'destructive'
                                : 'secondary'
                          }
                        >
                          {excuseStatusLabel(excuse.status)}
                        </Badge>
                      </div>
                      {excuse.reviewer ? (
                        <p className="mt-2 text-[10px] text-muted-foreground">
                          Oleh: {excuse.reviewer.name}
                        </p>
                      ) : null}
                      {proofHref ? (
                        <a
                          href={proofHref}
                          target="_blank"
                          rel="noreferrer"
                          className="mt-2 inline-flex items-center gap-1 text-sm text-brand text-brand"
                        >
                          <Download className="size-4" />
                          Lihat bukti
                        </a>
                      ) : null}
                      {currentUser?.role !== 'USER' && excuse.status === 'PENDING' ? (
                        <div className="mt-3 flex gap-2">
                          <Button
                            size="sm"
                            variant="outline"
                            className="min-h-11 flex-1 border-emerald-200 text-emerald-700"
                            disabled={!!reviewingId}
                            aria-busy={reviewingId === excuse.id}
                            onClick={() =>
                              openReviewConfirm(
                                excuse.id,
                                'APPROVED',
                                excuse.user?.name ?? 'Mahasiswa'
                              )
                            }
                          >
                            {reviewingId === excuse.id ? (
                              <Loader2 className="size-4 animate-spin" />
                            ) : (
                              'Terima'
                            )}
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            className="min-h-11 flex-1 border-red-200 text-red-700"
                            disabled={!!reviewingId}
                            onClick={() =>
                              openReviewConfirm(
                                excuse.id,
                                'REJECTED',
                                excuse.user?.name ?? 'Mahasiswa'
                              )
                            }
                          >
                            Tolak
                          </Button>
                        </div>
                      ) : null}
                    </li>
                  );
                })
              )}
            </ul>

            <div className="hidden overflow-x-auto md:block">
              <Table>
                <TableHeader className="sticky top-0 z-10 bg-muted/50 [&_tr]:border-b">
                  <TableRow>
                    {currentUser?.role !== 'USER' && <TableHead>Mahasiswa</TableHead>}
                    <TableHead>Kelas / Sesi</TableHead>
                    <TableHead>Alasan</TableHead>
                    <TableHead>Bukti</TableHead>
                    <TableHead>Status</TableHead>
                    {currentUser?.role !== 'USER' && (
                      <TableHead className="text-right">Aksi</TableHead>
                    )}
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {loading ? (
                    Array.from({ length: 6 }).map((_, i) => (
                      <TableRow key={i}>
                        <TableCell colSpan={currentUser?.role !== 'USER' ? 6 : 5}>
                          <Skeleton className="h-10 w-full" />
                        </TableCell>
                      </TableRow>
                    ))
                  ) : filteredExcuses.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={currentUser?.role !== 'USER' ? 6 : 5} className="p-0">
                        <AdminEmptyState
                          compact
                          icon={FileTextIcon}
                          title={hasFilters ? 'Tidak ada hasil' : 'Belum ada pengajuan'}
                          description={
                            hasFilters
                              ? 'Ubah filter atau kata kunci pencarian.'
                              : 'Pengajuan izin dan sakit akan muncul di sini.'
                          }
                        />
                      </TableCell>
                    </TableRow>
                  ) : (
                    paginatedExcuses.map((excuse) => (
                      <TableRow key={excuse.id}>
                        {currentUser?.role !== 'USER' && (
                          <TableCell>
                            <div className="font-medium text-foreground">{excuse.user.name}</div>
                            <div className="text-xs text-muted-foreground">
                              {excuse.user.nim_nip}
                            </div>
                          </TableCell>
                        )}
                        <TableCell>
                          <div className="font-medium text-slate-800 dark:text-zinc-200">
                            {excuse.session.title}
                          </div>
                          <div className="text-xs font-semibold text-brand text-brand mt-0.5">
                            {(() => {
                              const labels = (excuse.session.session_classes ?? []).flatMap(
                                (x: any) => {
                                  const result = formatClassLabel(x?.class);
                                  return result ? [result] : [];
                                }
                              );
                              if (labels.length) return labels.join(', ');
                              return excuse.session.class
                                ? formatClassLabel(excuse.session.class)
                                : 'Umum';
                            })()}
                          </div>
                          <div className="text-xs text-muted-foreground mt-1">
                            {format(new Date(excuse.session.session_start), 'dd MMM yyyy HH:mm', {
                              locale: id,
                            })}
                          </div>
                        </TableCell>
                        <TableCell>
                          <Badge variant={excuse.reason === 'SICK' ? 'destructive' : 'warning'}>
                            {excuse.reason === 'SICK' ? 'Sakit' : 'Izin'}
                          </Badge>
                          <p
                            className="text-xs mt-1 max-w-xs truncate text-muted-foreground"
                            title={excuse.description}
                          >
                            {excuse.description || '-'}
                          </p>
                        </TableCell>
                        <TableCell>
                          {resolveProofUrl(excuse.proof_url) ? (
                            <a
                              href={resolveProofUrl(excuse.proof_url) || undefined}
                              target="_blank"
                              rel="noreferrer"
                              className="text-brand hover:underline flex items-center gap-1 text-sm"
                            >
                              <FileText size={14} /> Lihat Bukti
                            </a>
                          ) : (
                            '-'
                          )}
                        </TableCell>
                        <TableCell>
                          <Badge
                            variant={
                              excuse.status === 'APPROVED'
                                ? 'success'
                                : excuse.status === 'REJECTED'
                                  ? 'destructive'
                                  : 'default'
                            }
                            className="gap-1"
                          >
                            {excuse.status === 'APPROVED' && <CheckCircle2 size={12} />}
                            {excuse.status === 'REJECTED' && <XCircle size={12} />}
                            {excuse.status === 'PENDING' && <Clock size={12} />}
                            {excuseStatusLabel(excuse.status)}
                          </Badge>
                          {excuse.reviewer && (
                            <div className="text-[10px] text-slate-400 mt-1">
                              Oleh: {excuse.reviewer.name}
                            </div>
                          )}
                        </TableCell>
                        {currentUser?.role !== 'USER' && (
                          <TableCell className="text-right">
                            {excuse.status === 'PENDING' && (
                              <div className="flex justify-end gap-2">
                                <Button
                                  size="sm"
                                  variant="outline"
                                  className="border-emerald-200 text-emerald-600 hover:bg-emerald-50"
                                  disabled={!!reviewingId}
                                  aria-busy={reviewingId === excuse.id}
                                  onClick={() =>
                                    openReviewConfirm(
                                      excuse.id,
                                      'APPROVED',
                                      excuse.user?.name ?? 'Mahasiswa'
                                    )
                                  }
                                >
                                  {reviewingId === excuse.id ? (
                                    <Loader2 className="size-4 animate-spin" />
                                  ) : (
                                    'Terima'
                                  )}
                                </Button>
                                <Button
                                  size="sm"
                                  variant="outline"
                                  className="border-red-200 text-red-600 hover:bg-red-50"
                                  disabled={!!reviewingId}
                                  onClick={() =>
                                    openReviewConfirm(
                                      excuse.id,
                                      'REJECTED',
                                      excuse.user?.name ?? 'Mahasiswa'
                                    )
                                  }
                                >
                                  Tolak
                                </Button>
                              </div>
                            )}
                          </TableCell>
                        )}
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </div>
            <TablePagination
              meta={excusesPaginationMeta}
              onPageChange={setExcusesPage}
              itemLabel="pengajuan"
            />
          </div>
        )}

        {/* Modal Form */}
        <Dialog
          open={isModalOpen}
          onOpenChange={(open) => {
            if (!open && submitting) return;
            if (!open) {
              stopCamera();
              clearPhoto();
            }
            setIsModalOpen(open);
          }}
        >
          <DialogContent className="max-w-lg max-h-[90dvh] overflow-y-auto p-0">
            <div className="border-b border-border px-6 py-5 border-border">
              <DialogHeader>
                <DialogTitle className="text-xl font-bold text-foreground">
                  Buat Pengajuan Izin Baru
                </DialogTitle>
                <DialogDescription className="sr-only">Form pengajuan izin</DialogDescription>
              </DialogHeader>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6 p-6 sm:p-8">
              <div className="space-y-2">
                <Label>
                  Pilih Sesi / Kelas <span className="text-red-500">*</span>
                </Label>
                <Select
                  required
                  value={formData.session_id}
                  onValueChange={(val) => setFormData({ ...formData, session_id: val })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Pilih Sesi yang akan diizinkan" />
                  </SelectTrigger>
                  <SelectContent>
                    {sessions.map((s) => (
                      <SelectItem key={s.id} value={s.id}>
                        {s.title} (
                        {(() => {
                          const labels = (s.session_classes ?? []).flatMap((x: any) => {
                            const result = formatClassLabel(x?.class);
                            return result ? [result] : [];
                          });
                          if (labels.length) return labels.join(', ');
                          return s.class ? formatClassLabel(s.class) : 'Umum';
                        })()}
                        ) - {format(new Date(s.session_start), 'dd MMM', { locale: id })}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>
                  Jenis Izin <span className="text-red-500">*</span>
                </Label>
                <Select
                  required
                  value={formData.reason}
                  onValueChange={(val) => setFormData({ ...formData, reason: val })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="SICK">Sakit</SelectItem>
                    <SelectItem value="EXCUSED">Izin (Kegiatan/Lainnya)</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>
                  Keterangan <span className="text-red-500">*</span>
                </Label>
                <Input
                  type="text"
                  required
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  placeholder="Mohon sebutkan alasan izin/sakit..."
                />
              </div>

              <div className="space-y-2">
                <Label>
                  Foto Bukti (wajib foto baru) <span className="text-red-500">*</span>
                </Label>
                {cameraError ? <div className="text-xs text-red-600">{cameraError}</div> : null}

                {!isCameraActive && !photoBlob ? (
                  <div className="flex flex-wrap items-center gap-2">
                    <Button
                      type="button"
                      variant="outline"
                      className="min-h-11"
                      disabled={!formData.session_id || cameraStarting}
                      onClick={() => void startCamera()}
                    >
                      {cameraStarting ? 'Membuka kameraΓÇª' : 'Buka Kamera'}
                    </Button>
                    <Button
                      type="button"
                      variant="ghost"
                      className="min-h-11"
                      disabled={!formData.session_id || cameraStarting}
                      onClick={switchCamera}
                    >
                      Ganti Kamera
                    </Button>
                  </div>
                ) : null}

                {/*
                  FIX: The <video> element is always in the DOM. We use `hidden` (display:none)
                  to avoid layout/interaction issues when the camera is inactive. The stream
                  is assigned via a useEffect + requestAnimationFrame after isCameraActive
                  flips to true and React removes the `hidden` class, ensuring the video
                  decoder activates on a visible element (mobile Android Chrome skips
                  decoder init on display:none elements).
                */}
                <div
                  className={cn(
                    'space-y-3 rounded-xl border border-border bg-muted/10 p-3',
                    !isCameraActive && 'hidden'
                  )}
                >
                  <video
                    ref={videoRef}
                    autoPlay
                    className="aspect-video w-full rounded-lg bg-black object-cover pointer-events-none"
                    playsInline
                    muted
                  />
                  <div className="flex flex-wrap items-center justify-between gap-2">
                    <Button
                      type="button"
                      variant="outline"
                      className="min-h-11"
                      onClick={switchCamera}
                    >
                      Ganti Kamera
                    </Button>
                    <Button type="button" className="min-h-11" onClick={takePhoto}>
                      Ambil Foto
                    </Button>
                    <Button type="button" variant="ghost" className="min-h-11" onClick={stopCamera}>
                      Tutup
                    </Button>
                  </div>
                  <canvas ref={canvasRef} className="hidden" />
                </div>

                {photoPreviewUrl ? (
                  <div className="space-y-3 rounded-xl border border-border bg-muted/10 p-3">
                    <img
                      src={photoPreviewUrl}
                      alt="Pratinjau foto bukti"
                      className="mx-auto max-h-56 rounded-lg object-contain"
                    />
                    <div className="flex flex-wrap items-center justify-end gap-2">
                      <Button
                        type="button"
                        variant="outline"
                        className="min-h-11"
                        onClick={retakePhoto}
                      >
                        Foto Ulang
                      </Button>
                      <Button
                        type="button"
                        variant="ghost"
                        className="min-h-11"
                        onClick={clearPhoto}
                      >
                        Hapus
                      </Button>
                    </div>
                  </div>
                ) : null}
              </div>

              <DialogFooter className="mt-4 gap-4 sm:gap-3">
                <Button
                  type="button"
                  variant="outline"
                  className="min-h-11"
                  disabled={submitting}
                  onClick={() => setIsModalOpen(false)}
                >
                  Batal
                </Button>
                <Button
                  type="submit"
                  className="min-h-11"
                  disabled={submitting}
                  aria-busy={submitting}
                >
                  {submitting ? (
                    <>
                      <Loader2 className="mr-2 size-4 animate-spin" aria-hidden="true" />
                      MengirimΓÇª
                    </>
                  ) : (
                    'Kirim Pengajuan'
                  )}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>

        <ConfirmModal
          isOpen={Boolean(reviewConfirm)}
          onClose={() => setReviewConfirm(null)}
          onConfirm={() => void confirmReview()}
          title={
            reviewConfirm?.status === 'APPROVED'
              ? 'Setujui pengajuan izin?'
              : 'Tolak pengajuan izin?'
          }
          description={
            reviewConfirm
              ? `Pengajuan dari ${reviewConfirm.studentName} akan ${
                  reviewConfirm.status === 'APPROVED' ? 'disetujui' : 'ditolak'
                } dan status kehadiran disesuaikan.`
              : ''
          }
          confirmText={reviewConfirm?.status === 'APPROVED' ? 'Ya, Setujui' : 'Ya, Tolak'}
          variant={reviewConfirm?.status === 'REJECTED' ? 'danger' : 'primary'}
        />
      </AdminPageShell>
    </>
  );
}

import React, { useEffect, useState } from 'react';
import api from '@/services/api';
import useSWR from 'swr';
import {
  Calendar,
  CheckCircle2,
  Clock,
  XCircle,
  MapPin,
  Smartphone,
  Camera,
  History as HistoryIcon,
  FileText,
} from 'lucide-react';
import { format } from 'date-fns';
import { id } from 'date-fns/locale';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Skeleton } from '@/components/ui/skeleton';
import AdminPageShell from '@/components/AdminPageShell';
import { AdminEmptyState } from '@/components/admin/AdminEmptyState';
import { CardSkeletonList } from '@/components/admin/CardSkeleton';
import type { AttendanceHistory } from '@/types/report';
import type { PaginationMeta } from '@/types/common';
import { useSwrPageState } from '@/hooks/useSwrPageState';
import { ErrorWithRetry } from '@/components/ErrorWithRetry';
import { TablePagination } from '@/components/ui/TablePagination';
import { attendanceBadgeVariant, attendanceStatusLabel } from '@/lib/utils/statusLabel';

const fetcher = (url: string) => api.get(url).then((res) => res.data);

export default function HistoryPage() {
  const [filter, setFilter] = useState('ALL');
  const [page, setPage] = useState(1);

  useEffect(() => {
    setPage(1);
  }, [filter]);

  const queryParams = new URLSearchParams({ page: String(page), limit: '20' });
  if (filter !== 'ALL') queryParams.set('status', filter);
  const swr = useSWR(`/reports?${queryParams.toString()}`, fetcher, { revalidateOnFocus: false });
  const { isPending, isError, retry } = useSwrPageState(swr);
  const history: AttendanceHistory[] = Array.isArray(swr.data?.data) ? swr.data.data : [];
  const meta: PaginationMeta | null = swr.data?.meta ?? null;
  const hasFilters = filter !== 'ALL';

  const filteredHistory = history;

  return (
    <AdminPageShell
      title="Riwayat Kehadiran"
      description="Pantau semua catatan absensimu sepanjang semester di sini."
      variant="plain"
      icon={<HistoryIcon className="size-5" />}
    >
      <div className="flex items-center gap-2 overflow-x-auto pb-2 scrollbar-hide">
        {['ALL', 'PRESENT', 'LATE', 'EXCUSED', 'ABSENT'].map((statusOption) => (
          <Button
            key={statusOption}
            variant={filter === statusOption ? 'default' : 'outline'}
            onClick={() => setFilter(statusOption)}
            className={`rounded-full ${filter === statusOption ? 'shadow-md shadow-indigo-500/30' : ''}`}
          >
            {statusOption === 'ALL'
              ? 'Semua Riwayat'
              : statusOption === 'PRESENT'
                ? 'Hadir Tepat Waktu'
                : statusOption === 'LATE'
                  ? 'Terlambat'
                  : statusOption === 'EXCUSED'
                    ? 'Sakit / Izin'
                    : 'Alfa'}
          </Button>
        ))}
      </div>

      {isError ? (
        <ErrorWithRetry
          title="Gagal memuat riwayat"
          error={swr.error ?? 'Permintaan membutuhkan waktu lebih lama dari biasanya.'}
          onRetry={retry}
        />
      ) : isPending ? (
        <>
          <div className="md:hidden">
            <CardSkeletonList count={4} />
          </div>
          <div className="hidden overflow-hidden rounded-xl border border-border bg-card shadow-card dark:shadow-none dark:ring-1 dark:ring-white/10 md:block">
            <div className="overflow-x-auto">
              <Table className="min-w-[800px]">
                <TableHeader className="sticky top-0 z-10 bg-muted/50 [&_tr]:border-b">
                  <TableRow>
                    <TableHead>Kelas / Sesi</TableHead>
                    <TableHead>Jadwal (Waktu Check-in)</TableHead>
                    <TableHead>Perangkat & IP</TableHead>
                    <TableHead>Bukti</TableHead>
                    <TableHead className="text-right">Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {Array.from({ length: 5 }).map((_, idx) => (
                    <TableRow key={idx}>
                      <TableCell>
                        <Skeleton className="mb-2 h-5 w-40" />
                        <Skeleton className="h-4 w-24" />
                      </TableCell>
                      <TableCell>
                        <Skeleton className="mb-2 h-4 w-32" />
                        <Skeleton className="h-4 w-24" />
                      </TableCell>
                      <TableCell>
                        <Skeleton className="mb-2 h-4 w-24" />
                        <Skeleton className="h-4 w-20" />
                      </TableCell>
                      <TableCell>
                        <Skeleton className="h-4 w-16" />
                      </TableCell>
                      <TableCell className="text-right">
                        <Skeleton className="ml-auto h-6 w-24 rounded-full" />
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </div>
        </>
      ) : filteredHistory.length === 0 ? (
        <div className="px-1 py-2 md:px-0 md:py-0">
          <AdminEmptyState
            compact
            icon={HistoryIcon}
            hasFilters={hasFilters}
            title={hasFilters ? undefined : 'Belum Ada Riwayat'}
            description={hasFilters ? undefined : 'Kamu belum mengikuti sesi kelas apa pun.'}
          />
        </div>
      ) : (
        <div className="overflow-hidden rounded-xl border border-border bg-card shadow-card dark:shadow-none dark:ring-1 dark:ring-white/10 md:bg-card max-md:border-0 max-md:bg-transparent max-md:shadow-none max-md:dark:ring-0">
          {/* [UX] #18 ΓÇö kartu mobile */}
          <ul className="space-y-3 p-5 md:hidden" aria-label="Riwayat kehadiran">
            {filteredHistory.map((item) => (
              <li key={item.id} className="rounded-2xl border border-border bg-card p-4">
                <p className="font-bold text-foreground">{item.session_title}</p>
                <p className="text-sm text-brand">{item.class_name || 'Umum'}</p>
                <div className="mt-2 flex flex-col gap-1 text-sm text-muted-foreground">
                  <div className="flex items-center gap-1.5">
                    <Calendar size={14} className="shrink-0 text-indigo-500" aria-hidden="true" />
                    <span>
                      {format(new Date(item.session_date), 'dd MMM yyyy', { locale: id })}
                    </span>
                  </div>
                  <div className="flex items-center gap-1.5">
                    <Clock size={14} className="shrink-0" aria-hidden="true" />
                    <span>{format(new Date(item.check_in_time), 'HH:mm:ss')} WIB</span>
                  </div>
                </div>
                <div className="mt-2 flex flex-col gap-1 text-xs text-muted-foreground">
                  <div className="flex items-center gap-1.5">
                    <Smartphone size={14} className="shrink-0" aria-hidden="true" />
                    <span className="truncate" title={item.device}>
                      {item.device || 'Perangkat tidak diketahui'}
                    </span>
                  </div>
                  <div className="flex items-center gap-1.5">
                    <MapPin size={14} className="shrink-0" aria-hidden="true" />
                    <span className="font-mono">{item.ip || 'N/A'}</span>
                  </div>
                  {item.photo_url ? (
                    <a
                      href={item.photo_url}
                      target="_blank"
                      rel="noreferrer"
                      className="inline-flex items-center gap-1 text-brand"
                    >
                      <Camera size={14} aria-hidden="true" /> Lihat bukti foto
                    </a>
                  ) : null}
                </div>
                <div className="mt-3 flex justify-end">
                  <Badge
                    variant={attendanceBadgeVariant(item.status)}
                    className="gap-1.5 px-3 py-1"
                  >
                    {item.status === 'PRESENT' && <CheckCircle2 className="size-3.5" />}
                    {item.status === 'LATE' && <Clock className="size-3.5" />}
                    {(item.status === 'SICK' || item.status === 'EXCUSED') && (
                      <FileText className="size-3.5" />
                    )}
                    {item.status === 'ABSENT' && <XCircle className="size-3.5" />}
                    {attendanceStatusLabel(item.status)}
                  </Badge>
                </div>
              </li>
            ))}
          </ul>
          <div className="hidden md:block">
            <div className="overflow-x-auto">
              <Table className="min-w-[800px]">
                <TableHeader className="sticky top-0 z-10 bg-muted/50 [&_tr]:border-b">
                  <TableRow>
                    <TableHead>Kelas / Sesi</TableHead>
                    <TableHead>Jadwal (Waktu Check-in)</TableHead>
                    <TableHead>Perangkat & IP</TableHead>
                    <TableHead>Bukti</TableHead>
                    <TableHead className="text-right">Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredHistory.map((item) => (
                    <TableRow key={item.id}>
                      <TableCell>
                        <div className="font-bold text-foreground text-base">
                          {item.session_title}
                        </div>
                        {item.class_name && (
                          <p className="text-sm font-semibold text-brand text-brand mt-0.5">
                            {typeof item.class_name === 'object' && item.class_name !== null
                              ? (item.class_name as any).name || (item.class_name as any).id
                              : item.class_name}
                          </p>
                        )}
                      </TableCell>
                      <TableCell>
                        <div className="flex flex-col gap-1.5 text-muted-foreground">
                          <div className="flex items-center gap-2">
                            <Calendar size={14} className="text-indigo-500" />
                            <span className="font-medium">
                              {format(new Date(item.session_date), 'dd MMM yyyy', { locale: id })}
                            </span>
                          </div>
                          <div className="flex items-center gap-2 text-sm text-muted-foreground">
                            <Clock size={14} />
                            {format(new Date(item.check_in_time), 'HH:mm:ss')} WIB
                          </div>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex flex-col gap-1 text-xs text-muted-foreground">
                          <div className="flex items-center gap-1.5">
                            <Smartphone size={14} className="text-slate-400 shrink-0" />
                            <span className="truncate max-w-[150px]" title={item.device}>
                              {item.device || 'Perangkat tidak diketahui'}
                            </span>
                          </div>
                          <div className="flex items-center gap-1.5">
                            <MapPin size={14} className="text-slate-400 shrink-0" />
                            <span className="font-mono">{item.ip || 'N/A'}</span>
                          </div>
                        </div>
                      </TableCell>
                      <TableCell>
                        {item.photo_url ? (
                          <a
                            href={item.photo_url}
                            target="_blank"
                            rel="noreferrer"
                            className="text-brand hover:text-indigo-700 hover:underline flex items-center gap-1.5 text-sm font-medium"
                          >
                            <Camera size={14} /> Lihat Foto
                          </a>
                        ) : (
                          <span className="text-slate-400 dark:text-zinc-600 text-sm italic">
                            -
                          </span>
                        )}
                      </TableCell>
                      <TableCell className="text-right">
                        <Badge
                          variant={attendanceBadgeVariant(item.status)}
                          className="gap-1.5 px-3 py-1"
                        >
                          {item.status === 'PRESENT' && <CheckCircle2 className="size-3.5" />}
                          {item.status === 'LATE' && <Clock className="size-3.5" />}
                          {(item.status === 'SICK' || item.status === 'EXCUSED') && (
                            <FileText className="size-3.5" />
                          )}
                          {item.status === 'ABSENT' && <XCircle className="size-3.5" />}
                          {attendanceStatusLabel(item.status)}
                        </Badge>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </div>
          {meta ? <TablePagination meta={meta} onPageChange={setPage} itemLabel="riwayat" /> : null}
        </div>
      )}
    </AdminPageShell>
  );
}

import React, { useState, useEffect } from 'react';
import api from '@/services/api';
import { Plus, Edit2, Trash2, Search, X, MapPin, LocateFixed } from 'lucide-react';
import { toast } from 'sonner';
import { MapContainer, TileLayer, Marker, Circle, useMapEvents } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import { MapResizeOnOpen } from '@/components/MapResizeOnOpen';
import useSWR from 'swr';
import { useSwrPageState } from '@/hooks/useSwrPageState';
import { useClientPagination } from '@/hooks/useClientPagination';
