const safeFormat = (value: unknown, fmt: string) => {
  const d = new Date(value as any);
  if (!isValid(d)) return '-';
  return format(d, fmt, { locale: id });
};

type ExportSessionMeta = {
  sessionId: string;
  sessionTitle: string;
  classesLabel: string;
  classSheets: string[];
};

async function buildSessionAttendUrl(sessionId: string): Promise<string> {
  try {
    const res = await api.get(`/sessions/${sessionId}/qr`);
    const token = res.data?.data?.token;
    if (token) {
      return `${window.location.origin}/attend?session=${sessionId}&token=${encodeURIComponent(token)}`;
    }
  } catch {
    /* fallback tanpa token */
  }
  return `${window.location.origin}/attend?session=${sessionId}`;
}

async function qrImageBase64(url: string): Promise<string> {
  const dataUrl = await QRCode.toDataURL(url, {
    width: 280,
    margin: 1,
    color: { dark: '#1e3a8a' },
  });
  return dataUrl.split(',')[1] ?? '';
}

export default function Reports() {
  const { user } = useAuthStore();
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('ALL');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [sessionId, setSessionId] = useState('ALL');
  const [exporting, setExporting] = useState<'none' | 'excel' | 'pdf'>('none');

  const [page, setPage] = useState(1);

  const queryParams = new URLSearchParams({
    page: page.toString(),
    limit: '50',
  });
  if (sessionId && sessionId !== 'ALL') {
    queryParams.append('sessionId', sessionId);
  }
  if (startDate) {
    queryParams.append('startDate', startDate);
  }
  if (endDate) {
    queryParams.append('endDate', endDate);
  }
  if (statusFilter !== 'ALL') {
    queryParams.append('status', statusFilter);
  }
  if (searchTerm.trim()) {
    queryParams.append('search', searchTerm.trim());
  }

  const swr = useSWR(`/reports?${queryParams.toString()}`, fetcher, { revalidateOnFocus: false });
  const { isPending: loading, isError, showSlowLoadingHint, retry } = useSwrPageState(swr);
  const { data, mutate } = swr;

  const reports: Report[] = Array.isArray(data?.data)
    ? (data.data.filter(Boolean) as Report[])
    : [];
  const meta: PaginationMeta | null = data?.meta || null;

  const sessionsFetcher = (url: string) => api.get(url).then((res) => res.data.data);
  const { data: sessions = [] } = useSWR<
    {
      id: string;
      title: string;
      session_start: string;
      class?: { name: string; semester: number } | null;
      session_classes?: { class: { name: string; semester: number } }[];
    }[]
  >('/sessions', sessionsFetcher, { revalidateOnFocus: false });

  useEffect(() => {
    setPage(1);
  }, [startDate, endDate, sessionId, statusFilter, searchTerm]);

  const filteredReports = useMemo(() => {
    const q = String(searchTerm ?? '').toLowerCase();
    return reports
      .filter((r): r is Report => Boolean(r && (r as any).id))
      .filter((r) => {
        const matchStatus = statusFilter === 'ALL' || r.status === statusFilter;
        const userName = String((r as any).user_name ?? '');
        const sessionTitle = String((r as any).session_title ?? '');
        const nim = String((r as any).nim_nip ?? '');
        const matchSearch =
          userName.toLowerCase().includes(q) ||
          sessionTitle.toLowerCase().includes(q) ||
          nim.toLowerCase().includes(q);
        return matchStatus && matchSearch;
      });
  }, [reports, statusFilter, searchTerm]);

  const hasFilters =
    Boolean(searchTerm.trim()) ||
    statusFilter !== 'ALL' ||
    Boolean(startDate) ||
    Boolean(endDate) ||
    sessionId !== 'ALL';

  // Override Modal State
  const [isOverrideModalOpen, setIsOverrideModalOpen] = useState(false);
  const [selectedReport, setSelectedReport] = useState<Report | null>(null);
  const [overrideStatus, setOverrideStatus] = useState('PRESENT');
  const [overrideNotes, setOverrideNotes] = useState('');
  const [overrideSubmitting, setOverrideSubmitting] = useState(false);
  const [isOverrideConfirmOpen, setIsOverrideConfirmOpen] = useState(false);
  const [filtersOpen, setFiltersOpen] = useState(false);

  const exportExcelMatrix = useCallback(
    async (rows: Report[], fileSuffix: string, sessionMeta?: ExportSessionMeta) => {
      const safeRows = (Array.isArray(rows) ? rows : []).filter((r): r is Report =>
        Boolean(r && (r as any).id)
      );
      const { default: ExcelJS } = await import('exceljs');
      const workbook = new ExcelJS.Workbook();

      if (sessionMeta?.sessionId) {
        const resolveAssetUrl = (assetUrl: string) => {
          if (!assetUrl) return '';
          if (assetUrl.startsWith('http') || assetUrl.startsWith('data:')) return assetUrl;
          const apiBase = String(import.meta.env.VITE_API_BASE_URL || '/api');
          const assetBase = apiBase.startsWith('http')
            ? new URL(apiBase).origin
            : apiBase.replace(/\/api\/?$/, '');
          return `${assetBase}${assetUrl}`;
        };

        const sheetNames = (sessionMeta.classSheets.length ? sessionMeta.classSheets : ['Kelas'])
          .map((s) => String(s || '').trim())
          .filter(Boolean);

        const usedNames = new Set<string>();
        const safeSheetName = (name: string) => {
          let base = name.replace(/[\\/*?:[\]]/g, ' ').trim() || 'Kelas';
          if (base.length > 31) base = base.slice(0, 31);
          let candidate = base;
          let idx = 2;
          while (usedNames.has(candidate)) {
            const suffix = ` (${idx})`;
            candidate = (base.slice(0, Math.max(0, 31 - suffix.length)) + suffix).trim();
            idx += 1;
          }
          usedNames.add(candidate);
          return candidate;
        };

        const orderedSheets = sheetNames.length ? sheetNames : ['Kelas'];
        for (const clsLabel of orderedSheets) {
          const sheet = workbook.addWorksheet(safeSheetName(clsLabel));
          sheet.columns = [
            { header: 'No', key: 'no', width: 6 },
            { header: 'Nama', key: 'user_name', width: 26 },
            { header: 'NIM/NIP', key: 'nim_nip', width: 16 },
            { header: 'Status', key: 'status', width: 12 },
            { header: 'Check-in', key: 'check_in', width: 20 },
            { header: 'Keterangan Izin', key: 'excuse_desc', width: 34 },
            { header: 'Bukti', key: 'proof', width: 22 },
          ];
          sheet.getRow(1).font = { bold: true };
          sheet.getRow(1).fill = {
            type: 'pattern',
            pattern: 'solid',
            fgColor: { argb: 'FFE0E7FF' },
          };

          const rowsForClass = safeRows.filter((r) => reportClassLabel(r) === clsLabel);
          rowsForClass.forEach((r, idx) => {
            const proofUrlRaw = (r as any).excuse_proof_url
              ? String((r as any).excuse_proof_url)
              : '';
            const proofUrl = proofUrlRaw ? resolveAssetUrl(proofUrlRaw) : '';
            const row = sheet.addRow({
              no: idx + 1,
              user_name: String((r as any).user_name ?? '-'),
              nim_nip: r.nim_nip || '-',
              status: r.status,
              check_in: safeFormat((r as any).check_in_time, 'dd/MM/yyyy HH:mm'),
              excuse_desc: String((r as any).excuse_description ?? ''),
              proof: proofUrl ? 'Lihat' : '',
            });
            if (proofUrl) {
              const cell = row.getCell('proof');
              cell.value = { text: 'Lihat', hyperlink: proofUrl };
              cell.font = { color: { argb: 'FF2563EB' }, underline: true };
            }
          });
        }

        const sheetLabelSet = new Set(orderedSheets);
        const otherRows = safeRows.filter((r) => !sheetLabelSet.has(reportClassLabel(r)));
        if (otherRows.length) {
          const sheet = workbook.addWorksheet(safeSheetName('Lainnya'));
          sheet.columns = [
            { header: 'No', key: 'no', width: 6 },
            { header: 'Nama', key: 'user_name', width: 26 },
            { header: 'NIM/NIP', key: 'nim_nip', width: 16 },
            { header: 'Kelas', key: 'kelas', width: 22 },
            { header: 'Status', key: 'status', width: 12 },
            { header: 'Check-in', key: 'check_in', width: 20 },
            { header: 'Keterangan Izin', key: 'excuse_desc', width: 34 },
            { header: 'Bukti', key: 'proof', width: 22 },
          ];
          sheet.getRow(1).font = { bold: true };
          sheet.getRow(1).fill = {
            type: 'pattern',
            pattern: 'solid',
            fgColor: { argb: 'FFE0E7FF' },
          };
          otherRows.forEach((r, idx) => {
            const proofUrlRaw = (r as any).excuse_proof_url
              ? String((r as any).excuse_proof_url)
              : '';
            const proofUrl = proofUrlRaw ? resolveAssetUrl(proofUrlRaw) : '';
            const row = sheet.addRow({
              no: idx + 1,
              user_name: String((r as any).user_name ?? '-'),
              nim_nip: r.nim_nip || '-',
              kelas: reportClassLabel(r),
              status: r.status,
              check_in: safeFormat((r as any).check_in_time, 'dd/MM/yyyy HH:mm'),
              excuse_desc: String((r as any).excuse_description ?? ''),
              proof: proofUrl ? 'Lihat' : '',
            });
            if (proofUrl) {
              const cell = row.getCell('proof');
              cell.value = { text: 'Lihat', hyperlink: proofUrl };
              cell.font = { color: { argb: 'FF2563EB' }, underline: true };
            }
          });
        }

        const qrSheet = workbook.addWorksheet('QR Scan Absensi');
        const attendUrl = await buildSessionAttendUrl(sessionMeta.sessionId);
        qrSheet.mergeCells('A1', 'D1');
        qrSheet.getCell('A1').value = `QR Absensi ΓÇö ${sessionMeta.sessionTitle}`;
        qrSheet.getCell('A1').font = { bold: true, size: 14 };
        qrSheet.getCell('A2').value = `Kelas: ${sessionMeta.classesLabel}`;
        qrSheet.getCell('A3').value = 'Tautan scan (buka di browser HP):';
        qrSheet.getCell('A4').value = attendUrl;
        qrSheet.getCell('A4').font = { color: { argb: 'FF2563EB' }, underline: true };
        try {
          const base64 = await qrImageBase64(attendUrl);
          const imageId = workbook.addImage({ base64, extension: 'png' });
          qrSheet.addImage(imageId, { tl: { col: 0, row: 5 }, ext: { width: 220, height: 220 } });
        } catch {
          qrSheet.getCell('A6').value = '(QR gagal dibuat ΓÇö gunakan tautan di atas)';
        }
        qrSheet.getColumn(1).width = 72;

        const buffer = await workbook.xlsx.writeBuffer();
        const blob = new Blob([buffer], {
          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `Rekap_Sesi_${fileSuffix}_${format(new Date(), 'yyyyMMdd_HHmm')}.xlsx`;
        link.click();
        URL.revokeObjectURL(url);
        toast.success('Laporan Excel berhasil diunduh');
        return;
      }

      const sheet = workbook.addWorksheet('Rekap Matriks Kehadiran');

      // Dapatkan daftar sesi unik dari laporan yang difilter
      const uniqueSessions = Array.from(
        new Set(safeRows.map((r) => String((r as any).session_title ?? '')))
      ).filter(Boolean);

      // Siapkan kolom: Nama, NIM, Kelas, lalu diikuti nama-nama sesi
      const columns = [
        { header: 'Nama Peserta', key: 'user_name', width: 25 },
        { header: 'NIM/NIP', key: 'nim_nip', width: 15 },
        { header: 'Kelas', key: 'kelas', width: 22 },
      ];
      uniqueSessions.forEach((session) => {
        columns.push({ header: session, key: session, width: 15 });
      });
      // Tambahkan kolom rekap total
      columns.push({ header: 'Total Hadir', key: 'total_present', width: 15 });
      columns.push({ header: 'Total Sakit', key: 'total_sick', width: 15 });
      columns.push({ header: 'Total Izin', key: 'total_excused', width: 15 });
      columns.push({ header: 'Total Alfa', key: 'total_absent', width: 15 });

      sheet.columns = columns;

      sheet.getRow(1).font = { bold: true };
      sheet.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE0E7FF' } };

      // Kelompokkan data per mahasiswa
      const studentData: Record<string, Record<string, string | number>> = {};

      safeRows.forEach((r) => {
        const studentId = r.user_id;
        if (!studentId) return;
        if (!studentData[studentId]) {
          studentData[studentId] = {
            user_name: String((r as any).user_name ?? '-'),
            nim_nip: r.nim_nip || '-',
            kelas: reportClassLabel(r),
            total_present: 0,
            total_sick: 0,
            total_excused: 0,
            total_absent: 0,
          };
        }

        // Isi status sesi
        const sessionTitle = String((r as any).session_title ?? '-');
        studentData[studentId][sessionTitle] = r.status;

        // Hitung total
        if (r.status === 'PRESENT' || r.status === 'LATE')
          (studentData[studentId].total_present as number) += 1;
        else if (r.status === 'SICK') (studentData[studentId].total_sick as number) += 1;
        else if (r.status === 'EXCUSED') (studentData[studentId].total_excused as number) += 1;
        else if (r.status === 'ABSENT') (studentData[studentId].total_absent as number) += 1;
      });

      Object.values(studentData).forEach((data) => {
        sheet.addRow(data);
      });

      if (sessionMeta?.sessionId) {
        const qrSheet = workbook.addWorksheet('QR Scan Absensi');
        const attendUrl = await buildSessionAttendUrl(sessionMeta.sessionId);
        qrSheet.mergeCells('A1', 'D1');
        qrSheet.getCell('A1').value = `QR Absensi ΓÇö ${sessionMeta.sessionTitle}`;
        qrSheet.getCell('A1').font = { bold: true, size: 14 };
        qrSheet.getCell('A2').value = `Kelas: ${sessionMeta.classesLabel}`;
        qrSheet.getCell('A3').value = 'Tautan scan (buka di browser HP):';
        qrSheet.getCell('A4').value = attendUrl;
        qrSheet.getCell('A4').font = { color: { argb: 'FF2563EB' }, underline: true };
        try {
          const base64 = await qrImageBase64(attendUrl);
          const imageId = workbook.addImage({ base64, extension: 'png' });
          qrSheet.addImage(imageId, { tl: { col: 0, row: 5 }, ext: { width: 220, height: 220 } });
        } catch {
          qrSheet.getCell('A6').value = '(QR gagal dibuat ΓÇö gunakan tautan di atas)';
        }
        qrSheet.getColumn(1).width = 72;
      }

      const buffer = await workbook.xlsx.writeBuffer();
      const blob = new Blob([buffer], {
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `Matriks_Kehadiran_${fileSuffix}_${format(new Date(), 'yyyyMMdd_HHmm')}.xlsx`;
      link.click();
      URL.revokeObjectURL(url);
      toast.success('Matriks Laporan Excel berhasil diunduh');
    },
    []
  );

  const exportPdfList = useCallback(
    async (rows: Report[], fileSuffix: string, sessionMeta?: ExportSessionMeta) => {
      const safeRows = (Array.isArray(rows) ? rows : []).filter((r): r is Report =>
        Boolean(r && (r as any).id)
      );
      const [{ default: jsPDF }, { default: autoTable }] = await Promise.all([
        import('jspdf'),
        import('jspdf-autotable'),
      ]);
      const doc = new jsPDF();

      let tableStartY = 35;

      doc.setFontSize(16);
      doc.text('Laporan Rekapitulasi Kehadiran', 14, 20);
      doc.setFontSize(10);
      doc.text(`Dicetak pada: ${format(new Date(), 'dd MMMM yyyy HH:mm', { locale: id })}`, 14, 28);

      if (sessionMeta?.sessionId) {
        const attendUrl = await buildSessionAttendUrl(sessionMeta.sessionId);
        doc.setFontSize(11);
        doc.text(`Sesi: ${sessionMeta.sessionTitle}`, 14, 36);
        doc.text(`Kelas: ${sessionMeta.classesLabel}`, 14, 42);
        try {
          const base64 = await qrImageBase64(attendUrl);
          doc.addImage(`data:image/png;base64,${base64}`, 'PNG', 150, 14, 48, 48);
        } catch {
          /* tanpa gambar QR */
        }
        doc.setFontSize(8);
        doc.text('QR / tautan scan absensi:', 14, 50);
        doc.text(doc.splitTextToSize(attendUrl, 130), 14, 55);
        tableStartY = 68;
      }

      const tableData = safeRows.map((r) => [
        String((r as any).user_name ?? '-'),
        r.nim_nip || '-',
        reportClassLabel(r),
        String((r as any).session_title ?? '-'),
        safeFormat((r as any).session_date, 'dd/MM/yyyy'),
        safeFormat((r as any).check_in_time, 'HH:mm:ss'),
        (r as any).status ?? '-',
      ]);

      autoTable(doc, {
        head: [['Nama', 'NIM/NIP', 'Kelas', 'Sesi', 'Tanggal', 'Waktu', 'Status']],
        body: tableData,
        startY: tableStartY,
        theme: 'grid',
        styles: { fontSize: 8 },
        headStyles: { fillColor: [79, 70, 229] },
      });

      doc.save(`Rekap_Kehadiran_${fileSuffix}_${format(new Date(), 'yyyyMMdd_HHmm')}.pdf`);
      toast.success('Laporan PDF berhasil diunduh');
    },
    []
  );

  const fetchAllReports = useCallback(
    async (sid?: string) => {
      const limit = 500;
      let p = 1;
      const all: Report[] = [];
      while (true) {
        const params = new URLSearchParams({ page: String(p), limit: String(limit) });
        if (sid) params.set('sessionId', sid);
        if (sid) params.set('withClassBreakdown', '1');
        params.set('withSummary', '0');
        if (startDate) params.set('startDate', startDate);
        if (endDate) params.set('endDate', endDate);
        if (statusFilter !== 'ALL') params.set('status', statusFilter);
        if (searchTerm.trim()) params.set('search', searchTerm.trim());
        const res = await api.get(`/reports?${params.toString()}`);
        const chunk: Report[] = res.data?.data || [];
        const m: PaginationMeta | undefined = res.data?.meta;
        all.push(...chunk);
        if (!m || p >= m.totalPages) break;
        p += 1;
      }
      return all;
    },
    [endDate, searchTerm, startDate, statusFilter]
  );

  const sessionExportMeta = useCallback((): ExportSessionMeta | undefined => {
    if (sessionId === 'ALL') return undefined;
    const s = sessions.find((x) => x.id === sessionId);
    if (!s) return undefined;
    const labels = (s.session_classes ?? []).flatMap((x: any) => {
      const result = formatClassLabel(x?.class);
      return result ? [result] : [];
    });
    const classesLabel = labels.length
      ? labels.join(', ')
      : s.class
        ? formatClassLabel(s.class)
        : 'Umum';
    const classSheets = labels.length ? labels : s.class ? [formatClassLabel(s.class)] : ['Umum'];
    return { sessionId, sessionTitle: s.title, classesLabel, classSheets };
  }, [sessionId, sessions]);

  const handleExportExcel = useCallback(async () => {
    const sanitize = (s: string) =>
      s
        .replace(/[^a-z0-9]+/gi, '_')
        .replace(/^_+|_+$/g, '')
        .slice(0, 40) || 'Sesi';
    try {
      setExporting('excel');
      const meta = sessionExportMeta();
      if (sessionId !== 'ALL') {
        const rows = await fetchAllReports(sessionId);
        const title = sessions.find((s) => s.id === sessionId)?.title || 'Sesi';
        await exportExcelMatrix(rows, sanitize(title), meta);
        toast.success('Excel berhasil diunduh');
        return;
      }
      await exportExcelMatrix(await fetchAllReports(), 'Semua');
      toast.success('Excel berhasil diunduh');
    } catch (err: unknown) {
      toast.error(toastErrorMessage(err, 'Gagal export Excel'));
    } finally {
      setExporting('none');
    }
  }, [exportExcelMatrix, fetchAllReports, sessionExportMeta, sessionId, sessions, statusFilter]);

  const handleExportPDF = useCallback(async () => {
    const sanitize = (s: string) =>
      s
        .replace(/[^a-z0-9]+/gi, '_')
        .replace(/^_+|_+$/g, '')
        .slice(0, 40) || 'Sesi';
    try {
      setExporting('pdf');
      const meta = sessionExportMeta();
      if (sessionId !== 'ALL') {
        const rows = await fetchAllReports(sessionId);
        const title = sessions.find((s) => s.id === sessionId)?.title || 'Sesi';
        await exportPdfList(rows, sanitize(title), meta);
        toast.success('PDF berhasil diunduh');
        return;
      }
      await exportPdfList(await fetchAllReports(), 'Semua');
      toast.success('PDF berhasil diunduh');
    } catch (err: unknown) {
      toast.error(toastErrorMessage(err, 'Gagal export PDF'));
    } finally {
      setExporting('none');
    }
  }, [exportPdfList, fetchAllReports, sessionExportMeta, sessionId, sessions, statusFilter]);

  const handleOpenOverride = (report: Report) => {
    setSelectedReport(report);
    setOverrideStatus(report.status);
    setOverrideNotes('');
    setIsOverrideModalOpen(true);
  };

  const handleOverrideSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedReport || overrideSubmitting) return;

    setOverrideSubmitting(true);
    try {
      await api.post('/attendance/override', {
        session_id: selectedReport.session_id,
        user_id: selectedReport.user_id,
        status: overrideStatus,
        notes: overrideNotes,
      });

      toast.success('Status kehadiran berhasil diubah');
      setIsOverrideConfirmOpen(false);
      setIsOverrideModalOpen(false);

      // Refresh reports
      mutate();
    } catch (error: unknown) {
      toast.error(toastErrorMessage(error, 'Gagal mengubah status'));
    } finally {
      setOverrideSubmitting(false);
    }
  };

  return (
    <AdminPageShell
      title="Rekap Kehadiran"
      description="Filter data lalu export ke Excel atau PDF."
      variant="plain"
      icon={<FileText className="size-5" />}
      actions={
        <>
          <Button
            onClick={handleExportExcel}
            disabled={exporting !== 'none'}
            className="bg-emerald-600 text-white hover:bg-emerald-700"
            aria-busy={exporting === 'excel'}
          >
            <Download className="mr-2 size-4" aria-hidden="true" />
            {exporting === 'excel' ? 'Menyiapkan ExcelΓÇª' : 'Export Excel'}
          </Button>
          <Button
            onClick={handleExportPDF}
            disabled={exporting !== 'none'}
            variant="destructive"
            aria-busy={exporting === 'pdf'}
          >
            <FileText className="mr-2 size-4" aria-hidden="true" />
            {exporting === 'pdf' ? 'Menyiapkan PDFΓÇª' : 'Export PDF'}
          </Button>
        </>
      }
    >
      {isError ? (
        <ErrorWithRetry title="Gagal memuat rekap" error={swr.error} onRetry={retry} />
      ) : (
        <div className="overflow-hidden rounded-xl border border-border bg-card shadow-card dark:shadow-none dark:ring-1 dark:ring-white/10">
          <div className="shrink-0 border-b border-border p-5">
            <button
              type="button"
              className="mb-3 flex min-h-11 w-full items-center justify-between rounded-xl border border-border bg-muted px-4 py-3 text-sm font-semibold text-foreground md:hidden"
              aria-expanded={filtersOpen}
              onClick={() => setFiltersOpen((v) => !v)}
            >
              Filter &amp; pencarian
              <ChevronDown
                className={`h-5 w-5 transition-transform ${filtersOpen ? 'rotate-180' : ''}`}
                aria-hidden="true"
              />
            </button>
            <FadeIn
              className={`flex flex-col gap-4 sm:flex-row sm:items-end ${filtersOpen ? 'flex' : 'hidden md:flex'}`}
            >
              <div className="relative min-w-0 flex-1">
                <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-400" />
                <Input
                  type="text"
                  placeholder="Cari nama, NIM, atau sesi..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-9"
                  aria-describedby="reports-search-hint"
                />
              </div>
              <div className="flex w-full items-center gap-2 sm:w-auto">
                <DatePicker
                  value={startDate}
                  onChange={setStartDate}
                  placeholder="Dari tanggal"
                  className="w-full sm:w-[160px]"
                />
                <span
                  className="flex h-11 shrink-0 items-center px-0.5 text-muted-foreground"
                  aria-hidden="true"
                >
                  ΓÇô
                </span>
                <DatePicker
                  value={endDate}
                  onChange={setEndDate}
                  placeholder="Sampai tanggal"
                  className="w-full sm:w-[160px]"
                  popoverAlign="end"
                />
              </div>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-full sm:w-[180px]">
                  <SelectValue placeholder="Semua Status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ALL">Semua Status</SelectItem>
                  <SelectItem value="PRESENT">Hadir</SelectItem>
                  <SelectItem value="LATE">Terlambat</SelectItem>
                  <SelectItem value="SICK">Sakit</SelectItem>
                  <SelectItem value="EXCUSED">Izin</SelectItem>
                  <SelectItem value="ABSENT">Tidak Hadir</SelectItem>
                </SelectContent>
              </Select>
              <Select value={sessionId} onValueChange={setSessionId}>
                <SelectTrigger className="w-full sm:w-[260px]">
                  <SelectValue placeholder="Semua Sesi" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ALL">Semua Sesi</SelectItem>
                  {sessions.map((s) => {
                    const labels = (s.session_classes ?? []).flatMap((x: any) => {
                      const result = formatClassLabel(x?.class);
                      return result ? [result] : [];
                    });
                    const classesLabel = labels.length
                      ? labels.join(', ')
                      : s.class
                        ? formatClassLabel(s.class)
                        : 'Umum';
                    return (
                      <SelectItem key={s.id} value={s.id}>
                        {s.title} ({classesLabel}) - {safeFormat(s.session_start, 'dd MMM')}
                      </SelectItem>
                    );
                  })}
                </SelectContent>
              </Select>
            </FadeIn>
            <p id="reports-search-hint" className="mt-3 text-xs text-muted-foreground">
              Pencarian memfilter data di halaman ini ({filteredReports.length} baris).
            </p>
          </div>

          <ul className="space-y-3 p-5 md:hidden" aria-label="Daftar laporan kehadiran">
            {showSlowLoadingHint ? (
              <li>
                <SlowLoadingHint onRetry={retry} />
              </li>
            ) : null}
            {loading ? (
              <li>
                <CardSkeletonList count={4} />
              </li>
            ) : filteredReports.length === 0 ? (
              <li>
                <AdminEmptyState compact icon={FileText} hasFilters={hasFilters} />
              </li>
            ) : (
              filteredReports.map((report: Report, idx) => (
                <li
                  key={report.id ?? idx}
                  className="space-y-3 rounded-2xl border border-border p-5"
                >
                  <div className="flex items-start justify-between gap-3">
                    <div className="min-w-0 flex-1">
                      <p className="font-bold text-foreground">{report.user_name}</p>
                      <p className="text-sm text-muted-foreground">{report.nim_nip}</p>
                    </div>
                    <Badge
                      variant={attendanceBadgeVariant(report.status)}
                      className="shrink-0 gap-1"
                    >
                      {report.status === 'PRESENT' && <CheckCircle2 className="size-3" />}
                      {report.status === 'LATE' && <Clock className="size-3" />}
                      {(report.status === 'SICK' || report.status === 'EXCUSED') && (
                        <FileText className="size-3" />
                      )}
                      {report.status === 'ABSENT' && <XCircle className="size-3" />}
                      {attendanceStatusLabel(report.status)}
                    </Badge>
                  </div>
                  <p className="text-xs font-medium text-muted-foreground">
                    Kelas: {reportClassLabel(report)}
                  </p>
                  <p className="text-sm font-medium text-brand">{report.session_title}</p>
                  <p className="text-xs text-muted-foreground">
                    {safeFormat(report.session_date, 'dd MMM yyyy')} ┬╖{' '}
                    {safeFormat(report.check_in_time, 'HH:mm:ss')}
                  </p>
                  <div className="flex items-start gap-3">
                    {report.photo_url ? (
                      <a
                        href={report.photo_url}
                        target="_blank"
                        rel="noreferrer"
                        className="shrink-0 hover:opacity-80"
                      >
                        <img
                          src={report.photo_url}
                          alt="Bukti hadir"
                          className="size-12 rounded-md border border-border object-cover"
                        />
                      </a>
                    ) : (
                      <div className="flex size-12 shrink-0 items-center justify-center rounded-md bg-muted text-xs text-muted-foreground">
                        ΓÇö
                      </div>
                    )}
                    <div className="min-w-0 flex-1 space-y-1 text-xs text-muted-foreground">
                      <div className="flex items-center gap-1.5">
                        <MapPin size={12} className="shrink-0" aria-hidden="true" />
                        <span className="font-mono">IP: {report.ip || 'ΓÇö'}</span>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <Smartphone size={12} className="shrink-0" aria-hidden="true" />
                        <span className="truncate" title={report.device || undefined}>
                          {report.device || 'ΓÇö'}
                        </span>
                      </div>
                    </div>
                  </div>
                  {user?.role !== 'USER' ? (
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      className="min-h-11 w-full"
                      onClick={() => report?.id && handleOpenOverride(report)}
                    >
                      <Edit3 className="mr-2 size-4" aria-hidden="true" />
                      Override status
                    </Button>
                  ) : null}
                </li>
              ))
            )}
          </ul>

          <div className="hidden overflow-x-auto md:block">
            {showSlowLoadingHint ? (
              <div className="border-b border-border p-4">
                <SlowLoadingHint onRetry={retry} />
              </div>
            ) : null}
            <Table className="min-w-[800px]">
              <TableHeader className="sticky top-0 z-10 bg-muted/50 [&_tr]:border-b">
                <TableRow>
                  <TableHead>Peserta</TableHead>
                  <TableHead>Sesi / Kelas</TableHead>
                  <TableHead>Waktu Check-in</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Foto Bukti</TableHead>
                  <TableHead>Info Device/IP</TableHead>
                  {user?.role !== 'USER' && <TableHead className="text-right">Aksi</TableHead>}
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                  Array.from({ length: 10 }).map((_, idx) => (
                    <TableRow key={idx}>
                      <TableCell>
                        <Skeleton className="h-5 w-32 mb-2" />
                        <Skeleton className="h-4 w-24" />
                      </TableCell>
                      <TableCell>
                        <Skeleton className="h-5 w-40 mb-1" />
                        <Skeleton className="h-3 w-20 mb-2" />
                        <Skeleton className="h-4 w-32" />
                      </TableCell>
                      <TableCell>
                        <Skeleton className="h-5 w-24" />
                      </TableCell>
                      <TableCell>
                        <Skeleton className="h-6 w-24 rounded-full" />
                      </TableCell>
                      <TableCell>
                        <Skeleton className="h-4 w-32 mb-1" />
                        <Skeleton className="h-4 w-24" />
                      </TableCell>
                      {user?.role !== 'USER' && (
                        <TableCell className="text-right">
                          <Skeleton className="h-8 w-20 ml-auto rounded-md" />
                        </TableCell>
                      )}
                    </TableRow>
                  ))
                ) : filteredReports.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={user?.role !== 'USER' ? 7 : 6} className="p-0">
                      <AdminEmptyState
                        compact
                        icon={FileText}
                        hasFilters={hasFilters}
                        className="border-0 shadow-none"
                      />
                    </TableCell>
                  </TableRow>
                ) : (
                  (filteredReports ?? [])
                    .filter((r): r is Report => Boolean(r && (r as any).id))
                    .map((report: any, idx: number) => (
                      <TableRow key={String(report?.id ?? idx)}>
                        <TableCell>
                          <div className="font-medium text-foreground">
                            {String(report?.user_name ?? '-')}
                          </div>
                          <div className="text-sm text-muted-foreground">
                            {String(report?.nim_nip ?? '-') || '-'}
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="font-medium text-slate-800 dark:text-zinc-200">
                            {String(report?.session_title ?? '-')}
                          </div>
                          {report?.class_name && (
                            <div className="text-xs font-semibold text-brand text-brand mt-0.5">
                              {typeof report.class_name === 'object' && report.class_name !== null
                                ? (report.class_name as any).name || (report.class_name as any).id
                                : report.class_name}
                            </div>
                          )}
                          <div className="text-xs text-muted-foreground mt-1">
                            {safeFormat(report.session_date, 'dd MMMM yyyy')}
                          </div>
                        </TableCell>
                        <TableCell className="text-muted-foreground dark:text-zinc-300 font-medium">
                          {safeFormat(report.check_in_time, 'HH:mm:ss')}
                        </TableCell>
                        <TableCell>
                          <Badge variant={attendanceBadgeVariant(report.status)} className="gap-1">
                            {report.status === 'PRESENT' && (
                              <CheckCircle2 className="size-3 mr-1" />
                            )}
                            {report.status === 'LATE' && <Clock className="size-3 mr-1" />}
                            {(report.status === 'SICK' || report.status === 'EXCUSED') && (
                              <FileText className="size-3 mr-1" />
                            )}
                            {report.status === 'ABSENT' && <XCircle className="size-3 mr-1" />}
                            {attendanceStatusLabel(report.status)}
                          </Badge>
                        </TableCell>
                        <TableCell>
                          {report.photo_url ? (
                            <a
                              href={report.photo_url}
                              target="_blank"
                              rel="noreferrer"
                              className="inline-block hover:opacity-80 transition-opacity"
                            >
                              <img
                                src={report.photo_url}
                                alt="Bukti Hadir"
                                className="size-10 object-cover rounded-md shadow-sm border border-border"
                              />
                            </a>
                          ) : (
                            <div className="size-10 bg-muted rounded-md flex items-center justify-center text-xs text-slate-400 text-muted-foreground">
                              -
                            </div>
                          )}
                        </TableCell>
                        <TableCell>
                          <div className="text-xs text-muted-foreground font-mono mb-1">
                            IP: {report.ip || '-'}
                          </div>
                          <div
                            className="text-xs text-slate-400 text-muted-foreground max-w-[150px] truncate"
                            title={report.device || '-'}
                          >
                            {report.device || '-'}
                          </div>
                        </TableCell>
                        {user?.role !== 'USER' && (
                          <TableCell className="text-right">
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => report?.id && handleOpenOverride(report)}
                              className="text-muted-foreground hover:text-brand hover:bg-indigo-50 dark:text-slate-400 dark:hover:bg-indigo-900/30"
                              title="Override Status"
                              aria-label={`Override status kehadiran ${report.user_name}`}
                            >
                              <Edit3 className="size-4" />
                            </Button>
                          </TableCell>
                        )}
                      </TableRow>
                    ))
                )}
              </TableBody>
            </Table>
          </div>

          {meta ? <TablePagination meta={meta} onPageChange={setPage} itemLabel="laporan" /> : null}
        </div>
      )}

      {/* Override Modal */}
      <Dialog
        open={Boolean(isOverrideModalOpen && selectedReport)}
        onOpenChange={setIsOverrideModalOpen}
      >
        <DialogContent className="max-w-md p-0">
          <div className="border-b border-border px-6 py-4 border-border">
            <DialogHeader>
              <DialogTitle className="text-xl font-bold text-foreground">
                Ubah Status Manual
              </DialogTitle>
              <DialogDescription className="sr-only">Override status kehadiran</DialogDescription>
            </DialogHeader>
          </div>

          <form onSubmit={handleOverrideSubmit} className="p-6">
            {selectedReport && (
              <div className="mb-4 space-y-1 rounded-lg bg-muted/50 p-3 text-sm text-foreground">
                <p>
                  <strong>Nama:</strong> {selectedReport.user_name}
                </p>
                <p>
                  <strong>Sesi:</strong> {selectedReport.session_title}
                </p>
                <p>
                  <strong>Waktu:</strong>{' '}
                  {safeFormat(selectedReport.check_in_time, 'dd MMM yyyy HH:mm:ss')}
                </p>
              </div>
            )}

            <div className="space-y-4">
              <div className="space-y-2">
                <Label>Status Baru</Label>
                <Select value={overrideStatus} onValueChange={setOverrideStatus}>
                  <SelectTrigger className="w-full">
                    <SelectValue placeholder="Pilih Status" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="PRESENT">Hadir (PRESENT)</SelectItem>
                    <SelectItem value="LATE">Terlambat (LATE)</SelectItem>
                    <SelectItem value="SICK">Sakit (SICK)</SelectItem>
                    <SelectItem value="EXCUSED">Izin (EXCUSED)</SelectItem>
                    <SelectItem value="ABSENT">Alfa (ABSENT)</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Catatan / Alasan (Opsional)</Label>
                <Textarea
                  rows={3}
                  value={overrideNotes}
                  onChange={(e) => setOverrideNotes(e.target.value)}
                  placeholder="Contoh: Dispensasi alat rusak"
                />
              </div>
            </div>

            <DialogFooter className="mt-8">
              <Button
                type="button"
                variant="outline"
                onClick={() => setIsOverrideModalOpen(false)}
                disabled={overrideSubmitting}
              >
                Batal
              </Button>
              <Button
                type="button"
                disabled={overrideSubmitting}
                onClick={() => setIsOverrideConfirmOpen(true)}
              >
                {overrideSubmitting ? (
                  <>
                    <Loader2 className="mr-2 size-4 animate-spin" aria-hidden="true" />
                    MenyimpanΓÇª
                  </>
                ) : (
                  'Simpan Status'
                )}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <ConfirmModal
        isOpen={isOverrideConfirmOpen}
        onClose={() => setIsOverrideConfirmOpen(false)}
        onConfirm={() => {
          void handleOverrideSubmit({ preventDefault: () => {} } as React.FormEvent);
        }}
        title="Ubah status kehadiran?"
        description={
          selectedReport
            ? `Status ${selectedReport.user_name} pada sesi "${selectedReport.session_title}" akan diubah menjadi ${attendanceStatusLabel(overrideStatus)}.`
            : 'Status kehadiran akan diubah secara manual.'
        }
        confirmText="Ya, Ubah Status"
        variant="warning"
      />
    </AdminPageShell>
  );
}

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '@/services/api';
import useSWR from 'swr';
import { useAuthStore } from '@/stores/authStore';
import { Plus, Search, Edit2, Trash2, X, QrCode, MapPin, Clock, Calendar } from 'lucide-react';
import { format } from 'date-fns';
import { id } from 'date-fns/locale';
import { toast } from 'sonner';
import { toastErrorMessage } from '@/lib/utils/toastMessage';
import { sessionStatusLabel } from '@/lib/utils/statusLabel';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { ConfirmModal } from '@/components/ConfirmModal';
import ActionLoadingOverlay from '@/components/ActionLoadingOverlay';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Skeleton } from '@/components/ui/skeleton';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import AdminPageShell from '@/components/AdminPageShell';
import { AdminEmptyState } from '@/components/admin/AdminEmptyState';
import { CardSkeletonList } from '@/components/admin/CardSkeleton';
import { AdminContentTransition } from '@/components/admin/AdminContentTransition';

import type { Location, Session } from '@/types/session';
import { formatClassLabel, sessionClassNames } from '@/lib/utils/classLabel';
import { WizardStepIndicator } from '@/components/ui/WizardStepIndicator';
import { useSwrPageState } from '@/hooks/useSwrPageState';
import { useClientPagination } from '@/hooks/useClientPagination';
import { ErrorWithRetry } from '@/components/ErrorWithRetry';
import { TablePagination } from '@/components/ui/TablePagination';
import { applyApiFieldErrors, firstFieldErrorMessage } from '@/lib/http/apiFieldErrors';

const WIZARD_LABELS = ['Info & Lokasi', 'Jadwal', 'Aturan Absen', 'Kelas'] as const;
const WIZARD_HINTS = [
  'Nama sesi, lokasi geofencing, dan cara validasi absensi (QR atau GPS saja).',
  'Waktu mulaiΓÇôselesai sesi serta kapan mahasiswa boleh membuka check-in.',
  'Batas menit dianggap terlambat dan apakah wajib check-out setelah hadir.',
  'Kelas yang diundang; kosongkan pilihan kelas jika sesi untuk semua mahasiswa.',
] as const;

type FormFieldKey =
  | 'title'
  | 'description'
  | 'location_id'
  | 'qr_mode'
  | 'session_start'
  | 'session_end'
  | 'check_in_open_at'
  | 'check_in_close_at'
  | 'late_threshold_minutes'
  | 'status'
  | 'class_ids';

type FormFieldErrors = Partial<Record<FormFieldKey, string>>;

function qrModeLabel(mode: string): string {
  if (mode === 'NONE') return 'Tanpa QR (GPS saja)';
  if (mode === 'DYNAMIC') return 'QR Dinamis';
  if (mode === 'STATIC') return 'QR Statis';
  return mode;
}

function sessionStatusBadgeVariant(status: string): 'success' | 'outline' | 'secondary' {
  if (status === 'ACTIVE') return 'success';
  if (status === 'UPCOMING') return 'outline';
  return 'secondary';
}

export default function Sessions() {
  const navigate = useNavigate();
  const { user: currentUser } = useAuthStore();
  const [wizardStep, setWizardStep] = useState(1);
  const [locations, setLocations] = useState<Location[]>([]);
  const [classes, setClasses] = useState<{ id: string; name: string; semester: number }[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterDate, setFilterDate] = useState('');
  const [filterLocation, setFilterLocation] = useState('ALL');
  const [filterClass, setFilterClass] = useState('ALL');
  const [classSearch, setClassSearch] = useState('');

  // Modal state
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSession, setEditingSession] = useState<Session | null>(null);

  // Form state
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    location_id: '',
    class_ids: [] as string[],
    qr_mode: 'NONE',
    session_start: '',
    session_end: '',
    check_in_open_at: '',
    check_in_close_at: '',
    late_threshold_minutes: 15,
    require_checkout: false,
    status: 'UPCOMING',
  });
  const [saving, setSaving] = useState(false);
  const [formErrors, setFormErrors] = useState<FormFieldErrors>({});

  // Delete Session Confirmation Modal
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [sessionToDelete, setSessionToDelete] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [isSaveConfirmOpen, setIsSaveConfirmOpen] = useState(false);

  // Nilai minimum untuk input datetime-local (waktu sekarang dalam zona lokal)
  // Sengaja hitung sekali per render ΓÇö memo tidak perlu karena cheap & tidak harus update tiap detik.
  const nowLocalMin = (() => {
    const d = new Date();
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 16);
  })();

  const fetcher = (url: string) => api.get(url).then((res) => res.data.data);
  const swr = useSWR<Session[]>('/sessions', fetcher, { revalidateOnFocus: false });
  const { data: sessions = [], isPending, isError, retry, mutate } = useSwrPageState(swr);

  const hasFilters =
    Boolean(searchTerm.trim()) ||
    Boolean(filterDate) ||
    filterLocation !== 'ALL' ||
    filterClass !== 'ALL';

  const canProceedWizard = (step: number) => {
    if (step === 1) return Boolean(formData.title.trim() && formData.location_id);
    if (step === 2) return Boolean(formData.session_start && formData.session_end);
    if (step === 3) return Boolean(formData.check_in_open_at && formData.check_in_close_at);
    return true;
  };

  const fetchLocations = async () => {
    try {
      const [locationsRes, classesRes] = await Promise.all([
        api.get('/locations'),
        api.get('/classes'),
      ]);
      setLocations(locationsRes.data.data);
      setClasses(classesRes.data.data);
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    if (currentUser?.role !== 'USER') {
      fetchLocations();
    }
  }, [currentUser]);

  // Format UTC date string to local datetime-local string
  const formatForDateTimeLocal = (dateString: string) => {
    const d = new Date(dateString);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 16);
  };

  const handleOpenModal = (session: any = null) => {
    if (session) {
      setEditingSession(session);
      const linkedIds = Array.isArray(session.session_classes)
        ? session.session_classes.flatMap((x: any) => {
            const result = x?.class?.id;
            return result ? [result] : [];
          })
        : [];
      const classIds = linkedIds.length ? linkedIds : session.class_id ? [session.class_id] : [];
      setFormData({
        title: session.title,
        description: session.description || '',
        class_ids: classIds,
        location_id: session.location_id,
        qr_mode: session.qr_mode,
        session_start: formatForDateTimeLocal(session.session_start),
        session_end: formatForDateTimeLocal(session.session_end),
        check_in_open_at: formatForDateTimeLocal(session.check_in_open_at),
        check_in_close_at: formatForDateTimeLocal(session.check_in_close_at),
        late_threshold_minutes: session.late_threshold_minutes,
        require_checkout: session.require_checkout,
        status: session.status,
      });
    } else {
      setEditingSession(null);

      // Default to today + 1 hour
      const now = new Date();
      now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
      const nowStr = now.toISOString().slice(0, 16);

      const later = new Date(now.getTime() + 2 * 60 * 60 * 1000); // +2 hours
      const laterStr = later.toISOString().slice(0, 16);

      setFormData({
        title: '',
        description: '',
        location_id: locations.length > 0 ? locations[0].id : '',
        class_ids: [] as string[],
        qr_mode: 'NONE',
        session_start: nowStr,
        session_end: laterStr,
        check_in_open_at: nowStr,
        check_in_close_at: laterStr,
        late_threshold_minutes: 15,
        require_checkout: false,
        status: 'UPCOMING',
      });
    }
    setWizardStep(1);
    setFormErrors({});
    setIsModalOpen(true);
  };

  const onWizardFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (wizardStep < 4 && canProceedWizard(wizardStep)) {
      setWizardStep((s) => Math.min(4, s + 1));
    }
  };

  const validateSessionForm = (): Record<string, string> => {
    const openAtMs = new Date(formData.check_in_open_at).getTime();
    const closeAtMs = new Date(formData.check_in_close_at).getTime();
    const sessionStartMs = new Date(formData.session_start).getTime();
    const sessionEndMs = new Date(formData.session_end).getTime();
    const nowMs = Date.now();
    const isEditOngoing = Boolean(editingSession) && editingSession?.status !== 'UPCOMING';

    const errors: Record<string, string> = {};
    if (!formData.title.trim()) {
      errors.title = 'Judul sesi wajib diisi.';
    }
    if (!formData.location_id) {
      errors.location_id = 'Pilih lokasi sesi.';
    }
    if (Number.isNaN(closeAtMs) || Number.isNaN(openAtMs)) {
      errors.check_in_close_at = 'Format waktu tidak valid.';
    } else {
      if (!isEditOngoing && closeAtMs <= nowMs + 60_000) {
        errors.check_in_close_at = 'Tutup absen harus minimal 1 menit ke depan dari sekarang.';
      }
      if (closeAtMs <= openAtMs) {
        errors.check_in_close_at = 'Tutup absen harus setelah Buka absen.';
      }
      if (!Number.isNaN(sessionEndMs) && sessionEndMs < sessionStartMs) {
        errors.session_end = 'Berakhir sesi tidak boleh sebelum mulai sesi.';
      }
    }
    return errors;
  };

  const focusWizardStepForErrors = (errors: Record<string, string>) => {
    if (errors.title || errors.location_id || errors.qr_mode) {
      setWizardStep(1);
    } else if (errors.session_start || errors.session_end) {
      setWizardStep(2);
    } else if (
      errors.check_in_open_at ||
      errors.check_in_close_at ||
      errors.late_threshold_minutes
    ) {
      setWizardStep(3);
    }
  };

  const buildSessionPayload = () => {
    const base = {
      title: formData.title.trim(),
      description: formData.description || undefined,
      location_id: formData.location_id,
      qr_mode: formData.qr_mode,
      session_start: new Date(formData.session_start).toISOString(),
      session_end: new Date(formData.session_end).toISOString(),
      check_in_open_at: new Date(formData.check_in_open_at).toISOString(),
      check_in_close_at: new Date(formData.check_in_close_at).toISOString(),
      late_threshold_minutes: Number(formData.late_threshold_minutes),
      require_checkout: formData.require_checkout,
      class_ids: formData.class_ids,
    };
    if (editingSession) {
      return { ...base, status: formData.status };
    }
    return base;
  };

  const openSaveConfirm = () => {
    const errors = validateSessionForm();
    if (Object.keys(errors).length > 0) {
      setFormErrors(errors);
      focusWizardStepForErrors(errors);
      toast.error(Object.values(errors)[0]);
      return;
    }
    setIsSaveConfirmOpen(true);
  };

  const saveSession = async () => {
    if (saving) return;
    setSaving(true);
    setFormErrors({});

    try {
      const errors = validateSessionForm();
      if (Object.keys(errors).length > 0) {
        setFormErrors(errors);
        focusWizardStepForErrors(errors);
        toast.error(Object.values(errors)[0]);
        setIsSaveConfirmOpen(false);
        return;
      }

      const payload = buildSessionPayload();

      if (editingSession) {
        const res = await api.put(`/sessions/${editingSession.id}`, payload);
        if (res.data?.success === false) {
          throw new Error(res.data?.message || res.data?.error || 'Gagal memperbarui sesi');
        }
        toast.success('Sesi berhasil diperbarui');
      } else {
        const res = await api.post('/sessions', payload);
        if (res.data?.success === false) {
          throw new Error(res.data?.message || res.data?.error || 'Gagal membuat sesi');
        }
        toast.success('Sesi berhasil dibuat');
      }
      setIsSaveConfirmOpen(false);
      setIsModalOpen(false);
      await mutate();
    } catch (error: unknown) {
      const fieldErrors = applyApiFieldErrors(error, setFormErrors);
      if (fieldErrors) {
        focusWizardStepForErrors(fieldErrors);
        toast.error(
          firstFieldErrorMessage(fieldErrors) ?? toastErrorMessage(error, 'Gagal menyimpan sesi')
        );
      } else {
        toast.error(toastErrorMessage(error, 'Gagal menyimpan sesi'));
      }
    } finally {
      setSaving(false);
    }
  };

  const fieldError = (key: FormFieldKey) =>
    formErrors[key] ? <p className="text-sm text-destructive">{formErrors[key]}</p> : null;

  const clearFieldError = (key: FormFieldKey) => {
    if (!formErrors[key]) return;
    setFormErrors((prev) => {
      const next = { ...prev };
      delete next[key];
      return next;
    });
  };

  const openDeleteConfirm = (id: string) => {
    setSessionToDelete(id);
    setIsDeleteModalOpen(true);
  };

  const confirmDeleteSession = async () => {
    if (!sessionToDelete || deleting) return;
    setDeleting(true);
    try {
      await api.delete(`/sessions/${sessionToDelete}`);
      toast.success('Sesi berhasil dihapus');
      setIsDeleteModalOpen(false);
      setSessionToDelete(null);
      mutate();
    } catch (error) {
      toast.error(toastErrorMessage(error, 'Gagal menghapus sesi'));
    } finally {
      setDeleting(false);
    }
  };

  const filteredSessions = sessions.filter((s) => {
    const matchSearch = s.title.toLowerCase().includes(searchTerm.toLowerCase());
    const matchLocation = filterLocation === 'ALL' || s.location?.id === filterLocation;
    const linkedIds = (s.session_classes ?? []).flatMap((x) => {
      const result = x?.class?.id;
      return result ? [result] : [];
    }) as string[];
    const legacyClassId = s.class_id ?? null;
    const isAllStudents = !legacyClassId && linkedIds.length === 0;
    const matchClass =
      filterClass === 'ALL' ||
      (filterClass === 'ALL_STUDENTS'
        ? isAllStudents
        : legacyClassId === filterClass || linkedIds.includes(filterClass));

    let matchDate = true;
    if (filterDate) {
      const sDate = new Date(s.session_start).toISOString().split('T')[0];
      matchDate = sDate === filterDate;
    }

    return matchSearch && matchLocation && matchClass && matchDate;
  });

  const {
    paginatedItems: paginatedSessions,
    meta: sessionsPaginationMeta,
    setPage: setSessionsPage,
  } = useClientPagination(filteredSessions, {
    pageSize: 20,
    resetDeps: [searchTerm, filterDate, filterLocation, filterClass],
  });

  const actionOverlayLabel = saving
    ? editingSession
      ? 'Menyimpan perubahan sesiΓÇª'
      : 'Membuat sesiΓÇª'
    : deleting
      ? 'Menghapus sesiΓÇª'
      : null;

  return (
    <>
      <ActionLoadingOverlay show={!!actionOverlayLabel} label={actionOverlayLabel ?? ''} />
      <AdminPageShell
        title="Sesi Kehadiran"
        description="Kelola sesi, jadwal, lokasi, dan QR."
        variant="plain"
        icon={<Calendar className="size-5" />}
        actions={
          currentUser?.role !== 'USER' ? (
            <Button onClick={() => handleOpenModal()}>
              <Plus className="size-4 mr-2" />
              Buat Sesi Baru
            </Button>
          ) : null
        }
      >
        {isError ? (
          <ErrorWithRetry
            title="Gagal memuat sesi"
            error={swr.error}
            onRetry={retry}
            className="mb-6"
          />
        ) : (
          <div className="mb-6 overflow-hidden rounded-xl border border-border bg-card shadow-card dark:shadow-none dark:ring-1 dark:ring-white/10">
            <div className="grid grid-cols-1 gap-5 border-b border-border p-5 sm:grid-cols-2 lg:grid-cols-4">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 size-4" />
                <Input
                  type="text"
                  placeholder="Cari kegiatan/mata kuliah..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-9 w-full"
                />
              </div>
              <div className="relative w-full">
                <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 size-4 z-10 pointer-events-none" />
                <Input
                  type="date"
                  value={filterDate}
                  onChange={(e) => setFilterDate(e.target.value)}
                  className="w-full pl-9 block appearance-none [&::-webkit-calendar-picker-indicator]:absolute [&::-webkit-calendar-picker-indicator]:inset-0 [&::-webkit-calendar-picker-indicator]:w-full [&::-webkit-calendar-picker-indicator]:h-full [&::-webkit-calendar-picker-indicator]:opacity-0 [&::-webkit-calendar-picker-indicator]:cursor-pointer bg-transparent"
                />
              </div>
              <div className="w-full">
                <Select value={filterLocation} onValueChange={setFilterLocation}>
                  <SelectTrigger className="w-full">
                    <SelectValue placeholder="Semua Lokasi" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="ALL">Semua Lokasi</SelectItem>
                    {locations.map((loc) => (
                      <SelectItem key={loc.id} value={loc.id}>
                        {loc.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="w-full">
                <Select value={filterClass} onValueChange={setFilterClass}>
                  <SelectTrigger className="w-full">
                    <SelectValue placeholder="Semua Kelas" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="ALL">Semua Kelas</SelectItem>
                    <SelectItem value="ALL_STUDENTS">Semua Mahasiswa (Umum)</SelectItem>
                    {classes.map((c) => (
                      <SelectItem key={c.id} value={c.id}>
                        {formatClassLabel(c)}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <ul className="space-y-3 p-5 md:hidden" aria-label="Daftar sesi">
              {isPending ? (
                <li>
                  <CardSkeletonList count={3} />
                </li>
              ) : filteredSessions.length === 0 ? (
                <li>
                  <AdminEmptyState
                    compact
                    icon={Calendar}
                    hasFilters={hasFilters}
                    title={hasFilters ? 'Tidak ada hasil' : 'Belum ada sesi'}
                    description={
                      hasFilters
                        ? 'Ubah filter pencarian, tanggal, lokasi, atau kelas.'
                        : 'Buat sesi kehadiran untuk memulai absensi.'
                    }
                  />
                </li>
              ) : (
                paginatedSessions.map((session) => {
                  const attendances = (
                    session as Session & {
                      attendances?: { id: string; check_out_time: string | null }[];
                    }
                  ).attendances;
                  return (
                    <li
                      key={session.id}
                      className="rounded-2xl border border-border bg-background/60 p-4 dark:bg-muted/10"
                    >
                      <div className="space-y-2">
                        <div className="flex flex-wrap items-start justify-between gap-2">
                          <p className="text-base font-bold leading-snug text-foreground">
                            {session.title}
                          </p>
                          <Badge
                            variant={sessionStatusBadgeVariant(session.status)}
                            className="justify-center text-center whitespace-normal"
                          >
                            {sessionStatusLabel(session.status)}
                          </Badge>
                        </div>
                        <p className="text-sm text-muted-foreground">{session.location?.name}</p>
                        <p className="text-sm text-muted-foreground">
                          {format(new Date(session.session_start), 'dd MMM yyyy ┬╖ HH:mm', {
                            locale: id,
                          })}{' '}
                          ΓÇô {format(new Date(session.session_end), 'HH:mm')} WIB
                        </p>
                        <p className="text-sm text-muted-foreground">
                          {sessionClassNames(session)}
                        </p>
                        <p className="text-xs text-muted-foreground">
                          {qrModeLabel(session.qr_mode)}
                        </p>
                        <p className="text-xs text-muted-foreground">
                          Dibuat oleh: {session.creator?.name}
                        </p>
                      </div>
                      <div className="mt-5 flex flex-wrap gap-3">
                        {session.qr_mode !== 'NONE' && session.status !== 'CLOSED' && (
                          <Button
                            variant="outline"
                            size="sm"
                            className="min-h-11"
                            onClick={() => window.open(`/sessions/${session.id}/qr`, '_blank')}
                            aria-label={`Tampilkan QR untuk ${session.title}`}
                          >
                            QR
                          </Button>
                        )}
                        {(currentUser?.role === 'SUPER_ADMIN' || currentUser?.role === 'ADMIN') && (
                          <>
                            <Button
                              variant="outline"
                              size="sm"
                              className="min-h-11"
                              onClick={() => handleOpenModal(session)}
                              aria-label={`Edit sesi ${session.title}`}
                            >
                              Edit
                            </Button>
                            <Button
                              variant="destructive"
                              size="sm"
                              className="min-h-11"
                              onClick={() => openDeleteConfirm(session.id)}
                              aria-label={`Hapus sesi ${session.title}`}
                            >
                              Hapus
                            </Button>
                          </>
                        )}
                        {currentUser?.role === 'USER' && session.status === 'ACTIVE' && (
                          <>
                            {attendances && attendances.length > 0 ? (
                              attendances[0].check_out_time || !session.require_checkout ? (
                                <Badge variant="success" className="min-h-11 px-3 py-2">
                                  Sudah Absen
                                </Badge>
                              ) : (
                                <Button
                                  className="min-h-11 flex-1 bg-amber-500 hover:bg-amber-600"
                                  onClick={() =>
                                    navigate(
                                      `/attend?session=${session.id}&checkout=true&attendance=${attendances[0].id}`
                                    )
                                  }
                                >
                                  Check-out
                                </Button>
                              )
                            ) : (
                              <Button
                                className="min-h-11 flex-1"
                                onClick={() => navigate(`/attend?session=${session.id}`)}
                              >
                                Hadir
                              </Button>
                            )}
                          </>
                        )}
                      </div>
                    </li>
                  );
                })
              )}
            </ul>

            <div className="hidden overflow-x-auto md:block">
              <Table>
                <TableHeader className="sticky top-0 z-10 bg-muted/50 [&_tr]:border-b">
                  <TableRow>
                    <TableHead>Informasi Kelas/Event</TableHead>
                    <TableHead>Jadwal Sesi</TableHead>
                    <TableHead>Kelas</TableHead>
                    <TableHead>Mode QR & Lokasi</TableHead>
                    <TableHead className="text-center">Status</TableHead>
                    <TableHead className="text-right">Aksi</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {isPending ? (
                    Array.from({ length: 5 }).map((_, idx) => (
                      <TableRow key={idx}>
                        <TableCell>
                          <Skeleton className="h-5 w-40 mb-2" />
                          <Skeleton className="h-4 w-32" />
                        </TableCell>
                        <TableCell>
                          <Skeleton className="h-4 w-48 mb-2" />
                          <Skeleton className="h-4 w-32" />
                        </TableCell>
                        <TableCell>
                          <Skeleton className="h-6 w-24 rounded-full" />
                        </TableCell>
                        <TableCell>
                          <Skeleton className="h-5 w-32 mb-2" />
                          <Skeleton className="h-4 w-40" />
                        </TableCell>
                        <TableCell className="text-center">
                          <Skeleton className="mx-auto h-5 w-24" />
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex justify-end gap-2">
                            <Skeleton className="size-8 rounded-md" />
                            <Skeleton className="size-8 rounded-md" />
                          </div>
                        </TableCell>
                      </TableRow>
                    ))
                  ) : filteredSessions.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={6} className="p-0">
                        <AdminEmptyState
                          compact
                          icon={Calendar}
                          hasFilters={hasFilters}
                          title={hasFilters ? 'Tidak ada hasil' : 'Belum ada sesi'}
                          description={
                            hasFilters
                              ? 'Ubah filter pencarian, tanggal, lokasi, atau kelas.'
                              : 'Buat sesi kehadiran untuk memulai absensi.'
                          }
                          className="border-0 shadow-none"
                        />
                      </TableCell>
                    </TableRow>
                  ) : (
                    paginatedSessions.map((session) => (
                      <TableRow key={session.id}>
                        <TableCell>
                          <div className="font-bold text-foreground text-base">{session.title}</div>
                          <div className="text-sm text-muted-foreground flex items-center gap-1 mt-1">
                            <MapPin size={14} className="text-indigo-500" />
                            {session.location?.name}
                          </div>
                          <div className="text-xs text-slate-400 text-muted-foreground mt-1">
                            Dibuat oleh: {session.creator?.name}
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-1.5 text-muted-foreground mb-1">
                            <Clock size={14} className="text-indigo-500" />
                            <span className="font-medium">
                              {format(new Date(session.session_start), 'dd MMM yyyy', {
                                locale: id,
                              })}
                            </span>
                          </div>
                          <div className="text-xs text-muted-foreground">
                            {format(new Date(session.session_start), 'HH:mm')} -{' '}
                            {format(new Date(session.session_end), 'HH:mm')} WIB
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="font-medium text-muted-foreground">
                            {sessionClassNames(session)}
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="flex flex-col gap-2">
                            <div className="flex items-center gap-1.5 text-muted-foreground">
                              <MapPin size={14} className="text-emerald-500 shrink-0" />
                              <span className="font-medium text-sm line-clamp-1">
                                {session.location?.name || 'Lokasi tidak diketahui'}
                              </span>
                            </div>
                            <div className="text-xs text-muted-foreground flex items-center gap-1.5">
                              <QrCode size={14} className="text-slate-400" />
                              <span className="font-medium">{qrModeLabel(session.qr_mode)}</span>
                            </div>
                          </div>
                        </TableCell>
                        <TableCell className="text-center">
                          <Badge
                            variant={sessionStatusBadgeVariant(session.status)}
                            className="justify-center text-center whitespace-normal"
                          >
                            {sessionStatusLabel(session.status)}
                          </Badge>
                        </TableCell>
                        {(currentUser?.role === 'SUPER_ADMIN' || currentUser?.role === 'ADMIN') && (
                          <TableCell className="text-right">
                            <div className="flex justify-end gap-2">
                              {session.qr_mode !== 'NONE' && session.status !== 'CLOSED' && (
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  onClick={() =>
                                    window.open(`/sessions/${session.id}/qr`, '_blank')
                                  }
                                  className="text-brand hover:text-indigo-700 hover:bg-indigo-50 text-brand dark:hover:bg-indigo-900/50"
                                  aria-label={`Tampilkan QR untuk ${session.title}`}
                                >
                                  <QrCode className="size-4" />
                                </Button>
                              )}
                              <Button
                                variant="ghost"
                                size="icon"
                                onClick={() => handleOpenModal(session)}
                                className="text-muted-foreground hover:text-brand hover:bg-indigo-50 dark:text-slate-400 dark:hover:bg-indigo-900/30"
                                aria-label={`Edit sesi ${session.title}`}
                              >
                                <Edit2 className="size-4" />
                              </Button>
                              <Button
                                variant="ghost"
                                size="icon"
                                onClick={() => openDeleteConfirm(session.id)}
                                className="text-muted-foreground hover:text-red-600 hover:bg-red-50 dark:text-slate-400 dark:hover:bg-red-900/30"
                                aria-label={`Hapus sesi ${session.title}`}
                              >
                                <Trash2 className="size-4" />
                              </Button>
                            </div>
                          </TableCell>
                        )}
                        {currentUser?.role === 'USER' && (
                          <TableCell className="text-right">
                            {session.status === 'ACTIVE' && (
                              <div className="flex gap-2 justify-end">
                                {(session as any).attendances &&
                                (session as any).attendances.length > 0 ? (
                                  (session as any).attendances[0].check_out_time ||
                                  !session.require_checkout ? (
                                    <Badge variant="success">Sudah Absen</Badge>
                                  ) : (
                                    <Button
                                      onClick={() =>
                                        navigate(
                                          `/attend?session=${session.id}&checkout=true&attendance=${(session as any).attendances[0].id}`
                                        )
                                      }
                                      className="shadow-lg shadow-amber-600/20 bg-amber-500 hover:bg-amber-600 text-white text-xs px-3 py-1.5 h-auto"
                                    >
                                      Check-out
                                    </Button>
                                  )
                                ) : (
                                  <Button
                                    onClick={() => navigate(`/attend?session=${session.id}`)}
                                    className="min-h-11 shadow-sm"
                                  >
                                    Hadir
                                  </Button>
                                )}
                              </div>
                            )}
                          </TableCell>
                        )}
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </div>
            <TablePagination
              meta={sessionsPaginationMeta}
              onPageChange={setSessionsPage}
              itemLabel="sesi"
            />
          </div>
        )}

        <Dialog
          open={Boolean(isModalOpen && currentUser?.role !== 'USER')}
          onOpenChange={setIsModalOpen}
        >
          <DialogContent className="max-w-4xl p-0">
            <div className="border-b border-border px-6 py-4 border-border">
              <DialogHeader>
                <DialogTitle className="text-xl font-bold text-foreground">
                  {editingSession ? 'Edit Sesi Kehadiran' : 'Buat Sesi Baru'}
                </DialogTitle>
                <DialogDescription className="sr-only">Form sesi kehadiran</DialogDescription>
              </DialogHeader>
            </div>

            <form
              onSubmit={onWizardFormSubmit}
              className="max-h-[75vh] space-y-6 overflow-y-auto p-6"
            >
              <WizardStepIndicator
                labels={WIZARD_LABELS}
                hints={WIZARD_HINTS}
                currentStep={wizardStep}
              />

              <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                <AdminContentTransition contentKey={String(wizardStep)} className="md:col-span-2">
                  {wizardStep === 1 ? (
                    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                      <div className="space-y-2">
                        <Label>
                          Judul / Mata Kuliah <span className="text-red-500">*</span>
                        </Label>
                        <Input
                          type="text"
                          required
                          value={formData.title}
                          onChange={(e) => {
                            clearFieldError('title');
                            setFormData({ ...formData, title: e.target.value });
                          }}
                          placeholder="Pemrograman Web Lanjut (A)"
                          aria-invalid={Boolean(formErrors.title)}
                        />
                        {fieldError('title')}
                      </div>
                      <div className="space-y-2">
                        <Label>
                          Lokasi Ruangan <span className="text-red-500">*</span>
                        </Label>
                        <Select
                          required
                          value={formData.location_id}
                          onValueChange={(value) => {
                            clearFieldError('location_id');
                            setFormData({ ...formData, location_id: value });
                          }}
                        >
                          <SelectTrigger className="w-full">
                            <SelectValue placeholder="Pilih Lokasi Geofencing..." />
                          </SelectTrigger>
                          <SelectContent>
                            {locations.map((loc) => (
                              <SelectItem key={loc.id} value={loc.id}>
                                {loc.name}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                        {fieldError('location_id')}
                      </div>
                      <div className="space-y-2">
                        <Label>Deskripsi</Label>
                        <Textarea
                          rows={3}
                          value={formData.description}
                          onChange={(e) => {
                            clearFieldError('description');
                            setFormData({ ...formData, description: e.target.value });
                          }}
                          aria-invalid={Boolean(formErrors.description)}
                        />
                        {fieldError('description')}
                      </div>
                      <div className="space-y-2">
                        <Label>
                          Metode Validasi QR <span className="text-red-500">*</span>
                        </Label>
                        <Select
                          required
                          value={formData.qr_mode}
                          onValueChange={(value: string) => {
                            clearFieldError('qr_mode');
                            setFormData({ ...formData, qr_mode: value });
                          }}
                        >
                          <SelectTrigger className="w-full">
                            <SelectValue placeholder="Pilih Metode Validasi QR" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="DYNAMIC">
                              QR Dinamis (ganti tiap 15 detik)
                            </SelectItem>
                            <SelectItem value="STATIC">QR Statis</SelectItem>
                            <SelectItem value="NONE">Tanpa QR (GPS saja)</SelectItem>
                          </SelectContent>
                        </Select>
                        {fieldError('qr_mode')}
                      </div>
                    </div>
                  ) : wizardStep === 2 ? (
                    <div className="space-y-4">
                      <div className="flex flex-col gap-4 sm:flex-row sm:items-end">
                        <div className="min-w-0 flex-1 space-y-2">
                          <Label>
                            Waktu Mulai Sesi <span className="text-red-500">*</span>
                          </Label>
                          <Input
                            type="datetime-local"
                            required
                            value={formData.session_start}
                            onChange={(e) => {
                              clearFieldError('session_start');
                              setFormData({ ...formData, session_start: e.target.value });
                            }}
                            aria-invalid={Boolean(formErrors.session_start)}
                          />
                          {fieldError('session_start')}
                        </div>
                        <span
                          className="hidden shrink-0 px-1 pb-2 text-muted-foreground sm:inline"
                          aria-hidden="true"
                        >
                          ΓÇô
                        </span>
                        <div className="min-w-0 flex-1 space-y-2">
                          <Label>
                            Waktu Selesai Sesi <span className="text-red-500">*</span>
                          </Label>
                          <Input
                            type="datetime-local"
                            required
                            value={formData.session_end}
                            onChange={(e) => {
                              clearFieldError('session_end');
                              setFormData({ ...formData, session_end: e.target.value });
                            }}
                            aria-invalid={Boolean(formErrors.session_end)}
                          />
                          {fieldError('session_end')}
                        </div>
                      </div>
                      <div className="flex flex-col gap-4 sm:flex-row sm:items-end">
                        <div className="min-w-0 flex-1 space-y-2">
                          <Label>
                            Buka Check-in <span className="text-red-500">*</span>
                          </Label>
                          <Input
                            type="datetime-local"
                            required
                            min={editingSession ? undefined : nowLocalMin}
                            value={formData.check_in_open_at}
                            onChange={(e) => {
                              clearFieldError('check_in_open_at');
                              setFormData({ ...formData, check_in_open_at: e.target.value });
                            }}
                            aria-invalid={Boolean(formErrors.check_in_open_at)}
                          />
                          {fieldError('check_in_open_at')}
                        </div>
                        <span
                          className="hidden shrink-0 px-1 pb-2 text-muted-foreground sm:inline"
                          aria-hidden="true"
                        >
                          ΓÇô
                        </span>
                        <div className="min-w-0 flex-1 space-y-2">
                          <Label>
                            Tutup Check-in <span className="text-red-500">*</span>
                          </Label>
                          <Input
                            type="datetime-local"
                            required
                            min={editingSession ? undefined : nowLocalMin}
                            value={formData.check_in_close_at}
                            onChange={(e) => {
                              clearFieldError('check_in_close_at');
                              setFormData({ ...formData, check_in_close_at: e.target.value });
                            }}
                            aria-invalid={Boolean(formErrors.check_in_close_at)}
                          />
                          {fieldError('check_in_close_at')}
                        </div>
                      </div>
                    </div>
                  ) : wizardStep === 3 ? (
                    <div className="space-y-4">
                      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                        <div className="space-y-2">
                          <Label>
                            Toleransi Terlambat (Menit) <span className="text-red-500">*</span>
                          </Label>
                          <Input
                            type="number"
                            min="0"
                            required
                            value={formData.late_threshold_minutes}
                            onChange={(e) => {
                              clearFieldError('late_threshold_minutes');
                              setFormData({
                                ...formData,
                                late_threshold_minutes: parseInt(e.target.value),
                              });
                            }}
                            aria-invalid={Boolean(formErrors.late_threshold_minutes)}
                          />
                          {fieldError('late_threshold_minutes')}
                        </div>
                        <div className="flex items-center gap-2 pt-8">
                          <Checkbox
                            checked={Boolean(formData.require_checkout)}
                            onCheckedChange={(checked) =>
                              setFormData((p) => ({ ...p, require_checkout: Boolean(checked) }))
                            }
                          />
                          <span className="text-sm font-medium text-muted-foreground">
                            Wajib Check-out
                          </span>
                        </div>
                      </div>
                      {editingSession && (
                        <div className="space-y-2">
                          <Label>Status Sesi (Override Manual)</Label>
                          <Select
                            value={formData.status}
                            onValueChange={(value: string) => {
                              clearFieldError('status');
                              setFormData({ ...formData, status: value });
                            }}
                          >
                            <SelectTrigger className="w-full">
                              <SelectValue placeholder="Pilih Status" />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="UPCOMING">
                                {sessionStatusLabel('UPCOMING')}
                              </SelectItem>
                              <SelectItem value="ACTIVE">{sessionStatusLabel('ACTIVE')}</SelectItem>
                              <SelectItem value="CLOSED">{sessionStatusLabel('CLOSED')}</SelectItem>
                            </SelectContent>
                          </Select>
                          {fieldError('status')}
                        </div>
                      )}
                    </div>
                  ) : (
                    <div className="space-y-4">
                      <div className="space-y-2">
                        <Label>Target Kelas</Label>
                        <div className="relative">
                          <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-400" />
                          <Input
                            value={classSearch}
                            onChange={(e) => setClassSearch(e.target.value)}
                            onKeyDown={(e) => {
                              if (e.key === 'Enter') e.preventDefault();
                            }}
                            placeholder="Cari kelas..."
                            className="pl-9"
                          />
                        </div>

                        <div className="scrollbar-hide max-h-56 overflow-y-auto rounded-xl border border-border bg-card p-2">
                          <div className="space-y-1.5">
                            <Button
                              type="button"
                              variant="ghost"
                              className={[
                                'h-auto w-full justify-between rounded-lg px-3 py-2.5 text-left',
                                formData.class_ids.length === 0
                                  ? 'bg-emerald-50 text-emerald-900 hover:bg-emerald-50 dark:bg-emerald-950/30 dark:text-emerald-100 dark:hover:bg-emerald-950/30'
                                  : 'hover:bg-slate-50 dark:hover:bg-zinc-900',
                              ].join(' ')}
                              onClick={() => setFormData((p) => ({ ...p, class_ids: [] }))}
                            >
                              <span className="font-medium">Semua Mahasiswa (Umum)</span>
                              {formData.class_ids.length === 0 ? (
                                <span className="text-xs font-semibold">Terpilih</span>
                              ) : null}
                            </Button>
                            <div className="h-px bg-muted/70" />
                            {classes
                              .filter((c) =>
                                c.name.toLowerCase().includes(classSearch.trim().toLowerCase())
                              )
                              .map((c) => {
                                const selected = formData.class_ids.includes(c.id);
                                return (
                                  <Button
                                    key={c.id}
                                    type="button"
                                    variant="ghost"
                                    className={[
                                      'h-auto w-full justify-between rounded-lg px-3 py-2.5 text-left',
                                      selected
                                        ? 'bg-emerald-50 text-emerald-900 hover:bg-emerald-50 dark:bg-emerald-950/30 dark:text-emerald-100 dark:hover:bg-emerald-950/30'
                                        : 'hover:bg-slate-50 dark:hover:bg-zinc-900',
                                    ].join(' ')}
                                    onClick={() => {
                                      setFormData((p) => {
                                        const set = new Set(p.class_ids);
                                        if (selected) set.delete(c.id);
                                        else set.add(c.id);
                                        return { ...p, class_ids: Array.from(set) };
                                      });
                                    }}
                                  >
                                    <span className="font-medium">{formatClassLabel(c)}</span>
                                    {selected ? (
                                      <span className="text-xs font-semibold">Terpilih</span>
                                    ) : (
                                      <span className="text-xs text-muted-foreground">Tambah</span>
                                    )}
                                  </Button>
                                );
                              })}
                          </div>
                          {classes.filter((c) =>
                            c.name.toLowerCase().includes(classSearch.trim().toLowerCase())
                          ).length === 0 ? (
                            <div className="px-3 py-2 text-sm text-muted-foreground">
                              Tidak ada kelas.
                            </div>
                          ) : null}
                        </div>

                        <div className="rounded-xl border border-border bg-muted/30 p-3">
                          <div className="text-sm font-semibold text-foreground">
                            Kelas Terpilih:
                          </div>
                          <div className="mt-2 flex flex-wrap gap-2">
                            {formData.class_ids.length === 0 ? (
                              <Badge variant="secondary">Semua Mahasiswa</Badge>
                            ) : (
                              formData.class_ids
                                .flatMap((id) => {
                                  const result = classes.find((c) => c.id === id);
                                  return result ? [result] : [];
                                })
                                .map((c: any) => (
                                  <Badge key={c.id} variant="secondary" className="gap-1">
                                    <span className="max-w-[260px] truncate">
                                      {formatClassLabel(c)}
                                    </span>
                                    <Button
                                      type="button"
                                      variant="ghost"
                                      size="icon"
                                      className="ml-1 size-5"
                                      onClick={() =>
                                        setFormData((p) => ({
                                          ...p,
                                          class_ids: p.class_ids.filter((x) => x !== c.id),
                                        }))
                                      }
                                      aria-label="Hapus kelas"
                                    >
                                      <X className="size-3" />
                                    </Button>
                                  </Badge>
                                ))
                            )}
                          </div>
                        </div>

                        <div className="text-xs text-muted-foreground">
                          Kosong = semua mahasiswa.
                        </div>
                      </div>
                    </div>
                  )}
                </AdminContentTransition>
              </div>

              <DialogFooter className="mt-6 flex flex-wrap gap-3">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setIsModalOpen(false)}
                  disabled={saving}
                  className="min-h-11"
                >
                  Batal
                </Button>
                {wizardStep > 1 ? (
                  <Button
                    type="button"
                    variant="secondary"
                    className="min-h-11"
                    onClick={() => setWizardStep((s) => Math.max(1, s - 1))}
                  >
                    Sebelumnya
                  </Button>
                ) : null}
                {wizardStep < 4 ? (
                  <Button
                    type="button"
                    className="min-h-11"
                    disabled={!canProceedWizard(wizardStep)}
                    onClick={() => setWizardStep((s) => Math.min(4, s + 1))}
                  >
                    Lanjut
                  </Button>
                ) : (
                  <Button
                    type="button"
                    disabled={saving}
                    aria-busy={saving}
                    className="min-h-11"
                    onClick={openSaveConfirm}
                  >
                    {saving ? 'MenyimpanΓÇª' : editingSession ? 'Simpan Perubahan' : 'Buat Sesi'}
                  </Button>
                )}
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>

        <ConfirmModal
          isOpen={isSaveConfirmOpen}
          onClose={() => !saving && setIsSaveConfirmOpen(false)}
          onConfirm={saveSession}
          title={editingSession ? 'Simpan perubahan sesi?' : 'Buat sesi baru?'}
          description={
            editingSession
              ? `Perubahan pada "${formData.title || editingSession.title}" akan disimpan ke sistem.`
              : `Sesi "${formData.title || 'tanpa judul'}" akan dibuat. Pastikan jadwal dan kelas sudah benar.`
          }
          confirmText={editingSession ? 'Ya, Simpan' : 'Ya, Buat Sesi'}
          variant="primary"
          loading={saving}
          loadingText="MenyimpanΓÇª"
        />

        {/* Delete Session Confirmation Modal */}
        <ConfirmModal
          isOpen={isDeleteModalOpen}
          onClose={() => setIsDeleteModalOpen(false)}
          onConfirm={confirmDeleteSession}
          title="Konfirmasi Hapus Sesi"
          description="Apakah Anda yakin ingin menghapus sesi absensi ini? Seluruh data yang terkait dengan sesi ini akan ikut terhapus."
          confirmText="Ya, Hapus Sesi"
          variant="danger"
          loading={deleting}
          loadingText="MenghapusΓÇª"
        />
      </AdminPageShell>
    </>
  );
}

import React, { useState, useEffect } from 'react';
import { useAuthStore } from '@/stores/authStore';
import { useTheme } from '@/providers/theme-provider';
import { Moon, Sun } from 'lucide-react';
import api from '@/services/api';
import { toast } from 'sonner';
import { User, LogOut, Shield, Mail, Phone } from 'lucide-react';
import { userRoleLabel } from '@/lib/utils/statusLabel';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import AdminPageShell from '@/components/AdminPageShell';
import { ErrorWithRetry } from '@/components/ErrorWithRetry';
import { toastErrorMessage } from '@/lib/utils/toastMessage';
import { forgetDeviceFingerprint } from '@/lib/storage/deviceFingerprint';
import { cn } from '@/lib/utils/utils';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';

const settingsCardClass =
  'rounded-xl border border-border bg-card text-card-foreground shadow-card dark:shadow-none dark:ring-1 dark:ring-white/10';

type ProfileField =
  | 'name'
  | 'email'
  | 'phone'
  | 'current_password'
  | 'new_password'
  | 'confirm_password';
type FieldErrors = Partial<Record<ProfileField, string>>;

function parseFieldErrors(err: unknown): FieldErrors {
  const status = (err as { response?: { status?: number } })?.response?.status;
  if (status !== 422) return {};
  const raw = (err as { response?: { data?: { errors?: Record<string, string | string[]> } } })
    ?.response?.data?.errors;
  if (!raw || typeof raw !== 'object') return {};
  const out: FieldErrors = {};
  for (const [key, val] of Object.entries(raw)) {
    const msg = Array.isArray(val) ? val[0] : typeof val === 'string' ? val : undefined;
    if (msg) out[key as ProfileField] = msg;
  }
  return out;
}

export default function Settings() {
  const { user, setAuth } = useAuthStore();
  const { theme, toggleTheme } = useTheme();

  const [profileLoading, setProfileLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [profileError, setProfileError] = useState<unknown>(null);
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});
  const [activeTab, setActiveTab] = useState<'profile'>('profile');

  const [formData, setFormData] = useState({
    name: user?.name || '',
    email: user?.email || '',
    phone: '',
    current_password: '',
    new_password: '',
    confirm_password: '',
  });

  useEffect(() => {
    if (!user) return;

    const loadProfile = async () => {
      setProfileLoading(true);
      setProfileError(null);
      try {
        const res = await api.get('/settings/profile');
        const row = res.data.data;
        if (row) {
          setFormData({
            name: row.name || user.name || '',
            email: row.email || user.email || '',
            phone: row.phone || '',
            current_password: '',
            new_password: '',
            confirm_password: '',
          });
        }
      } catch (err) {
        setProfileError(err);
        setFormData((prev) => ({
          ...prev,
          name: user.name || '',
          email: user.email || '',
        }));
        toast.error(toastErrorMessage(err, 'Gagal memuat profil'));
      } finally {
        setProfileLoading(false);
      }
    };

    void loadProfile();
  }, [user]);

  const isStudent = user?.role === 'USER';

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.new_password && formData.new_password !== formData.confirm_password) {
      toast.error('Kata sandi baru tidak cocok');
      return;
    }

    setSaving(true);
    setFieldErrors({});
    try {
      const res = await api.put('/settings/profile', {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        current_password: formData.current_password,
        new_password: formData.new_password,
      });

      // Update local state
      setAuth({ ...user!, name: formData.name, email: formData.email });

      toast.success(res.data.message || 'Profil berhasil diperbarui');
      setFormData((prev) => ({
        ...prev,
        current_password: '',
        new_password: '',
        confirm_password: '',
      }));
    } catch (error: unknown) {
      const fields = parseFieldErrors(error);
      if (Object.keys(fields).length > 0) setFieldErrors(fields);
      toast.error(toastErrorMessage(error, 'Gagal memperbarui profil'));
    } finally {
      setSaving(false);
    }
  };

  return (
    <AdminPageShell
      title="Pengaturan"
      description="Kelola profil, kata sandi, dan preferensi akun Anda."
      variant="plain"
      icon={<User className="size-5" />}
    >
      <div className="grid w-full gap-6 xl:grid-cols-12 xl:items-start">
        {activeTab === 'profile' && profileError ? (
          <div className="xl:col-span-12">
            <ErrorWithRetry
              title="Gagal memuat profil"
              error={profileError}
              onRetry={() => {
                setProfileError(null);
                void (async () => {
                  if (!user) return;
                  setProfileLoading(true);
                  try {
                    const res = await api.get('/settings/profile');
                    const row = res.data.data;
                    if (row) {
                      setFormData({
                        name: row.name || user.name || '',
                        email: row.email || user.email || '',
                        phone: row.phone || '',
                        current_password: '',
                        new_password: '',
                        confirm_password: '',
                      });
                    }
                  } catch (err) {
                    setProfileError(err);
                    toast.error(toastErrorMessage(err, 'Gagal memuat profil'));
                  } finally {
                    setProfileLoading(false);
                  }
                })();
              }}
            />
          </div>
        ) : (
          activeTab === 'profile' && (
            <>
              <aside className="space-y-6 xl:col-span-4 2xl:col-span-3">
                <Card className={settingsCardClass}>
                  <CardHeader className="pb-2">
                    <CardTitle className="text-lg">Tampilan</CardTitle>
                    <CardDescription>
                      Pilih tema yang nyaman untuk mata saat Anda mengelola absensi di malam hari
                      atau siang hari.
                    </CardDescription>
                  </CardHeader>
                  <CardContent>
                    <Button
                      type="button"
                      variant="outline"
                      className="min-h-11 gap-2"
                      onClick={toggleTheme}
                      aria-pressed={theme === 'dark'}
                    >
                      {theme === 'dark' ? (
                        <Sun className="size-4" aria-hidden="true" />
                      ) : (
                        <Moon className="size-4" aria-hidden="true" />
                      )}
                      {theme === 'dark' ? 'Mode terang' : 'Mode gelap'}
                    </Button>
                  </CardContent>
                </Card>

                <Card className={settingsCardClass}>
                  <CardHeader className="pb-2">
                    <CardTitle className="text-lg">Ringkasan Akun</CardTitle>
                    <CardDescription>Data login Anda di sistem absensi.</CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="flex items-start gap-3 rounded-lg border border-border bg-muted/40 p-4">
                      <Shield className="mt-0.5 size-5 shrink-0 text-brand" aria-hidden="true" />
                      <div className="min-w-0 flex-1">
                        <p className="text-xs font-medium text-muted-foreground">Peran</p>
                        <Badge variant="secondary" className="mt-1">
                          {user ? userRoleLabel(user.role) : 'ΓÇö'}
                        </Badge>
                      </div>
                    </div>
                    <div className="flex items-start gap-3 text-sm">
                      <User
                        className="mt-0.5 size-4 shrink-0 text-muted-foreground"
                        aria-hidden="true"
                      />
                      <div className="min-w-0">
                        <p className="text-xs text-muted-foreground">Nama</p>
                        <p className="font-medium text-foreground">{formData.name || 'ΓÇö'}</p>
                      </div>
                    </div>
                    <div className="flex items-start gap-3 text-sm">
                      <Mail
                        className="mt-0.5 size-4 shrink-0 text-muted-foreground"
                        aria-hidden="true"
                      />
                      <div className="min-w-0 break-all">
                        <p className="text-xs text-muted-foreground">Email</p>
                        <p className="font-medium text-foreground">{formData.email || 'ΓÇö'}</p>
                      </div>
                    </div>
                    {formData.phone ? (
                      <div className="flex items-start gap-3 text-sm">
                        <Phone
                          className="mt-0.5 size-4 shrink-0 text-muted-foreground"
                          aria-hidden="true"
                        />
                        <div>
                          <p className="text-xs text-muted-foreground">No. HP</p>
                          <p className="font-medium text-foreground">{formData.phone}</p>
                        </div>
                      </div>
                    ) : null}
                    {isStudent ? (
                      <p className="rounded-lg bg-muted/50 p-3 text-xs text-muted-foreground">
                        Perangkat absensi terikat saat login pertama. Hubungi admin jika perlu reset
                        perangkat.
                      </p>
                    ) : null}
                  </CardContent>
                </Card>

                {!isStudent ? (
                  <Card className={cn(settingsCardClass, 'border-red-200 dark:border-red-900/50')}>
                    <CardHeader className="pb-2">
                      <CardTitle className="text-lg text-red-600 dark:text-red-400">
                        Manajemen Perangkat
                      </CardTitle>
                      <CardDescription>
                        Hapus penautan perangkat ini; login berikutnya akan meminta verifikasi
                        ulang.
                      </CardDescription>
                    </CardHeader>
                    <CardContent>
                      <Button
                        type="button"
                        variant="outline"
                        onClick={() => {
                          forgetDeviceFingerprint();
                          toast.success(
                            'Perangkat dilupakan. Anda akan diminta login kembali pada percobaan berikutnya.'
                          );
                        }}
                        className="min-h-11 w-full border-red-200 text-red-600 hover:bg-red-50 hover:text-red-700 dark:border-red-900 dark:text-red-400 dark:hover:bg-red-900/20 sm:w-auto"
                      >
                        <LogOut size={16} className="mr-2" aria-hidden="true" /> Lupakan Perangkat
                        Ini
                      </Button>
                    </CardContent>
                  </Card>
                ) : null}
              </aside>

              <Card className={cn(settingsCardClass, 'xl:col-span-8 2xl:col-span-9')}>
                <CardHeader className="pb-2">
                  <CardTitle className="text-lg">Informasi Profil</CardTitle>
                  <CardDescription>
                    Perbarui nama, kontak, dan kata sandi akun Anda.
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <form onSubmit={handleSaveProfile} className="space-y-4">
                    {profileLoading ? (
                      <div className="space-y-4" aria-busy="true" aria-label="Memuat profil">
                        <Skeleton className="h-10 w-full" />
                        <Skeleton className="h-10 w-full" />
                        <Skeleton className="h-10 w-full" />
                      </div>
                    ) : (
                      <>
                        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                          <div className="space-y-2 sm:col-span-2">
                            <Label>Nama Lengkap</Label>
                            <Input
                              type="text"
                              required
                              autoComplete="name"
                              value={formData.name}
                              onChange={(e) => {
                                setFormData({ ...formData, name: e.target.value });
                                if (fieldErrors.name)
                                  setFieldErrors((f) => ({ ...f, name: undefined }));
                              }}
                              className={cn(fieldErrors.name && 'border-red-500')}
                              aria-invalid={!!fieldErrors.name}
                              aria-describedby={fieldErrors.name ? 'name-error' : undefined}
                            />
                            {fieldErrors.name ? (
                              <p id="name-error" className="text-xs text-red-600">
                                {fieldErrors.name}
                              </p>
                            ) : null}
                          </div>
                          <div className="space-y-2">
                            <Label>No. HP</Label>
                            <Input
                              type="tel"
                              autoComplete="tel"
                              value={formData.phone}
                              onChange={(e) => {
                                setFormData({ ...formData, phone: e.target.value });
                                if (fieldErrors.phone)
                                  setFieldErrors((f) => ({ ...f, phone: undefined }));
                              }}
                              className={cn(fieldErrors.phone && 'border-red-500')}
                              aria-invalid={!!fieldErrors.phone}
                              aria-describedby={fieldErrors.phone ? 'phone-error' : undefined}
                            />
                            {fieldErrors.phone ? (
                              <p id="phone-error" className="text-xs text-red-600">
                                {fieldErrors.phone}
                              </p>
                            ) : null}
                          </div>
                          <div className="space-y-2">
                            <Label>Email</Label>
                            <Input
                              type="email"
                              required
                              autoComplete="email"
                              value={formData.email}
                              onChange={(e) => {
                                setFormData({ ...formData, email: e.target.value });
                                if (fieldErrors.email)
                                  setFieldErrors((f) => ({ ...f, email: undefined }));
                              }}
                              className={cn(fieldErrors.email && 'border-red-500')}
                              aria-invalid={!!fieldErrors.email}
                              aria-describedby={fieldErrors.email ? 'email-error' : undefined}
                            />
                            {fieldErrors.email ? (
                              <p id="email-error" className="text-xs text-red-600">
                                {fieldErrors.email}
                              </p>
                            ) : null}
                            <p className="mt-1 text-xs text-muted-foreground">
                              Gunakan email yang aktif untuk notifikasi dan pemulihan akun.
                            </p>
                          </div>
                        </div>

                        <hr className="my-6 border-border" />

                        <h3 className="mb-2 text-base font-bold text-foreground">
                          Ubah Kata Sandi
                        </h3>
                        <p className="mb-4 text-sm text-muted-foreground">
                          Kosongkan jika tidak ingin mengubah kata sandi.
                        </p>

                        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                          <div className="space-y-2 sm:col-span-2">
                            <Label>Kata Sandi Saat Ini</Label>
                            <Input
                              type="password"
                              autoComplete="current-password"
                              value={formData.current_password}
                              onChange={(e) => {
                                setFormData({ ...formData, current_password: e.target.value });
                                if (fieldErrors.current_password)
                                  setFieldErrors((f) => ({ ...f, current_password: undefined }));
                              }}
                              className={cn(fieldErrors.current_password && 'border-red-500')}
                              aria-invalid={!!fieldErrors.current_password}
                              aria-describedby={
                                fieldErrors.current_password ? 'current-password-error' : undefined
                              }
                            />
                            {fieldErrors.current_password ? (
                              <p id="current-password-error" className="text-xs text-red-600">
                                {fieldErrors.current_password}
                              </p>
                            ) : null}
                          </div>
                          <div className="space-y-2">
                            <Label>Kata Sandi Baru</Label>
                            <Input
                              type="password"
                              autoComplete="new-password"
                              value={formData.new_password}
                              onChange={(e) => {
                                setFormData({ ...formData, new_password: e.target.value });
                                if (fieldErrors.new_password)
                                  setFieldErrors((f) => ({ ...f, new_password: undefined }));
                              }}
                              className={cn(fieldErrors.new_password && 'border-red-500')}
                              aria-invalid={!!fieldErrors.new_password}
                              aria-describedby={
                                fieldErrors.new_password ? 'new-password-error' : undefined
                              }
                            />
                            {fieldErrors.new_password ? (
                              <p id="new-password-error" className="text-xs text-red-600">
                                {fieldErrors.new_password}
                              </p>
                            ) : null}
                          </div>
                          <div className="space-y-2">
                            <Label>Konfirmasi Kata Sandi</Label>
                            <Input
                              type="password"
                              autoComplete="new-password"
                              value={formData.confirm_password}
                              onChange={(e) => {
                                setFormData({ ...formData, confirm_password: e.target.value });
                                if (fieldErrors.confirm_password)
                                  setFieldErrors((f) => ({ ...f, confirm_password: undefined }));
                              }}
                              className={cn(fieldErrors.confirm_password && 'border-red-500')}
                              aria-invalid={!!fieldErrors.confirm_password}
                              aria-describedby={
                                fieldErrors.confirm_password ? 'confirm-password-error' : undefined
                              }
                            />
                            {fieldErrors.confirm_password ? (
                              <p id="confirm-password-error" className="text-xs text-red-600">
                                {fieldErrors.confirm_password}
                              </p>
                            ) : null}
                          </div>
                        </div>

                        <div className="flex justify-end pt-2">
                          <Button type="submit" disabled={saving || profileLoading}>
                            {saving ? 'Menyimpan...' : 'Simpan Perubahan'}
                          </Button>
                        </div>
                      </>
                    )}
                  </form>
                </CardContent>
              </Card>
            </>
          )
        )}
      </div>
    </AdminPageShell>
  );
}

