import { format } from 'date-fns';
import { id } from 'date-fns/locale';
import type { User } from '@/types/user';

const fetcher = (url: string) => api.get(url).then((res) => res.data);
const profileFetcher = (url: string) => api.get(url).then((res) => res.data.data);

type Summary = {
  total: number;
  present: number;
  late: number;
  absent: number;
  sick: number;
  excused: number;
  other: number;
};

const safeFormat = (value: unknown, fmt: string) => {
  try {
    const d =
      value instanceof Date
        ? value
        : new Date(
            typeof value === 'string' || typeof value === 'number' ? value : String(value ?? '')
          );
    if (Number.isNaN(d.getTime())) return '-';
    return format(d, fmt, { locale: id });
  } catch {
    return '-';
  }
};

export default function StudentAttendanceRecap() {
  const { studentId = '' } = useParams<{ studentId: string }>();
  const navigate = useNavigate();
  const location = useLocation();

  const backToStudent = (location.state as { backToStudent?: string } | null)?.backToStudent;
  const classIdFromState = (location.state as { classId?: string } | null)?.classId;

  const [searchTerm, setSearchTerm] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState('20');
  const [stickySummary, setStickySummary] = useState<Summary | null>(null);
  const [excuseDetail, setExcuseDetail] = useState<Report | null>(null);

  useEffect(() => {
    setPage(1);
  }, [startDate, endDate, classIdFromState, pageSize]);

  const profileSwr = useSWR<User>(studentId ? `/users/${studentId}` : null, profileFetcher, {
    revalidateOnFocus: false,
  });
  const { data: profile, isInitialLoading: profileLoading } = useSwrPageState(profileSwr);

  const queryParams = new URLSearchParams({
    page: page.toString(),
    limit: pageSize,
    userId: studentId,
    withSummary: page === 1 ? '1' : '0',
  });
  if (classIdFromState) queryParams.append('classId', classIdFromState);
  if (startDate && endDate) {
    queryParams.append('startDate', startDate);
    queryParams.append('endDate', endDate);
  }

  const swr = useSWR(studentId ? `/reports?${queryParams.toString()}` : null, fetcher, {
    revalidateOnFocus: false,
    keepPreviousData: true,
  });
  const { data, isPending: loading, isError, retry } = useSwrPageState(swr);

  const reports = useMemo<Report[]>(() => {
    return Array.isArray(data?.data) ? (data.data.filter(Boolean) as Report[]) : [];
  }, [data?.data]);

  const meta = (data?.meta as (PaginationMeta & { summary?: Summary }) | undefined) ?? null;
  const providedSummary = meta?.summary ?? null;

  useEffect(() => {
    if (providedSummary) setStickySummary(providedSummary);
  }, [providedSummary]);

  const computedSummary = useMemo(() => {
    if (stickySummary) return stickySummary;
    return reports.reduce(
      (acc, r) => {
        const s = String(r.status ?? '').toUpperCase();
        acc.total += 1;
        if (s === 'PRESENT') acc.present += 1;
        else if (s === 'LATE') acc.late += 1;
        else if (s === 'ABSENT') acc.absent += 1;
        else if (s === 'SICK') acc.sick += 1;
        else if (s === 'EXCUSED') acc.excused += 1;
        else acc.other += 1;
        return acc;
      },
      { total: 0, present: 0, late: 0, absent: 0, sick: 0, excused: 0, other: 0 }
    );
  }, [reports, stickySummary]);

  const resolveAssetUrl = (assetUrl: string | null | undefined) => {
    if (!assetUrl) return null;
    if (assetUrl.startsWith('http') || assetUrl.startsWith('data:')) return assetUrl;
    const apiBase = String(import.meta.env.VITE_API_BASE_URL || '/api');
    const assetBase = apiBase.startsWith('http')
      ? new URL(apiBase).origin
      : apiBase.replace(/\/api\/?$/, '');
    return `${assetBase}${assetUrl}`;
  };

  const filteredReports = useMemo(() => {
    const q = searchTerm.trim().toLowerCase();
    if (!q) return reports;
    return reports.filter((r) => {
      const sessionTitle = String(r.session_title ?? '').toLowerCase();
      const className = String(r.class_name ?? '').toLowerCase();
      const status = String(r.status ?? '').toLowerCase();
      const date = String(r.session_date ?? '').toLowerCase();
      return (
        sessionTitle.includes(q) || className.includes(q) || status.includes(q) || date.includes(q)
      );
    });
  }, [reports, searchTerm]);

  if (!studentId) {
    return (
      <AdminPageShell title="Rekap kehadiran" variant="plain">
        <Button variant="outline" onClick={() => navigate('/classes')}>
          Kembali
        </Button>
      </AdminPageShell>
    );
  }

  return (
    <AdminPageShell
      title="Rekap Kehadiran Mahasiswa"
      description="Lihat ringkasan dan detail absensi mahasiswa sesuai scope akses Anda."
      variant="plain"
      icon={<FileText className="size-5" />}
      breadcrumb={
        <AdminBreadcrumbs
          items={[
            { label: 'Kelas', href: '/classes' },
            ...(classIdFromState
              ? [{ label: 'Detail Kelas', href: `/classes/${classIdFromState}` }]
              : []),
            { label: 'Mahasiswa', href: backToStudent || `/students/${studentId}` },
            { label: 'Rekap Kehadiran' },
          ]}
        />
      }
    >
      {isError ? (
        <ErrorWithRetry title="Gagal memuat rekap" error={swr.error} onRetry={retry} />
      ) : (
        <div className="space-y-6">
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            <Card>
              <CardContent className="p-5">
                <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                  Total Sesi
                </div>
                <div className="mt-2 text-2xl font-extrabold text-foreground">
                  {loading ? <Skeleton className="h-8 w-16" /> : computedSummary.total}
                </div>
                <div className="mt-2 text-xs text-muted-foreground">
                  {profileLoading ? (
                    <Skeleton className="h-4 w-32" />
                  ) : profile ? (
                    <>
                      {profile.name} ΓÇó {profile.nim_nip || 'ΓÇö'}
                    </>
                  ) : null}
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-5">
                <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                  Hadir
                </div>
                <div className="mt-2 text-2xl font-extrabold text-foreground">
                  {loading ? (
                    <Skeleton className="h-8 w-16" />
                  ) : (
                    computedSummary.present + computedSummary.late
                  )}
                </div>
                <div className="mt-2 flex flex-wrap gap-2 text-xs text-muted-foreground">
                  <span>Hadir: {computedSummary.present}</span>
                  <span>ΓÇó</span>
                  <span>Terlambat: {computedSummary.late}</span>
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-5">
                <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                  Alfa
                </div>
                <div className="mt-2 text-2xl font-extrabold text-foreground">
                  {loading ? <Skeleton className="h-8 w-16" /> : computedSummary.absent}
                </div>
                <div className="mt-2 text-xs text-muted-foreground">
                  Tidak hadir tanpa keterangan
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-5">
                <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                  Izin/Sakit
                </div>
                <div className="mt-2 text-2xl font-extrabold text-foreground">
                  {loading ? (
                    <Skeleton className="h-8 w-16" />
                  ) : (
                    computedSummary.excused + computedSummary.sick
                  )}
                </div>
                <div className="mt-2 flex flex-wrap gap-2 text-xs text-muted-foreground">
                  <span>Izin: {computedSummary.excused}</span>
                  <span>ΓÇó</span>
                  <span>Sakit: {computedSummary.sick}</span>
                </div>
              </CardContent>
            </Card>
          </div>

          <div className="overflow-hidden rounded-xl border border-border bg-card shadow-card dark:shadow-none dark:ring-1 dark:ring-white/10">
            <div className="flex flex-col gap-3 border-b border-border p-5 sm:flex-row sm:items-end sm:justify-between">
              <div className="min-w-0 flex-1">
                <div className="text-sm font-semibold text-foreground">Detail Kehadiran</div>
                <div className="mt-1 text-xs text-muted-foreground">
                  Filter tanggal berlaku untuk semua record. Pencarian hanya pada data halaman ini.
                </div>
              </div>
              <div className="flex w-full flex-col gap-3 sm:w-auto sm:flex-row sm:items-center">
                <div className="relative w-full sm:w-[260px]">
                  <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Cari sesi, kelas, statusΓÇª"
                    aria-label="Cari sesi, kelas, status"
                    className="pl-9"
                  />
                </div>
                <div className="flex w-full items-center gap-2 sm:w-auto">
                  <DatePicker
                    value={startDate}
                    onChange={setStartDate}
                    placeholder="Dari tanggal"
                    className="w-full sm:w-[160px]"
                  />
                  <span
                    className="flex h-11 shrink-0 items-center px-0.5 text-muted-foreground"
                    aria-hidden="true"
                  >
                    ΓÇô
                  </span>
                  <DatePicker
                    value={endDate}
                    onChange={setEndDate}
                    placeholder="Sampai tanggal"
                    className="w-full sm:w-[160px]"
                    popoverAlign="end"
                  />
                </div>
              </div>
            </div>

            {loading ? (
              <div className="p-5">
                <div className="space-y-3">
                  {Array.from({ length: 6 }).map((_, i) => (
                    <Skeleton key={i} className="h-10 w-full" />
                  ))}
                </div>
              </div>
            ) : reports.length === 0 ? (
              <div className="p-0">
                <AdminEmptyState
                  compact
                  icon={UserCircle2}
                  title="Belum ada data kehadiran"
                  description="Data akan muncul ketika mahasiswa memiliki riwayat absensi dalam scope akses Anda."
                  className="border-0 shadow-none"
                />
              </div>
            ) : (
              <>
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader className="sticky top-0 z-10 bg-muted/50 [&_tr]:border-b">
                      <TableRow>
                        <TableHead className="w-12">No</TableHead>
                        <TableHead>Tanggal</TableHead>
                        <TableHead>Sesi</TableHead>
                        <TableHead>Kelas</TableHead>
                        <TableHead>Status</TableHead>
                        <TableHead>Check-in</TableHead>
                        <TableHead className="text-right">Bukti</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {filteredReports.length === 0 ? (
                        <TableRow>
                          <TableCell colSpan={7} className="p-0">
                            <AdminEmptyState
                              compact
                              icon={UserCircle2}
                              title="Tidak ada hasil"
                              description="Ubah kata kunci pencarian."
                              className="border-0 shadow-none"
                            />
                          </TableCell>
                        </TableRow>
                      ) : (
                        filteredReports.map((r, idx) => (
                          <TableRow key={r.id}>
                            <TableCell className="text-muted-foreground">
                              meta ? (meta.page - 1) * meta.limit + idx + 1 : idx + 1
                            </TableCell>
                            <TableCell className="text-sm text-muted-foreground">
                              {safeFormat(r.session_date, 'dd MMM yyyy')}
                            </TableCell>
                            <TableCell className="font-medium">{r.session_title}</TableCell>
                            <TableCell className="text-sm text-muted-foreground">
                              {r.class_name || 'ΓÇö'}
                            </TableCell>
                            <TableCell>
                              <Badge variant={attendanceBadgeVariant(r.status)}>
                                {attendanceStatusLabel(r.status)}
                              </Badge>
                            </TableCell>
                            <TableCell className="text-sm text-muted-foreground">
                              {safeFormat(r.check_in_time, 'dd MMM yyyy, HH:mm')}
                            </TableCell>
                            <TableCell className="text-right">
                              {String(r.status).toUpperCase() === 'SICK' ||
                              String(r.status).toUpperCase() === 'EXCUSED' ? (
                                <div className="flex items-center justify-end gap-2">
                                  {r.excuse_proof_url ? (
                                    <Button asChild variant="link" className="px-0">
                                      <a
                                        href={resolveAssetUrl(r.excuse_proof_url) || '#'}
                                        target="_blank"
                                        rel="noreferrer"
                                      >
                                        Bukti
                                      </a>
                                    </Button>
                                  ) : null}
                                  {r.excuse_description || r.excuse_proof_url ? (
                                    <Button
                                      type="button"
                                      variant="outline"
                                      size="sm"
                                      onClick={() => setExcuseDetail(r)}
                                    >
                                      Detail
                                    </Button>
                                  ) : (
                                    <span className="text-muted-foreground">ΓÇö</span>
                                  )}
                                </div>
                              ) : (
                                <span className="text-muted-foreground">ΓÇö</span>
                              )}
                            </TableCell>
                          </TableRow>
                        ))
                      )}
                    </TableBody>
                  </Table>
                </div>
                {meta ? (
                  <div className="flex flex-col gap-3 border-t border-border p-3 sm:flex-row sm:items-center sm:justify-between">
                    <div className="flex items-center gap-2">
                      <span className="text-xs text-muted-foreground">Per halaman</span>
                      <select
                        className="h-9 rounded-md border border-border bg-background px-2 text-sm"
                        value={pageSize}
                        onChange={(e) => setPageSize(e.target.value)}
                      >
                        <option value="20">20</option>
                        <option value="50">50</option>
                      </select>
                    </div>
                    <TablePagination meta={meta} onPageChange={setPage} itemLabel="absensi" />
                  </div>
                ) : null}
              </>
            )}
          </div>
        </div>
      )}

      <Dialog
        open={Boolean(excuseDetail)}
        onOpenChange={(open) => {
          if (!open) setExcuseDetail(null);
        }}
      >
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>Detail Izin/Sakit</DialogTitle>
            <DialogDescription>
              {excuseDetail
                ? `${excuseDetail.session_title} ΓÇó ${safeFormat(excuseDetail.session_date, 'dd MMM yyyy')}`
                : ''}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-3">
            <div className="text-sm">
              <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                Keterangan
              </div>
              <div className="mt-1 text-foreground">{excuseDetail?.excuse_description || 'ΓÇö'}</div>
            </div>
            <div className="flex items-center justify-end">
              {excuseDetail?.excuse_proof_url ? (
                <Button asChild variant="outline">
                  <a
                    href={resolveAssetUrl(excuseDetail.excuse_proof_url) || '#'}
                    target="_blank"
                    rel="noreferrer"
                  >
                    Buka Bukti
                  </a>
                </Button>
              ) : null}
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </AdminPageShell>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { Link, useLocation, useNavigate, useParams } from 'react-router-dom';
import useSWR from 'swr';
import { ArrowLeft, FileText, Smartphone, User } from 'lucide-react';
import { toast } from 'sonner';
import api from '@/services/api';
import { useAuthStore } from '@/stores/authStore';
import { useSwrPageState } from '@/hooks/useSwrPageState';
import { useFacultyDirectory } from '@/hooks/useFacultyDirectory';
import AdminPageShell from '@/components/AdminPageShell';
import { ErrorWithRetry } from '@/components/ErrorWithRetry';
import { AdminBreadcrumbs } from '@/components/admin/AdminBreadcrumbs';
import ActionLoadingOverlay from '@/components/ActionLoadingOverlay';
import { ConfirmModal } from '@/components/ConfirmModal';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import { Skeleton } from '@/components/ui/skeleton';
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import type { User as AppUser } from '@/types/user';
import { formatClassLabel } from '@/lib/utils/classLabel';
import { toastErrorMessage } from '@/lib/utils/toastMessage';

type EnrollmentRow = { id: string; name: string; semester: number };

type ProfileForm = {
  name: string;
  email: string;
  nim_nip: string;
  phone: string;
  department: string;
  semester: number;
  is_active: boolean;
};

export default function StudentDetail() {
  const { studentId = '' } = useParams<{ studentId: string }>();
  const navigate = useNavigate();
  const location = useLocation();
  const { user: currentUser } = useAuthStore();

  const backTo =
    (location.state as { from?: string } | null)?.from ||
    ((location.state as { classId?: string } | null)?.classId
      ? `/classes/${(location.state as { classId: string }).classId}`
      : '/classes');
  const classIdFromState = (location.state as { classId?: string } | null)?.classId;

  const [form, setForm] = useState<ProfileForm>({
    name: '',
    email: '',
    nim_nip: '',
    phone: '',
    department: '',
    semester: 1,
    is_active: true,
  });
  const [password, setPassword] = useState('');
  const [passwordConfirm, setPasswordConfirm] = useState('');
  const {
    facultiesData,
    departmentQuery,
    setDepartmentQuery,
    totalDepartments,
    filteredFacultiesData,
  } = useFacultyDirectory();
  const [saving, setSaving] = useState(false);
  const [savingPassword, setSavingPassword] = useState(false);
  const [resettingDevice, setResettingDevice] = useState(false);
  const [isSaveConfirmOpen, setIsSaveConfirmOpen] = useState(false);
  const [isPasswordConfirmOpen, setIsPasswordConfirmOpen] = useState(false);
  const [isResetDeviceOpen, setIsResetDeviceOpen] = useState(false);

  const fetcher = (url: string) => api.get(url).then((r) => r.data.data);

  const profileSwr = useSWR<AppUser>(studentId ? `/users/${studentId}` : null, fetcher, {
    revalidateOnFocus: false,
  });
  const {
    data: profile,
    isInitialLoading,
    isError,
    retry,
    error,
    mutate,
  } = useSwrPageState(profileSwr);

  const enrollSwr = useSWR<EnrollmentRow[]>(
    studentId && profile?.role === 'USER' ? `/users/${studentId}/enrollments` : null,
    fetcher,
    { revalidateOnFocus: false }
  );
  const { data: enrollments = [], isInitialLoading: loadingClasses } = useSwrPageState(enrollSwr);

  useEffect(() => {
    if (!profile) return;
    setForm({
      name: profile.name ?? '',
      email: profile.email ?? '',
      nim_nip: profile.nim_nip ?? '',
      phone: profile.phone ?? '',
      department: profile.department ?? '',
      semester: profile.semester ?? 1,
      is_active: profile.is_active ?? true,
    });
  }, [profile]);

  const saveProfile = async () => {
    if (!studentId || saving) return;
    setSaving(true);
    try {
      await api.put(`/users/${studentId}`, {
        name: form.name.trim(),
        email: form.email.trim(),
        nim_nip: form.nim_nip.trim(),
        phone: form.phone.trim(),
        department: form.department.trim(),
        semester: form.semester,
        is_active: form.is_active,
      });
      toast.success('Data mahasiswa berhasil disimpan');
      setIsSaveConfirmOpen(false);
      await mutate();
    } catch (err: unknown) {
      toast.error(toastErrorMessage(err, 'Gagal menyimpan data'));
    } finally {
      setSaving(false);
    }
  };

  const savePassword = async () => {
    if (!studentId || savingPassword) return;
    if (password.length < 6) {
      toast.error('Kata sandi minimal 6 karakter');
      return;
    }
    if (password !== passwordConfirm) {
      toast.error('Konfirmasi kata sandi tidak cocok');
      return;
    }
    setSavingPassword(true);
    try {
      await api.put(`/users/${studentId}`, { password });
      toast.success('Kata sandi berhasil diperbarui');
      setPassword('');
      setPasswordConfirm('');
      setIsPasswordConfirmOpen(false);
    } catch (err: unknown) {
      toast.error(toastErrorMessage(err, 'Gagal memperbarui kata sandi'));
    } finally {
      setSavingPassword(false);
    }
  };

  const resetDevice = async () => {
    if (!studentId || resettingDevice) return;
    setResettingDevice(true);
    try {
      await api.post(`/users/${studentId}/reset-device`);
      toast.success('Perangkat berhasil di-reset. Mahasiswa dapat login di perangkat baru.');
      setIsResetDeviceOpen(false);
      await mutate();
    } catch (err: unknown) {
      toast.error(toastErrorMessage(err, 'Gagal reset perangkat'));
    } finally {
      setResettingDevice(false);
    }
  };

  const actionLabel = saving
    ? 'Menyimpan dataΓÇª'
    : savingPassword
      ? 'Memperbarui kata sandiΓÇª'
      : resettingDevice
        ? 'Mereset perangkatΓÇª'
        : null;

  if (!studentId) {
    return (
      <AdminPageShell title="Mahasiswa tidak ditemukan" variant="plain">
        <Button variant="outline" onClick={() => navigate('/classes')}>
          Kembali
        </Button>
      </AdminPageShell>
    );
  }

  if (isError && !profile) {
    const status = (error as { response?: { status?: number } })?.response?.status;
    return (
      <AdminPageShell title="Biodata Mahasiswa" variant="plain">
        <ErrorWithRetry
          title={status === 403 ? 'Anda tidak memiliki akses' : 'Gagal memuat data mahasiswa'}
          error={profileSwr.error}
          onRetry={retry}
        />
        <Button variant="outline" className="mt-4" onClick={() => navigate(backTo)}>
          <ArrowLeft className="mr-2 size-4" />
          Kembali
        </Button>
      </AdminPageShell>
    );
  }

  const enrolledDate = profile?.enrollment_date
    ? new Date(profile.enrollment_date).toLocaleDateString('id-ID', {
        day: 'numeric',
        month: 'long',
        year: 'numeric',
      })
    : null;

  return (
    <>
      <ActionLoadingOverlay show={!!actionLabel} label={actionLabel ?? ''} />
      <AdminPageShell
        title="Biodata Mahasiswa"
        description="Perbarui data akun mahasiswa langsung dari halaman ini."
        breadcrumb={
          <AdminBreadcrumbs
            items={[
              { label: 'Kelas', href: '/classes' },
              ...(classIdFromState
                ? [{ label: 'Detail Kelas', href: `/classes/${classIdFromState}` }]
                : []),
              { label: profile?.name ?? 'Biodata Mahasiswa' },
            ]}
          />
        }
        variant="plain"
        icon={<User className="size-5" />}
        actions={
          <div className="flex flex-wrap gap-2">
            {profile?.role === 'USER' ? (
              <Button
                type="button"
                variant="outline"
                onClick={() =>
                  navigate(`/students/${studentId}/attendance`, {
                    state: { backToStudent: `/students/${studentId}`, classId: classIdFromState },
                  })
                }
              >
                <FileText className="mr-2 size-4" />
                Rekap Kehadiran
              </Button>
            ) : null}
          </div>
        }
      >
        <div className="grid gap-6 lg:grid-cols-[minmax(0,280px)_1fr]">
          <aside className="space-y-4">
            <section className="rounded-lg border border-border bg-card p-5">
