              )}
            </section>
          </div>
        </div>
      </AdminPageShell>

      <ConfirmModal
        isOpen={isSaveConfirmOpen}
        onClose={() => setIsSaveConfirmOpen(false)}
        onConfirm={() => void saveProfile()}
        title="Simpan perubahan biodata?"
        description={`Data ${form.name || 'mahasiswa'} akan diperbarui di sistem.`}
        confirmText="Ya, Simpan"
        variant="primary"
        loading={saving}
        loadingText="MenyimpanΓÇª"
      />

      <ConfirmModal
        isOpen={isPasswordConfirmOpen}
        onClose={() => setIsPasswordConfirmOpen(false)}
        onConfirm={() => void savePassword()}
        title="Perbarui kata sandi?"
        description="Mahasiswa harus login ulang dengan kata sandi baru."
        confirmText="Ya, Perbarui"
        variant="primary"
        loading={savingPassword}
        loadingText="MemperbaruiΓÇª"
      />

      <ConfirmModal
        isOpen={isResetDeviceOpen}
        onClose={() => setIsResetDeviceOpen(false)}
        onConfirm={() => void resetDevice()}
        title="Reset perangkat mahasiswa?"
        description="Ikatan perangkat absensi akan dihapus. Mahasiswa bisa mendaftarkan perangkat baru saat login."
        confirmText="Ya, Reset"
        variant="danger"
        loading={resettingDevice}
        loadingText="MeresetΓÇª"
      />
    </>
  );
}

import React, { useMemo, useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import api from '@/services/api';
import useSWR from 'swr';
import { useAuthStore } from '@/stores/authStore';
import {
  Plus,
  Search,
  Edit2,
  Trash2,
  X,
  Download,
  Upload,
  Smartphone,
  Users as UsersIcon,
  Eye,
  EyeOff,
} from 'lucide-react';
import { AdminEmptyState } from '@/components/admin/AdminEmptyState';
import { CardSkeletonList } from '@/components/admin/CardSkeleton';
import { Skeleton } from '@/components/ui/skeleton';
import { userRoleLabel } from '@/lib/utils/statusLabel';
import { toastErrorMessage } from '@/lib/utils/toastMessage';
import { toast } from 'sonner';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  SelectGroup,
  SelectLabel,
} from '@/components/ui/select';
import { ConfirmModal } from '@/components/ConfirmModal';
import ActionLoadingOverlay from '@/components/ActionLoadingOverlay';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import AdminPageShell from '@/components/AdminPageShell';
import { TablePagination } from '@/components/ui/TablePagination';
import { useSwrPageState } from '@/hooks/useSwrPageState';
import { useFacultyDirectory } from '@/hooks/useFacultyDirectory';
import { ErrorWithRetry } from '@/components/ErrorWithRetry';
import { SlowLoadingHint } from '@/components/admin/SlowLoadingHint';
import type { User } from '@/types/user';
import type { PaginationMeta } from '@/types/common';
import { ClassMultiSelect, type ClassOption } from '@/components/ClassMultiSelect';
import { formatClassLabel } from '@/lib/utils/classLabel';

export default function Users() {
  const { user: currentUser } = useAuthStore();
  const [searchTerm, setSearchTerm] = useState('');
  const [roleFilter, setRoleFilter] = useState('ALL');
  const [statusFilter, setStatusFilter] = useState('ALL');

  // Pagination & Debounce State
  const [page, setPage] = useState(1);
  const [debouncedSearch, setDebouncedSearch] = useState('');

  // Debounce search input at 400ms
  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(searchTerm);
    }, 400);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  // Reset page to 1 when debouncedSearch or other filters change
  useEffect(() => {
    setPage(1);
  }, [debouncedSearch, roleFilter, statusFilter]);

  // Modal state
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [importFile, setImportFile] = useState<File | null>(null);
  const [importing, setImporting] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [showPassword, setShowPassword] = useState(false);

  // Form state
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    role: 'USER',
    is_active: true,
    department: '',
    nim_nip: '',
    phone: '',
    semester: 1,
  });
  const {
    facultiesData,
    departmentQuery,
    setDepartmentQuery,
    totalDepartments,
    filteredFacultiesData,
  } = useFacultyDirectory();
  const [classIds, setClassIds] = useState<string[]>([]);
  const [enrolledClasses, setEnrolledClasses] = useState<ClassOption[]>([]);

  // Reset Modal state
  const [isResetModalOpen, setIsResetModalOpen] = useState(false);
  const [userToReset, setUserToReset] = useState<string | null>(null);

  const fetcher = (url: string) => api.get(url).then((res) => res.data);
  // Delete Modal state
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [userToDelete, setUserToDelete] = useState<string | null>(null);

  // Loading state untuk aksi tulis
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [resetting, setResetting] = useState(false);

  const queryParams = new URLSearchParams({
    page: page.toString(),
    limit: '20',
    search: debouncedSearch.trim(),
    role: roleFilter,
    status: statusFilter,
  });

  const swr = useSWR(`/users?${queryParams.toString()}`, fetcher, { revalidateOnFocus: false });
  const { isPending: loading, isError, showSlowLoadingHint, retry } = useSwrPageState(swr);
  const { data, mutate, isValidating } = swr;

  const users: User[] = Array.isArray(data?.data) ? data.data : [];
  const meta: PaginationMeta | null = data?.meta || null;

  const handleOpenModal = async (user: User | null = null) => {
    setClassIds([]);
    setEnrolledClasses([]);
    setShowPassword(false);
    if (user) {
      setEditingUser(user);
      setFormData({
        name: user.name,
        email: user.email,
        password: '',
        role: user.role,
        nim_nip: user.nim_nip || '',
        department: user.department || '',
        phone: user.phone || '',
        semester: user.semester || 1,
        is_active: user.is_active,
      });
      if (user.role === 'USER') {
        try {
          const res = await api.get(`/users/${user.id}/enrollments`);
          setEnrolledClasses(res.data.data ?? []);
        } catch {
          toast.error('Gagal memuat kelas mahasiswa');
        }
      }
    } else {
      setEditingUser(null);
      setFormData({
        name: '',
        email: '',
        password: '',
        role: 'USER',
        nim_nip: '',
        department: '',
        phone: '',
        semester: 1,
        is_active: true,
      });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (saving) return;
    setSaving(true);
    try {
      const payload = {
        ...formData,
        class_ids: formData.role === 'USER' ? classIds : [],
      };
      if (editingUser) {
        const res = await api.put(`/users/${editingUser.id}`, payload);
        const added = res.data?.data?.enrolled_added ?? 0;
        if (added > 0) {
          toast.success(`Pengguna diperbarui dan ditambahkan ke ${added} kelas`);
        } else {
          toast.success('Pengguna berhasil diperbarui');
        }
      } else {
        const res = await api.post('/users', payload);
        const enrolled = res.data?.data?.enrolled_classes ?? 0;
        if (enrolled > 0) {
          toast.success(`Pengguna ditambahkan dan didaftarkan ke ${enrolled} kelas`);
        } else {
          toast.success('Pengguna berhasil ditambahkan');
        }
      }
      setIsModalOpen(false);
      setClassIds([]);
      setEnrolledClasses([]);
      mutate();
    } catch (error: unknown) {
      toast.error(toastErrorMessage(error, 'Terjadi kesalahan'));
    } finally {
      setSaving(false);
    }
  };

  const openDeleteConfirm = (id: string) => {
    setUserToDelete(id);
    setIsDeleteModalOpen(true);
  };

  const confirmDeleteUser = async () => {
    if (!userToDelete || deleting) return;
    setDeleting(true);
    try {
      await api.delete(`/users/${userToDelete}`);
      toast.success('Pengguna berhasil dihapus');
      setIsDeleteModalOpen(false);
      setUserToDelete(null);
      mutate();
    } catch (error) {
      toast.error(toastErrorMessage(error, 'Gagal menghapus pengguna'));
    } finally {
      setDeleting(false);
    }
  };

  const hasFilters =
    Boolean(debouncedSearch.trim()) || roleFilter !== 'ALL' || statusFilter !== 'ALL';

  const roleBadgeProps = (role: string) => ({
    variant: (role === 'SUPER_ADMIN'
      ? 'default'
      : role === 'ADMIN'
        ? 'secondary'
        : role === 'CONTENT_ADMIN'
          ? 'warning'
          : 'outline') as 'default' | 'secondary' | 'warning' | 'outline',
    className:
      role === 'SUPER_ADMIN'
        ? 'bg-purple-600 hover:bg-purple-700'
        : role === 'ADMIN'
          ? 'bg-sky-600 text-white hover:bg-sky-700 dark:bg-sky-600'
          : role === 'CONTENT_ADMIN'
            ? 'bg-amber-500 hover:bg-amber-600'
            : '',
  });

  const filteredUsers = users;

  const handleDownloadTemplate = async () => {
    const { default: ExcelJS } = await import('exceljs');
    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet('Data Mahasiswa');
    const importYear = new Date().getFullYear();

    sheet.columns = [
      { header: 'Nama Lengkap', key: 'name', width: 25 },
      { header: 'Email', key: 'email', width: 25 },
      { header: 'NIM_NIP', key: 'nim', width: 20 },
      { header: 'Departemen', key: 'dept', width: 25 },
      { header: 'Semester', key: 'semester', width: 12 },
      { header: 'No_HP', key: 'phone', width: 20 },
      { header: 'Role (USER/ADMIN/CONTENT_ADMIN)', key: 'role', width: 26 },
      { header: 'Kelas (pisahkan dengan |)', key: 'classes', width: 34 },
    ];

    sheet.getRow(1).font = { bold: true };
    sheet.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE0E7FF' } };

    // Example row
    sheet.addRow({
      name: 'Budi Santoso',
      email: 'budi@mhs.kampus.ac.id',
      nim: '210010101',
      dept: 'Teknik Informatika',
      semester: 1,
      phone: '081234567890',
      role: 'USER',
      classes: 'Kelas A | Kelas Praktikum A',
    });

    sheet.addRow([]);
    sheet.addRow({
      name: `Catatan: hasil import otomatis memakai enrollment_date 1 Agustus ${importYear}. Kelas dipisahkan dengan tanda | dan kelas baru otomatis dibuat atas akun pengimpor.`,
    });
    sheet.mergeCells(`A4:H4`);
    sheet.getCell('A4').font = { italic: true, color: { argb: 'FF475569' } };

    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Template_Import_Mahasiswa.xlsx`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleImportSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!importFile) {
      toast.error('Silakan pilih file Excel terlebih dahulu');
      return;
    }

    setImporting(true);
    const formData = new FormData();
    formData.append('file', importFile);

    try {
      const res = await api.post('/users/import', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      const importedAt = res.data?.data?.enrollment_date
        ? new Date(res.data.data.enrollment_date).toLocaleDateString('id-ID', {
            day: 'numeric',
            month: 'long',
            year: 'numeric',
          })
        : null;
      const classesCreated = Number(res.data?.data?.classes_created || 0);
      const enrollmentsCreated = Number(res.data?.data?.class_enrollments_created || 0);
      toast.success(
        importedAt
          ? `${res.data.message} Enrollment date default: ${importedAt}. Kelas baru: ${classesCreated}. Enrollment kelas: ${enrollmentsCreated}.`
          : res.data.message
      );
      setIsImportModalOpen(false);
      setImportFile(null);
      mutate(); // Refresh list
    } catch (error: unknown) {
      toast.error(toastErrorMessage(error, 'Gagal mengimpor data Excel'));
    } finally {
      setImporting(false);
    }
  };

  const openResetConfirm = (id: string) => {
    setUserToReset(id);
    setIsResetModalOpen(true);
  };

  const confirmResetDevice = async () => {
    if (!userToReset || resetting) return;
    setResetting(true);
    try {
      await api.post(`/users/${userToReset}/reset-device`);
      toast.success('Perangkat berhasil di-reset');
      setIsResetModalOpen(false);
      setUserToReset(null);
      mutate();
