                      <TableCell className="font-medium">{p.title}</TableCell>
                      <TableCell>{p.category?.name ?? '-'}</TableCell>
                      <TableCell>{p.date_label ?? '-'}</TableCell>
                      <TableCell>
                        <Badge variant={p.is_published ? 'success' : 'secondary'}>
