import React, { useMemo, useState } from 'react';
import useSWR from 'swr';
import api from '@/services/api';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { ConfirmModal } from '@/components/ConfirmModal';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import type { PublicProgram } from '@/types/publicSite';
import { getErrorMessage } from '@/lib/http/errorMessage';
import AdminPageShell from '@/components/AdminPageShell';
import AdminCard from '@/components/AdminCard';
import PublicSiteProgramPreview from '@/components/publicSiteAdmin/PublicSiteProgramPreview';
import { ClipboardList } from 'lucide-react';
import { CmsTabNav, type CmsTabItem } from '@/components/ui/CmsTabNav';
import { CmsPublishTabs } from '@/components/ui/CmsPublishTabs';
import { CmsEditorLayout } from '@/components/cms/CmsEditorLayout';
import { CmsListToolbar } from '@/components/cms/CmsListToolbar';
import { AdminContentTransition } from '@/components/admin/AdminContentTransition';

type PageTab = 'form' | 'list';
const PAGE_TABS: readonly CmsTabItem<PageTab>[] = [
  { id: 'list', label: 'Daftar' },
  { id: 'form', label: 'Editor' },
];

export default function PublicSitePrograms() {
  const fetcher = (url: string) => api.get(url).then((r) => r.data.data);
  const { data: programs = [], mutate } = useSWR<PublicProgram[]>(
    '/public-site/admin/programs',
    fetcher,
    { revalidateOnFocus: false }
  );

  const [pageTab, setPageTab] = useState<PageTab>('list');
  const [form, setForm] = useState<{
    id?: string;
    title?: string;
    description?: string;
    isPublished?: boolean;
    division?: string;
    fundingSource?: string;
    location?: string;
    target?: string;
    rationale?: string;
  }>({});
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');
  const resetForm = () => setForm({});
  const resetDatesFromRange = (range: string) => {
    const raw = String(range ?? '').trim();
    if (!raw) {
      setDateStart('');
      setDateEnd('');
      return;
    }
    const parts = raw.split(' - ');
    if (parts.length >= 2) {
      setDateStart(parts[0] || '');
      setDateEnd(parts.slice(1).join(' - ') || '');
      return;
    }
    setDateStart(raw);
    setDateEnd('');
  };

  const dateRangePreview =
    dateStart && dateEnd ? `${dateStart} - ${dateEnd}` : dateStart || dateEnd || '';

  const [isDeleteOpen, setIsDeleteOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const deleteDescription = useMemo(() => 'Yakin ingin menghapus program kerja ini?', []);

  const openDelete = (id: string) => {
    setDeleteId(id);
    setIsDeleteOpen(true);
  };

  const confirmDelete = async () => {
    if (!deleteId) return;
    try {
      await api.delete(`/public-site/admin/programs/${deleteId}`);
      toast.success('Berhasil dihapus');
      setIsDeleteOpen(false);
      setDeleteId(null);
      mutate();
    } catch (e: any) {
      toast.error(getErrorMessage(e, 'Gagal menghapus'));
    }
  };

  const upsert = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const dateRange =
        dateStart && dateEnd ? `${dateStart} - ${dateEnd}` : dateStart || dateEnd || undefined;
      if (form.id) {
        await api.put(`/public-site/admin/programs/${form.id}`, {
          title: form.title,
          dateRange,
          description: form.description,
          isPublished: form.isPublished ?? false,
          division: form.division,
          fundingSource: form.fundingSource,
          location: form.location,
          target: form.target,
          rationale: form.rationale,
        });
        toast.success('Program kerja diperbarui');
      } else {
        await api.post('/public-site/admin/programs', {
          title: form.title,
          dateRange,
          description: form.description,
          isPublished: form.isPublished ?? false,
          division: form.division,
          fundingSource: form.fundingSource,
          location: form.location,
          target: form.target,
          rationale: form.rationale,
        });
        toast.success('Program kerja ditambahkan');
      }
      resetForm();
      setDateStart('');
      setDateEnd('');
      setPageTab('list');
      mutate();
    } catch (err: any) {
      toast.error(getErrorMessage(err, 'Gagal menyimpan'));
    }
  };

  return (
    <AdminPageShell
      title="Program Kerja"
      description="Kelola daftar program kerja yang akan tampil di halaman publik."
      variant="plain"
      icon={<ClipboardList size={22} />}
    >
      <CmsTabNav<PageTab>
        tabs={PAGE_TABS}
        value={pageTab}
        onChange={setPageTab}
        ariaLabel="Mode program kerja"
      />

      {pageTab === 'form' ? (
        <AdminContentTransition contentKey={`form-${form.id ?? 'new'}`}>
          <CmsEditorLayout
            preview={
              <PublicSiteProgramPreview
                title={form.title}
                dateRange={dateRangePreview}
                description={form.rationale ?? form.description}
                isPublished={form.isPublished}
                division={form.division}
                fundingSource={form.fundingSource}
                location={form.location}
                target={form.target}
              />
            }
          >
            <AdminCard
              title={form.id ? 'Ubah program' : 'Program baru'}
              description="Isi detail program kerja."
            >
              <form onSubmit={upsert} className="space-y-4">
                <div className="space-y-2">
                  <Label>Judul</Label>
                  <Input
                    value={form.title ?? ''}
                    onChange={(e) => setForm((p) => ({ ...p, title: e.target.value }))}
                  />
                </div>
                <div className="grid gap-4 sm:grid-cols-2">
                  <div className="space-y-2">
                    <Label>Tanggal mulai</Label>
                    <Input
                      type="date"
                      value={dateStart}
                      onChange={(e) => setDateStart(e.target.value)}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label>Tanggal selesai</Label>
                    <Input
                      type="date"
                      value={dateEnd}
                      onChange={(e) => setDateEnd(e.target.value)}
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <Label>Divisi</Label>
                  <Input
                    value={form.division ?? ''}
                    onChange={(e) => setForm((p) => ({ ...p, division: e.target.value }))}
                    placeholder="Divisi yang bertanggung jawab"
                  />
                </div>
                <div className="space-y-2">
                  <Label>Sumber Dana</Label>
                  <Input
                    value={form.fundingSource ?? ''}
                    onChange={(e) => setForm((p) => ({ ...p, fundingSource: e.target.value }))}
                    placeholder="Sumber dana program"
                  />
                </div>
                <div className="space-y-2">
                  <Label>Lokasi</Label>
                  <Input
                    value={form.location ?? ''}
                    onChange={(e) => setForm((p) => ({ ...p, location: e.target.value }))}
                    placeholder="Lokasi program"
                  />
                </div>
                <div className="space-y-2">
                  <Label>Target</Label>
                  <Input
                    value={form.target ?? ''}
                    onChange={(e) => setForm((p) => ({ ...p, target: e.target.value }))}
                    placeholder="Target program"
                  />
                </div>
                <div className="space-y-2">
                  <Label>Status publikasi</Label>
                  <CmsPublishTabs
                    published={form.isPublished ?? false}
                    onChange={(v) => setForm((p) => ({ ...p, isPublished: v }))}
                  />
                </div>
                <div className="space-y-2">
                  <Label>Rasional / Deskripsi</Label>
                  <Textarea
                    rows={5}
                    value={form.rationale ?? form.description ?? ''}
                    onChange={(e) => setForm((p) => ({ ...p, rationale: e.target.value }))}
                  />
                </div>
                <div className="flex flex-col-reverse gap-3 sm:flex-row sm:justify-end">
                  <Button
                    type="button"
                    variant="outline"
                    className="min-h-11"
                    onClick={() => setPageTab('list')}
                  >
                    Kembali ke daftar
                  </Button>
                  {form.id ? (
                    <Button variant="ghost" type="button" className="min-h-11" onClick={resetForm}>
                      Reset
                    </Button>
                  ) : null}
                  <Button type="submit" className="min-h-11">
                    {form.id ? 'Simpan' : 'Tambah program'}
                  </Button>
                </div>
              </form>
            </AdminCard>
          </CmsEditorLayout>
        </AdminContentTransition>
      ) : (
        <AdminContentTransition contentKey="list-programs">
          <AdminCard title="Daftar program" description="Semua program kerja di CMS.">
            <CmsListToolbar
              count={programs.length}
              countLabel="program"
              onCreate={() => {
                resetForm();
                setDateStart('');
                setDateEnd('');
                setPageTab('form');
              }}
            />
            <ul className="space-y-4 md:hidden" aria-label="Daftar program">
              {programs.map((p) => (
                <li key={p.id} className="rounded-2xl border border-border p-4 border-border">
                  <p className="font-bold text-foreground">{p.title}</p>
                  <p className="text-sm text-muted-foreground">{p.date_range ?? 'ΓÇö'}</p>
                  <Badge className="mt-2" variant={p.is_published ? 'success' : 'secondary'}>
                    {p.is_published ? 'Publik' : 'Draft'}
                  </Badge>
                  <div className="mt-3 flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      className="min-h-11 flex-1"
                      type="button"
                      onClick={() => {
                        setForm({
                          id: p.id,
                          title: p.title,
                          description: p.description ?? '',
                          isPublished: p.is_published,
                          division: p.division ?? '',
                          fundingSource: p.funding_source ?? '',
                          location: p.location ?? '',
                          target: p.target ?? '',
                          rationale: p.rationale ?? p.description ?? '',
                        });
                        resetDatesFromRange(p.date_range ?? '');
                        setPageTab('form');
                      }}
                    >
                      Edit
                    </Button>
                    <Button
                      variant="destructive"
                      size="sm"
                      className="min-h-11"
                      type="button"
                      onClick={() => openDelete(p.id)}
                    >
                      Hapus
                    </Button>
                  </div>
                </li>
              ))}
            </ul>
            <div className="hidden overflow-x-auto md:block">
              <Table className="min-w-[640px]">
                <TableHeader>
                  <TableRow>
                    <TableHead>Judul</TableHead>
                    <TableHead>Tanggal</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Aksi</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {programs.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={4} className="h-20 text-center text-muted-foreground">
                        Belum ada program.
                      </TableCell>
                    </TableRow>
                  ) : (
                    programs.map((p) => (
                      <TableRow key={p.id}>
                        <TableCell className="font-medium">{p.title}</TableCell>
                        <TableCell>{p.date_range ?? '-'}</TableCell>
                        <TableCell>
                          <Badge variant={p.is_published ? 'success' : 'secondary'}>
                            {p.is_published ? 'Publik' : 'Draft'}
                          </Badge>
                        </TableCell>
                        <TableCell className="space-x-2 text-right">
                          <Button
                            variant="outline"
                            size="sm"
                            className="min-h-9"
                            type="button"
                            onClick={() => {
                              setForm({
                                id: p.id,
                                title: p.title,
                                description: p.description ?? '',
                                isPublished: p.is_published,
                                division: p.division ?? '',
                                fundingSource: p.funding_source ?? '',
                                location: p.location ?? '',
                                target: p.target ?? '',
                                rationale: p.rationale ?? p.description ?? '',
                              });
                              resetDatesFromRange(p.date_range ?? '');
                              setPageTab('form');
                            }}
                          >
                            Edit
                          </Button>
                          <Button
                            variant="destructive"
                            size="sm"
                            className="min-h-9"
                            type="button"
                            onClick={() => openDelete(p.id)}
                          >
                            Hapus
                          </Button>
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </div>
          </AdminCard>
        </AdminContentTransition>
      )}

      <ConfirmModal
        isOpen={isDeleteOpen}
        onClose={() => setIsDeleteOpen(false)}
        onConfirm={confirmDelete}
        title="Konfirmasi Hapus"
        description={deleteDescription}
        confirmText="Ya, Hapus"
        cancelText="Batal"
        variant="danger"
      />
    </AdminPageShell>
  );
}

import React, { useMemo, useState } from 'react';
import useSWR from 'swr';
import api from '@/services/api';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { ConfirmModal } from '@/components/ConfirmModal';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import type { PublicRecruitment } from '@/types/publicSite';
import { getErrorMessage } from '@/lib/http/errorMessage';
import { prepareImageForUpload } from '@/lib/media/imageUpload';
import AdminPageShell from '@/components/AdminPageShell';
import AdminCard from '@/components/AdminCard';
import PublicSiteRecruitmentPreview from '@/components/publicSiteAdmin/PublicSiteRecruitmentPreview';
import { FileText } from 'lucide-react';
import { CmsTabNav, type CmsTabItem } from '@/components/ui/CmsTabNav';
import { CmsPublishTabs } from '@/components/ui/CmsPublishTabs';
import { CmsEditorLayout } from '@/components/cms/CmsEditorLayout';
import { CmsListToolbar } from '@/components/cms/CmsListToolbar';
import { AdminContentTransition } from '@/components/admin/AdminContentTransition';

type PageTab = 'form' | 'list';
type FormTab = 'info' | 'team';

const PAGE_TABS: readonly CmsTabItem<PageTab>[] = [
  { id: 'list', label: 'Daftar' },
  { id: 'form', label: 'Editor' },
];

const FORM_TABS: readonly CmsTabItem<FormTab>[] = [
  { id: 'info', label: 'Informasi' },
  { id: 'team', label: 'Panitia & Kontak' },
];

export default function PublicSiteRecruitments() {
  const fetcher = (url: string) => api.get(url).then((r) => r.data.data);
  const { data: recruitments = [], mutate } = useSWR<PublicRecruitment[]>(
    '/public-site/admin/recruitments',
    fetcher,
    { revalidateOnFocus: false }
  );

  const [pageTab, setPageTab] = useState<PageTab>('list');
  const [formTab, setFormTab] = useState<FormTab>('info');

  type CommitteeDraft = { name: string; role: string };
  type ContactDraft = { name: string; contact: string };
  const [form, setForm] = useState<{
    id?: string;
    title?: string;
    description?: string;
    formUrl?: string;
    posterImageUrl?: string;
    isPublished?: boolean;
    committee?: CommitteeDraft[];
    contacts?: ContactDraft[];
  }>({ committee: [], contacts: [] });
  const resetForm = () => setForm({ committee: [], contacts: [] });
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');
  const [uploadingPoster, setUploadingPoster] = useState(false);

  const resetDatesFromRange = (range: string) => {
    const raw = String(range ?? '').trim();
    if (!raw) {
      setDateStart('');
      setDateEnd('');
      return;
    }
    const parts = raw.split(' - ');
    if (parts.length >= 2) {
      setDateStart(parts[0] || '');
      setDateEnd(parts.slice(1).join(' - ') || '');
      return;
    }
    setDateStart(raw);
    setDateEnd('');
  };

  const dateRangePreview =
    dateStart && dateEnd ? `${dateStart} - ${dateEnd}` : dateStart || dateEnd || '';

  const uploadImage = async (file: File) => {
    const prepared = await prepareImageForUpload(file, {
      maxBytes: 4 * 1024 * 1024,
      maxWidth: 1600,
      quality: 0.82,
    });
    const formData = new FormData();
    formData.append('file', prepared);
    const res = await api.post('/public-site/admin/upload', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
    });
    return res.data.data.url as string;
  };

  const validatePublish = (): string | null => {
    if (!form.isPublished) return null;
    if (!dateStart.trim() && !dateEnd.trim()) {
      return 'Isi periode pendaftaran (tanggal mulai & selesai) sebelum mempublikasikan.';
    }
    const url = String(form.formUrl ?? '').trim();
    if (!url || !/^https:\/\/.+/i.test(url)) {
      return 'Link form pendaftaran (https://) wajib diisi sebelum mempublikasikan.';
    }
    return null;
  };

  const upsert = async (e: React.FormEvent) => {
    e.preventDefault();
    const publishErr = validatePublish();
    if (publishErr) {
      toast.error(publishErr);
      return;
    }
    try {
      const dateRange =
        dateStart && dateEnd ? `${dateStart} - ${dateEnd}` : dateStart || dateEnd || undefined;
      const committee = (form.committee ?? []).map((x, idx) => ({
        name: x.name,
        role: x.role,
        sortOrder: idx,
      }));
      const contacts = (form.contacts ?? []).map((x, idx) => ({
        name: x.name,
        contact: x.contact,
        sortOrder: idx,
      }));
      if (form.id) {
        await api.put(`/public-site/admin/recruitments/${form.id}`, {
          title: form.title,
          dateRange,
          description: form.description,
          formUrl: form.formUrl,
          posterImageUrl: form.posterImageUrl,
          isPublished: form.isPublished ?? false,
          committee,
          contacts,
        });
        toast.success('Open recruitment diperbarui');
      } else {
        await api.post('/public-site/admin/recruitments', {
          title: form.title,
          dateRange,
          description: form.description,
          formUrl: form.formUrl,
          posterImageUrl: form.posterImageUrl,
          isPublished: form.isPublished ?? false,
          committee,
          contacts,
        });
        toast.success('Open recruitment ditambahkan');
      }
      resetForm();
      setDateStart('');
      setDateEnd('');
      setPageTab('list');
      mutate();
    } catch (err: any) {
      toast.error(getErrorMessage(err, 'Gagal menyimpan'));
    }
  };

  const [isDeleteOpen, setIsDeleteOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const deleteDescription = useMemo(() => 'Yakin ingin menghapus open recruitment ini?', []);

  const openDelete = (id: string) => {
    setDeleteId(id);
    setIsDeleteOpen(true);
  };

  const confirmDelete = async () => {
    if (!deleteId) return;
    try {
      await api.delete(`/public-site/admin/recruitments/${deleteId}`);
      toast.success('Berhasil dihapus');
      setIsDeleteOpen(false);
      setDeleteId(null);
      mutate();
    } catch (e: any) {
      toast.error(getErrorMessage(e, 'Gagal menghapus'));
    }
  };

  const loadForEdit = (r: PublicRecruitment) => {
    setForm({
      id: r.id,
      title: r.title,
      description: r.description ?? '',
      formUrl: r.form_url ?? '',
      posterImageUrl: r.poster_image_url ?? '',
      isPublished: r.is_published,
      committee: (r.committee ?? []).map((x) => ({ name: x.name, role: x.role })),
      contacts: (r.contacts ?? []).map((x) => ({ name: x.name, contact: x.contact })),
    });
    resetDatesFromRange(r.date_range ?? '');
    setFormTab('info');
    setPageTab('form');
  };

  return (
    <AdminPageShell
      title="Open Recruitment"
      description="Kelola informasi open recruitment yang tampil di halaman publik."
      variant="plain"
      icon={<FileText size={22} />}
    >
      <CmsTabNav<PageTab>
        tabs={PAGE_TABS}
        value={pageTab}
        onChange={setPageTab}
        ariaLabel="Mode recruitment"
      />

      {pageTab === 'form' ? (
        <AdminContentTransition contentKey={`form-${form.id ?? 'new'}-${formTab}`}>
          <CmsEditorLayout
            preview={
              <PublicSiteRecruitmentPreview
                title={form.title}
                dateRange={dateRangePreview}
                description={form.description}
                formUrl={form.formUrl}
                posterImageUrl={form.posterImageUrl}
                isPublished={form.isPublished}
                committeeCount={form.committee?.length ?? 0}
                contactsCount={form.contacts?.length ?? 0}
              />
            }
          >
            <AdminCard
              title={form.id ? 'Ubah recruitment' : 'Recruitment baru'}
              description="Informasi umum dan data panitia."
            >
              <form onSubmit={upsert} className="space-y-5">
                <CmsTabNav<FormTab>
                  tabs={FORM_TABS}
                  value={formTab}
                  onChange={setFormTab}
                  ariaLabel="Bagian form recruitment"
                />

                <div className={formTab === 'info' ? 'grid gap-4 md:grid-cols-2' : 'hidden'}>
                  <div className="space-y-2 md:col-span-2">
                    <Label htmlFor="recruitment-title">Judul</Label>
                    <Input
                      id="recruitment-title"
                      value={form.title ?? ''}
                      onChange={(e) => setForm((p) => ({ ...p, title: e.target.value }))}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="recruitment-date-start">Tanggal Mulai</Label>
                    <Input
                      id="recruitment-date-start"
                      type="date"
                      value={dateStart}
                      onChange={(e) => setDateStart(e.target.value)}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="recruitment-date-end">Tanggal Selesai</Label>
                    <Input
                      id="recruitment-date-end"
                      type="date"
                      value={dateEnd}
                      onChange={(e) => setDateEnd(e.target.value)}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="recruitment-form-url">Link Form</Label>
                    <Input
                      id="recruitment-form-url"
                      value={form.formUrl ?? ''}
                      onChange={(e) => setForm((p) => ({ ...p, formUrl: e.target.value }))}
                    />
                  </div>
                  <div className="space-y-2 md:col-span-2">
                    <Label>Status publikasi</Label>
                    <CmsPublishTabs
                      published={form.isPublished ?? false}
                      onChange={(v) => setForm((p) => ({ ...p, isPublished: v }))}
                    />
                  </div>
                  <div className="space-y-2 md:col-span-2">
                    <Label htmlFor="recruitment-description">Deskripsi</Label>
                    <Textarea
                      id="recruitment-description"
                      value={form.description ?? ''}
                      onChange={(e) => setForm((p) => ({ ...p, description: e.target.value }))}
                    />
                  </div>
                  <div className="space-y-2 md:col-span-2">
                    <Label>Poster</Label>
                    <div className="grid gap-3 md:grid-cols-[1fr_180px]">
                      <div className="space-y-2">
                        <Input
                          id="recruitment-poster"
                          type="file"
                          accept="image/*"
                          className="hidden"
                          disabled={uploadingPoster}
                          onChange={async (e) => {
                            const file = e.target.files?.[0];
                            if (!file) return;
                            setUploadingPoster(true);
                            try {
                              const url = await uploadImage(file);
                              setForm((p) => ({ ...p, posterImageUrl: url }));
                              toast.success('Upload poster berhasil');
                            } catch (err: any) {
                              toast.error(getErrorMessage(err, 'Gagal upload poster'));
                            } finally {
                              setUploadingPoster(false);
                              e.currentTarget.value = '';
                            }
                          }}
                        />
                        <div className="flex flex-wrap gap-2">
                          <Button
                            asChild
                            variant="outline"
                            disabled={uploadingPoster}
                            className="min-h-11"
                          >
                            <Label htmlFor="recruitment-poster" className="cursor-pointer">
                              {uploadingPoster
                                ? 'Uploading...'
                                : form.posterImageUrl
                                  ? 'Ganti Poster'
                                  : 'Upload Poster'}
                            </Label>
                          </Button>
                          {form.posterImageUrl ? (
                            <Button
                              type="button"
                              variant="ghost"
                              className="min-h-11"
                              onClick={() => setForm((p) => ({ ...p, posterImageUrl: '' }))}
                              disabled={uploadingPoster}
                            >
                              Hapus
                            </Button>
                          ) : null}
                          <Button
                            type="button"
                            variant="ghost"
                            size="sm"
                            onClick={() => {
                              const el = document.getElementById('recruitment-poster-url-toggle');
                              el?.classList.toggle('hidden');
                            }}
                          >
                            Atau masukkan URL secara manual
                          </Button>
                        </div>
                        <div id="recruitment-poster-url-toggle" className="hidden space-y-2">
                          <Label
                            htmlFor="recruitment-poster-url"
                            className="text-xs text-muted-foreground"
                          >
                            Poster Image URL
                          </Label>
                          <Input
                            id="recruitment-poster-url"
                            value={form.posterImageUrl ?? ''}
                            onChange={(e) =>
                              setForm((p) => ({ ...p, posterImageUrl: e.target.value }))
                            }
                            placeholder="https://..."
                          />
                        </div>
                      </div>
                      <div className="overflow-hidden rounded-xl border border-border">
                        <div className="aspect-[4/5] w-full bg-slate-100 bg-background">
                          {form.posterImageUrl ? (
                            <img
                              src={form.posterImageUrl}
                              alt="Poster"
                              className="h-full w-full object-cover"
                            />
                          ) : (
                            <div className="flex h-full items-center justify-center text-xs text-muted-foreground">
                              Belum ada poster
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                </div>

                <div className={formTab === 'team' ? 'space-y-6' : 'hidden'}>
                  <div className="space-y-3">
                    <div className="flex flex-wrap items-center justify-between gap-3">
                      <Label>Panitia</Label>
                      <Button
                        type="button"
                        variant="outline"
                        className="min-h-11"
                        onClick={() =>
                          setForm((p) => ({
                            ...p,
                            committee: [...(p.committee ?? []), { name: '', role: '' }],
                          }))
                        }
                      >
                        Tambah Panitia
                      </Button>
                    </div>
                    {(form.committee ?? []).length === 0 ? (
                      <div className="rounded-xl border border-dashed rounded-xl border border-dashed border-border bg-muted/30 p-4 text-sm text-muted-foreground">
                        Belum ada panitia.
                      </div>
                    ) : (
                      <div className="space-y-3">
                        {(form.committee ?? []).map((c, idx) => (
                          <div key={idx} className="grid gap-3 md:grid-cols-2">
                            <Input
                              value={c.name}
                              onChange={(e) =>
                                setForm((p) => ({
                                  ...p,
                                  committee: (p.committee ?? []).map((x, i) =>
                                    i === idx ? { ...x, name: e.target.value } : x
                                  ),
                                }))
                              }
                              placeholder="Nama"
                            />
                            <div className="flex gap-2">
                              <Input
                                value={c.role}
                                onChange={(e) =>
                                  setForm((p) => ({
                                    ...p,
                                    committee: (p.committee ?? []).map((x, i) =>
                                      i === idx ? { ...x, role: e.target.value } : x
                                    ),
                                  }))
                                }
                                placeholder="Jabatan"
                              />
                              <Button
                                type="button"
                                variant="outline"
                                className="min-h-11 shrink-0"
                                onClick={() =>
                                  setForm((p) => ({
                                    ...p,
                                    committee: (p.committee ?? []).filter((_, i) => i !== idx),
                                  }))
                                }
                              >
                                Hapus
                              </Button>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  <div className="space-y-3">
                    <div className="flex flex-wrap items-center justify-between gap-3">
                      <Label>Contact Person</Label>
                      <Button
                        type="button"
                        variant="outline"
                        className="min-h-11"
                        onClick={() =>
                          setForm((p) => ({
                            ...p,
                            contacts: [...(p.contacts ?? []), { name: '', contact: '' }],
                          }))
                        }
                      >
                        Tambah Kontak
                      </Button>
                    </div>
                    {(form.contacts ?? []).length === 0 ? (
                      <div className="rounded-xl border border-dashed rounded-xl border border-dashed border-border bg-muted/30 p-4 text-sm text-muted-foreground">
                        Belum ada kontak.
                      </div>
                    ) : (
                      <div className="space-y-3">
                        {(form.contacts ?? []).map((c, idx) => (
                          <div key={idx} className="grid gap-3 md:grid-cols-2">
                            <Input
                              value={c.name}
                              onChange={(e) =>
                                setForm((p) => ({
                                  ...p,
                                  contacts: (p.contacts ?? []).map((x, i) =>
                                    i === idx ? { ...x, name: e.target.value } : x
                                  ),
                                }))
                              }
                              placeholder="Nama"
                            />
                            <div className="flex gap-2">
                              <Input
                                value={c.contact}
                                onChange={(e) =>
                                  setForm((p) => ({
                                    ...p,
                                    contacts: (p.contacts ?? []).map((x, i) =>
                                      i === idx ? { ...x, contact: e.target.value } : x
                                    ),
                                  }))
                                }
                                placeholder="Telepon / link"
                              />
                              <Button
                                type="button"
                                variant="outline"
                                className="min-h-11 shrink-0"
                                onClick={() =>
                                  setForm((p) => ({
                                    ...p,
                                    contacts: (p.contacts ?? []).filter((_, i) => i !== idx),
                                  }))
                                }
                              >
                                Hapus
                              </Button>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                <div className="flex flex-col-reverse gap-3 sm:flex-row sm:justify-end">
                  <Button
                    type="button"
                    variant="outline"
                    className="min-h-11"
                    onClick={() => setPageTab('list')}
                  >
                    Kembali ke daftar
                  </Button>
                  {form.id ? (
                    <Button variant="ghost" type="button" className="min-h-11" onClick={resetForm}>
                      Reset
                    </Button>
                  ) : null}
                  <Button type="submit" className="min-h-11">
                    {form.id ? 'Simpan' : 'Tambah recruitment'}
                  </Button>
                </div>
              </form>
            </AdminCard>
          </CmsEditorLayout>
        </AdminContentTransition>
      ) : (
        <AdminContentTransition contentKey="list-recruitments">
          <AdminCard
            title="Daftar recruitment"
            description="Open recruitment yang tampil di situs publik."
          >
            <CmsListToolbar
              count={recruitments.length}
              countLabel="recruitment"
              onCreate={() => {
                resetForm();
                setDateStart('');
                setDateEnd('');
                setFormTab('info');
                setPageTab('form');
              }}
            />
            <ul className="space-y-4 md:hidden" aria-label="Daftar recruitment">
              {recruitments.length === 0 ? (
                <li className="py-8 text-center text-sm text-muted-foreground">
                  Belum ada recruitment.
                </li>
              ) : null}
              {recruitments.map((r) => (
                <li key={r.id} className="rounded-2xl border border-border p-4 border-border">
                  <p className="font-bold text-foreground">{r.title}</p>
                  <p className="text-sm text-muted-foreground">{r.date_range ?? 'ΓÇö'}</p>
                  <Badge className="mt-2" variant={r.is_published ? 'success' : 'secondary'}>
                    {r.is_published ? 'Publik' : 'Draft'}
                  </Badge>
                  <div className="mt-3 flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      className="min-h-11 flex-1"
                      type="button"
                      onClick={() => loadForEdit(r)}
                    >
                      Edit
                    </Button>
                    <Button
                      variant="destructive"
                      size="sm"
                      className="min-h-11"
                      type="button"
                      onClick={() => openDelete(r.id)}
                    >
                      Hapus
                    </Button>
                  </div>
                </li>
              ))}
            </ul>
            <div className="hidden overflow-x-auto md:block">
              <Table className="min-w-[640px]">
                <TableHeader>
                  <TableRow>
                    <TableHead>Judul</TableHead>
                    <TableHead>Tanggal</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Aksi</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {recruitments.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={4} className="py-10 text-center text-muted-foreground">
                        Belum ada recruitment.
                      </TableCell>
                    </TableRow>
                  ) : null}
                  {recruitments.map((r) => (
                    <TableRow key={r.id}>
                      <TableCell className="font-medium">{r.title}</TableCell>
                      <TableCell>{r.date_range ?? '-'}</TableCell>
                      <TableCell>
                        <Badge variant={r.is_published ? 'success' : 'secondary'}>
                          {r.is_published ? 'Publik' : 'Draft'}
                        </Badge>
                      </TableCell>
                      <TableCell className="space-x-2 text-right">
                        <Button
                          variant="outline"
                          size="sm"
                          type="button"
                          onClick={() => loadForEdit(r)}
                        >
                          Edit
                        </Button>
                        <Button
                          variant="destructive"
                          size="sm"
                          type="button"
                          onClick={() => openDelete(r.id)}
                        >
                          Hapus
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </AdminCard>
        </AdminContentTransition>
      )}

      <ConfirmModal
        isOpen={isDeleteOpen}
        onClose={() => setIsDeleteOpen(false)}
        onConfirm={confirmDelete}
        title="Konfirmasi Hapus"
        description={deleteDescription}
        confirmText="Ya, Hapus"
        cancelText="Batal"
        variant="danger"
      />
    </AdminPageShell>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import useSWR from 'swr';
import api from '@/services/api';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Checkbox } from '@/components/ui/checkbox';
import type { PublicStructureGroup } from '@/types/publicSite';
import { getErrorMessage } from '@/lib/http/errorMessage';
import { prepareImageForUpload } from '@/lib/media/imageUpload';
import { ConfirmModal } from '@/components/ConfirmModal';
import AdminPageShell from '@/components/AdminPageShell';
import AdminCard from '@/components/AdminCard';
import { AdminCardActions } from '@/components/admin/AdminCardActions';
import PublicSiteStructurePreview from '@/components/publicSiteAdmin/PublicSiteStructurePreview';
import { CmsEditorLayout } from '@/components/cms/CmsEditorLayout';
import { Layers } from 'lucide-react';

export default function PublicSiteStructure() {
  const formId = React.useId();
  const fetcher = (url: string) => api.get(url).then((r) => r.data.data);
  const { data: adminData, mutate } = useSWR<{
    cabinets: any[];
    activeCabinetId: string;
    activeGroups: PublicStructureGroup[];
  }>('/public-site/admin/structure', fetcher, { revalidateOnFocus: false });

  type MemberDraft = { name: string; role: string; photoUrl: string; isSpotlight: boolean };
  type GroupDraft = { title: string; isCore: boolean; people: MemberDraft[] };
  const [groups, setGroups] = useState<GroupDraft[]>([]);
  const [cabinetName, setCabinetName] = useState('');
  const [cabinetPeriod, setCabinetPeriod] = useState('');
  const [viewingCabinetId, setViewingCabinetId] = useState<string | null>(null);
  const [dirty, setDirty] = useState(false);
  const dirtyRef = useRef(false);
  const markDirty = () => {
    if (dirtyRef.current) return;
    dirtyRef.current = true;
    setDirty(true);
  };
  const setGroupsDirty = (updater: (prev: GroupDraft[]) => GroupDraft[]) => {
    markDirty();
    setGroups(updater);
  };

  const currentYear = new Date().getFullYear();

  useEffect(() => {
    if (dirtyRef.current) return;
    if (!adminData) return;

    const cabinets = adminData.cabinets || [];
    const activeCabinet = cabinets.find((c: any) => c.is_active) || cabinets[0] || null;
    const currentViewCabinet = viewingCabinetId
      ? cabinets.find((c: any) => c.id === viewingCabinetId)
      : activeCabinet;

    if (currentViewCabinet) {
      const mapped: GroupDraft[] = (currentViewCabinet.groups ?? []).map((g: any) => ({
        title: g.title ?? '',
        isCore: Boolean(g.is_core ?? false),
        people: (g.members ?? []).map((m: any) => ({
          name: m.name ?? '',
          role: m.role ?? '',
          photoUrl: m.photo_url ?? '',
          isSpotlight: Boolean(m.is_spotlight ?? false),
        })),
      }));
      setGroups(mapped);
      setCabinetName(currentViewCabinet.name);
      setCabinetPeriod(currentViewCabinet.period);
    } else {
      // Default for new cabinet
      setCabinetName('');
      setCabinetPeriod(`${currentYear}/${currentYear + 1}`);
      setGroups([]);
    }
  }, [adminData, viewingCabinetId]);

  const [saving, setSaving] = useState(false);
  const [uploadingKey, setUploadingKey] = useState<string | null>(null);
  const [confirm, setConfirm] = useState<{
    open: boolean;
    title: string;
    description: string;
    confirmText?: string;
    variant?: 'danger' | 'warning' | 'primary';
    onConfirm?: () => void;
  }>({ open: false, title: '', description: '' });

  const uploadImage = async (file: File) => {
    const prepared = await prepareImageForUpload(file, {
      maxBytes: 4 * 1024 * 1024,
      maxWidth: 1200,
      quality: 0.82,
    });
    const form = new FormData();
    form.append('file', prepared);
    const res = await api.post('/public-site/admin/upload', form, {
      headers: { 'Content-Type': 'multipart/form-data' },
    });
    return res.data.data.url as string;
  };

  const onPickMemberPhoto = async (gi: number, pi: number, file: File) => {
    const key = `${gi}:${pi}`;
    setUploadingKey(key);
    try {
      const url = await uploadImage(file);
      setGroupsDirty((prev) =>
        prev.map((g, gidx) =>
          gidx === gi
            ? {
                ...g,
                people: g.people.map((p, pidx) => (pidx === pi ? { ...p, photoUrl: url } : p)),
              }
            : g
        )
      );
      toast.success('Upload foto anggota berhasil');
    } catch (e: any) {
      toast.error(getErrorMessage(e, 'Gagal upload foto'));
    } finally {
      setUploadingKey(null);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      const payload = groups.map((g, gi) => ({
        title: g.title,
        isCore: g.isCore,
        sortOrder: gi,
        people: (g.people ?? []).map((p, pi) => ({
          name: p.name,
          role: p.role,
          photoUrl: p.photoUrl,
          isSpotlight: p.isSpotlight,
          sortOrder: pi,
        })),
      }));
      await api.put('/public-site/admin/structure', { cabinetName, cabinetPeriod, data: payload });
      toast.success('Struktur organisasi tersimpan');
      setViewingCabinetId(null); // Reset to new active cabinet after saving
      dirtyRef.current = false;
      setDirty(false);
      mutate();
    } catch (e: any) {
      toast.error(getErrorMessage(e, 'Gagal menyimpan'));
    } finally {
      setSaving(false);
    }
  };

  const handleSetActive = async (id: string) => {
    try {
      await api.put(`/public-site/admin/structure/active/${id}`);
      toast.success('Kabinet aktif diubah');
      mutate();
    } catch (e: any) {
      toast.error(getErrorMessage(e, 'Gagal mengubah kabinet aktif'));
    }
  };

  const handleReset = () => {
    if (!adminData) return;
    const cabinets = adminData.cabinets || [];
    const activeCabinet = cabinets.find((c: any) => c.is_active) || cabinets[0] || null;
    const currentViewCabinet = viewingCabinetId
      ? cabinets.find((c: any) => c.id === viewingCabinetId)
      : activeCabinet;

    if (currentViewCabinet) {
      const mapped: GroupDraft[] = (currentViewCabinet.groups ?? []).map((g: any) => ({
        title: g.title ?? '',
        isCore: Boolean(g.is_core ?? false),
        people: (g.members ?? []).map((m: any) => ({
          name: m.name ?? '',
          role: m.role ?? '',
          photoUrl: m.photo_url ?? '',
          isSpotlight: Boolean(m.is_spotlight ?? false),
        })),
      }));
      setGroups(mapped);
      setCabinetName(currentViewCabinet.name);
      setCabinetPeriod(currentViewCabinet.period);
    }
    dirtyRef.current = false;
    setDirty(false);
  };

  return (
    <AdminPageShell
      title="Struktur Organisasi"
      description="Tambahkan grup dan anggota tanpa perlu JSON."
      variant="plain"
      icon={<Layers size={22} />}
    >
      <ConfirmModal
        isOpen={confirm.open}
        onClose={() => setConfirm((prev) => ({ ...prev, open: false }))}
        onConfirm={() => {
          confirm.onConfirm?.();
          setConfirm((prev) => ({ ...prev, open: false }));
        }}
        title={confirm.title}
        description={confirm.description}
        confirmText={confirm.confirmText}
        cancelText="Batal"
        variant={confirm.variant}
      />

      <CmsEditorLayout preview={<PublicSiteStructurePreview groups={groups} />}>
        <AdminCard
          title="Grup Struktur"
          description="Atur grup, tandai divisi inti, lalu tentukan spotlight per anggota (maks 1 anggota per grup). Tips: buat grup bernama ΓÇ£Dosen PembimbingΓÇ¥ untuk tampil di atas INTI; untuk foto Visi/Misi di beranda, isi jabatan mengandung ΓÇ£KetuaΓÇ¥ dan ΓÇ£WakilΓÇ¥."
          actions={
            <Button
              type="button"
              variant="outline"
              className="min-h-11 w-full sm:w-auto"
              onClick={() =>
                setGroupsDirty((prev) => [
                  ...prev,
                  {
                    title: '',
                    isCore: false,
                    people: [{ name: '', role: '', photoUrl: '', isSpotlight: false }],
                  },
                ])
              }
            >
              Tambah Grup
            </Button>
          }
        >
          {/* Cabinet Info */}
          <div className="mb-6 flex flex-col gap-3">
            <div className="flex flex-col gap-2">
              <Label htmlFor={`${formId}-cabinet-name`}>Nama Kabinet</Label>
              <Input
                id={`${formId}-cabinet-name`}
                value={cabinetName}
                onChange={(e) => {
                  markDirty();
                  setCabinetName(e.target.value);
                }}
                placeholder="Contoh: Kabinet Harmoni"
              />
            </div>
            <div className="flex flex-col gap-2">
              <Label htmlFor={`${formId}-cabinet-period`}>Periode</Label>
              <Input
                id={`${formId}-cabinet-period`}
                value={cabinetPeriod}
                onChange={(e) => {
                  markDirty();
                  setCabinetPeriod(e.target.value);
                }}
                placeholder={`Contoh: ${currentYear}/${currentYear + 1}`}
              />
            </div>
          </div>

          {/* Cabinet Selection */}
          {adminData?.cabinets && adminData.cabinets.length > 0 && (
            <div className="mb-6 border-b border-border pb-6">
              <Label className="mb-2 block">Lihat Kabinet Sebelumnya</Label>
              <div className="flex flex-wrap gap-2">
                {adminData.cabinets.map((cabinet: any) => (
                  <div key={cabinet.id} className="flex items-center gap-2">
                    <Button
                      type="button"
                      variant={
                        viewingCabinetId === cabinet.id || (!viewingCabinetId && cabinet.is_active)
                          ? 'default'
                          : 'outline'
                      }
                      size="sm"
                      onClick={() =>
                        setViewingCabinetId(viewingCabinetId === cabinet.id ? null : cabinet.id)
                      }
                    >
                      {cabinet.name} ({cabinet.period}){cabinet.is_active && ' (Aktif)'}
                    </Button>
                    {!cabinet.is_active && (
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => handleSetActive(cabinet.id)}
                      >
                        Jadikan Aktif
                      </Button>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}

          {groups.length === 0 ? (
            <div className="rounded-2xl border border-dashed border-border bg-muted/30 p-6 text-sm text-muted-foreground">
              Belum ada struktur. Klik ΓÇ£Tambah GrupΓÇ¥ untuk mulai.
            </div>
          ) : (
            <div className="space-y-5">
              {groups.map((g, gi) => (
                <div key={gi} className="rounded-2xl border border-border bg-muted/20 p-4">
                  <div className="flex flex-col gap-3 md:flex-row md:items-end md:justify-between">
                    <div className="w-full space-y-2">
                      <Label htmlFor={`${formId}-group-title-${gi}`}>Nama Grup</Label>
                      <Input
                        id={`${formId}-group-title-${gi}`}
                        value={g.title}
                        onChange={(e) =>
                          setGroupsDirty((prev) =>
                            prev.map((x, idx) => (idx === gi ? { ...x, title: e.target.value } : x))
                          )
                        }
                        placeholder="Contoh: INTI"
                      />
                      <div className="flex items-center gap-2 text-sm text-foreground">
                        <Checkbox
                          id={`${formId}-group-core-${gi}`}
                          checked={Boolean(g.isCore)}
                          onCheckedChange={(checked) =>
                            setGroupsDirty((prev) =>
                              prev.map((x, idx) =>
                                idx === gi ? { ...x, isCore: Boolean(checked) } : x
                              )
                            )
                          }
                        />
                        <Label htmlFor={`${formId}-group-core-${gi}`}>Divisi inti</Label>
                      </div>
                    </div>
                    <div className="flex w-full flex-col gap-2 sm:flex-row sm:items-center sm:justify-end md:w-auto">
                      <Button
                        type="button"
                        variant="outline"
                        className="w-full sm:w-auto"
                        onClick={() =>
                          setGroupsDirty((prev) =>
                            prev.map((x, idx) =>
                              idx === gi
                                ? {
                                    ...x,
                                    people: [
                                      ...x.people,
                                      { name: '', role: '', photoUrl: '', isSpotlight: false },
                                    ],
                                  }
                                : x
                            )
                          )
                        }
                      >
                        Tambah Anggota
                      </Button>
                      <Button
                        type="button"
                        variant="destructive"
                        className="w-full sm:w-auto"
                        onClick={() =>
                          setConfirm({
                            open: true,
                            title: 'Hapus grup ini?',
                            description: 'Semua anggota di dalam grup ini juga akan ikut terhapus.',
                            confirmText: 'Hapus Grup',
                            variant: 'danger',
                            onConfirm: () =>
                              setGroupsDirty((prev) => prev.filter((_, idx) => idx !== gi)),
                          })
                        }
                      >
                        Hapus Grup
                      </Button>
                    </div>
                  </div>

                  <div className="mt-4 space-y-3">
                    <div className="hidden grid gap-3 md:grid-cols-4 md:grid">
                      <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                        Foto
                      </div>
                      <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                        Nama
                      </div>
                      <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                        Jabatan
                      </div>
                      <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                        Spotlight
                      </div>
                    </div>
                    {g.people.map((p, pi) => (
                      <div
                        key={pi}
                        className="grid gap-3 rounded-2xl border border-border/70 bg-muted/25 p-3 md:grid-cols-4 md:border-0 md:bg-transparent md:p-0"
                      >
                        <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
                          <div className="size-12 overflow-hidden rounded-full border border-border bg-muted">
                            {p.photoUrl ? (
                              <img
                                src={p.photoUrl}
                                alt="Foto"
                                className="h-full w-full object-cover"
                              />
                            ) : null}
                          </div>
                          <Input
                            id={`structure-photo-${gi}-${pi}`}
                            type="file"
                            accept="image/*"
                            className="hidden"
                            disabled={saving || uploadingKey === `${gi}:${pi}`}
                            onChange={(e) => {
                              const file = e.currentTarget.files?.[0];
                              if (!file) return;
                              onPickMemberPhoto(gi, pi, file);
                              e.currentTarget.value = '';
                            }}
                          />
                          <div className="flex flex-1 flex-col gap-2 sm:flex-row sm:items-center">
                            <Button
                              asChild
                              variant="outline"
                              disabled={saving || uploadingKey === `${gi}:${pi}`}
                              className="w-full sm:w-auto"
                            >
                              <Label
                                htmlFor={`structure-photo-${gi}-${pi}`}
                                className="cursor-pointer"
                              >
                                {uploadingKey === `${gi}:${pi}`
                                  ? 'Uploading...'
                                  : p.photoUrl
                                    ? 'Ganti Foto'
                                    : 'Upload Foto'}
                              </Label>
                            </Button>
                            {p.photoUrl ? (
                              <Button
                                type="button"
                                variant="ghost"
                                className="w-full sm:w-auto"
                                disabled={saving || uploadingKey === `${gi}:${pi}`}
                                onClick={() =>
                                  setGroupsDirty((prev) =>
                                    prev.map((x, idx) =>
                                      idx === gi
                                        ? {
                                            ...x,
                                            people: x.people.map((pp, pidx) =>
                                              pidx === pi ? { ...pp, photoUrl: '' } : pp
                                            ),
                                          }
                                        : x
                                    )
                                  )
                                }
                              >
                                Hapus Foto
                              </Button>
                            ) : null}
                          </div>
                        </div>
                        <Label htmlFor={`${formId}-member-name-${gi}-${pi}`} className="sr-only">
                          Nama anggota {pi + 1} pada grup {g.title || gi + 1}
                        </Label>
                        <Input
                          id={`${formId}-member-name-${gi}-${pi}`}
                          value={p.name}
                          onChange={(e) =>
                            setGroupsDirty((prev) =>
                              prev.map((x, idx) =>
                                idx === gi
                                  ? {
                                      ...x,
                                      people: x.people.map((pp, pidx) =>
                                        pidx === pi ? { ...pp, name: e.target.value } : pp
                                      ),
                                    }
                                  : x
                              )
                            )
                          }
                          placeholder="Nama"
                        />
                        <div className="flex flex-col gap-2 sm:flex-row">
                          <Label htmlFor={`${formId}-member-role-${gi}-${pi}`} className="sr-only">
                            Jabatan anggota {pi + 1} pada grup {g.title || gi + 1}
                          </Label>
                          <Input
                            id={`${formId}-member-role-${gi}-${pi}`}
                            value={p.role}
                            onChange={(e) =>
                              setGroupsDirty((prev) =>
                                prev.map((x, idx) =>
                                  idx === gi
                                    ? {
                                        ...x,
                                        people: x.people.map((pp, pidx) =>
                                          pidx === pi ? { ...pp, role: e.target.value } : pp
                                        ),
                                      }
                                    : x
                                )
                              )
                            }
                            placeholder="Jabatan"
                          />
                          <Button
                            type="button"
                            variant="outline"
                            className="w-full sm:w-auto"
                            onClick={() =>
                              setConfirm({
                                open: true,
                                title: 'Hapus anggota ini?',
                                description: 'Tindakan ini tidak bisa dibatalkan.',
                                confirmText: 'Hapus',
                                variant: 'danger',
                                onConfirm: () =>
                                  setGroupsDirty((prev) =>
                                    prev.map((x, idx) =>
                                      idx === gi
                                        ? {
                                            ...x,
                                            people: x.people.filter((_, pidx) => pidx !== pi),
                                          }
                                        : x
                                    )
                                  ),
                              })
                            }
                          >
                            Hapus
                          </Button>
                        </div>
                        <div className="flex items-center justify-start gap-2 md:justify-center">
                          <Label
                            htmlFor={`${formId}-member-spotlight-${gi}-${pi}`}
                            className="text-sm font-medium text-foreground md:hidden"
                          >
                            Spotlight
                          </Label>
                          <Checkbox
                            id={`${formId}-member-spotlight-${gi}-${pi}`}
                            checked={Boolean(p.isSpotlight)}
                            onCheckedChange={(checked) => {
                              const next = Boolean(checked);
                              setGroupsDirty((prev) =>
                                prev.map((x, idx) =>
                                  idx === gi
                                    ? {
                                        ...x,
                                        people: x.people.map((pp, pidx) =>
                                          pidx === pi
                                            ? { ...pp, isSpotlight: next }
                                            : { ...pp, isSpotlight: next ? false : pp.isSpotlight }
                                        ),
                                      }
                                    : x
                                )
                              );
                            }}
                          />
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          )}

          <AdminCardActions>
            <Button
              variant="outline"
              type="button"
              onClick={() =>
                setConfirm({
                  open: true,
                  title: 'Reset perubahan?',
                  description:
                    'Semua perubahan yang belum disimpan akan dikembalikan ke data terakhir yang tersimpan.',
                  confirmText: 'Reset',
                  variant: 'primary',
                  onConfirm: handleReset,
                })
              }
              disabled={saving || !dirty}
              className="w-full sm:w-auto"
            >
              Reset
            </Button>
            <Button
              type="button"
              onClick={handleSave}
              disabled={saving || !dirty}
              className="min-h-11 w-full sm:w-auto"
            >
              Simpan
            </Button>
          </AdminCardActions>
        </AdminCard>
      </CmsEditorLayout>
    </AdminPageShell>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import PublicLayout from '@/components/PublicLayout';
import useSWR from 'swr';
import api from '@/services/api';
import type { PublicProfile, PublicStructureGroup } from '@/types/publicSite';
import { Skeleton } from '@/components/ui/skeleton';
import PublicPageHero from '@/components/PublicPageHero';
import PublicCoverImage from '@/components/PublicCoverImage';
import { AnimatePresence, m } from 'framer-motion';
import { useReducedMotion } from '@/lib/a11y/useReducedMotion';
import { fadeTransition } from '@/lib/perf/motionPresets';
import PublicEnter from '@/components/PublicEnter';
import PublicReveal from '@/components/PublicReveal';
import { useSwrPageState } from '@/hooks/useSwrPageState';
import { PublicPageError } from '@/components/public/PublicPageError';
import { PublicEmptyState } from '@/components/public/PublicEmptyState';
import PublicLoadingOverlay from '@/components/PublicLoadingOverlay';

export default function Fungsionaris() {
  const fetcher = (url: string) => api.get(url).then((r) => r.data);
  const structureSwr = useSWR<{ data: PublicStructureGroup[], cabinet: any, allCabinets: any[] }>('/public-site/structure', fetcher, { revalidateOnFocus: false });
  const { data: structureData, isInitialLoading: isLoading, isError, retry } = useSwrPageState(structureSwr);
  const [selectedCabinetId, setSelectedCabinetId] = useState<string | null>(null);
  
  const allCabinets = structureData?.allCabinets ?? [];
  const activeCabinet = structureData?.cabinet;
  const selectedCabinet = useMemo(() => {
    if (selectedCabinetId) {
      return allCabinets.find(c => c.id === selectedCabinetId);
    }
    return activeCabinet;
  }, [allCabinets, selectedCabinetId, activeCabinet]);
  
  const groups = selectedCabinet?.groups ?? [];
  const cabinet = selectedCabinet ?? null;
  const { data: profile } = useSWR<PublicProfile | null>('/public-site/profile', (url) => api.get(url).then(r => r.data.data), { revalidateOnFocus: false });
  const reducedMotion = useReducedMotion();

  const ordered = useMemo(
    () => groups.slice().sort((a: any, b: any) => (Number(a.sort_order ?? 999) || 999) - (Number(b.sort_order ?? 999) || 999)),
    [groups],
  );

  const isCoreByTitle = (title: string) => {
    const t = String(title ?? '').toLowerCase();
    return t.includes('inti') || t.includes('badan pengurus harian') || t === 'bph';
  };

  const isAdvisorByTitle = (title: string) => {
    const t = String(title ?? '').toLowerCase();
    return t.includes('dosen') || t.includes('pembimbing') || t.includes('pembina');
  };

  const advisorGroups = useMemo(() => ordered.filter((g: any) => isAdvisorByTitle(g.title)), [ordered]);
  const coreGroups = useMemo(
    () => ordered.filter((g: any) => !advisorGroups.some((x: any) => x.id === g.id) && (Boolean(g.is_core) || isCoreByTitle(g.title))),
    [ordered, advisorGroups],
  );
  const bidangGroups = useMemo(
    () => ordered.filter((g: any) => !advisorGroups.some((x: any) => x.id === g.id) && !coreGroups.some((x: any) => x.id === g.id)),
    [ordered, advisorGroups, coreGroups],
  );

  const [activeId, setActiveId] = useState<string>('');
  useEffect(() => {
    if (!activeId && bidangGroups.length) setActiveId(bidangGroups[0].id);
  }, [activeId, bidangGroups]);

  const activeGroup = bidangGroups.find((g: any) => g.id === activeId) ?? null;
  const kabinetName = cabinet?.name ?? profile?.kabinet_name ?? '';
  const kabinetPeriod = cabinet?.period ?? profile?.kabinet_period ?? '';
  const subtitleBits = [kabinetName, kabinetPeriod].map((x) => String(x || '').trim()).filter(Boolean);

  const sortedMembers = (members: any[]) =>
    (members ?? []).slice().sort((a: any, b: any) => (Number(a.sort_order ?? 999) || 999) - (Number(b.sort_order ?? 999) || 999));

  const corePeople = useMemo(() => sortedMembers(coreGroups.flatMap((g: any) => g.members ?? [])), [coreGroups]);
  const advisorPeople = useMemo(() => sortedMembers(advisorGroups.flatMap((g: any) => g.members ?? [])), [advisorGroups]);
  const pickLeader = (people: PublicStructureGroup['members']) => {
    const spotlight = people.find((p) => Boolean(p.is_spotlight));
    if (spotlight) return spotlight;
    const ketua = people.find((p) => String(p.role ?? '').toLowerCase().includes('ketua'));
    if (ketua) return ketua;
    return people[0] ?? null;
  };

  const renderAvatar = (p: any, size: 'xl' | 'lg' | 'md') => {
    const sizeClass =
      size === 'xl'
        ? 'h-36 w-36 sm:h-44 sm:w-44'
        : size === 'lg'
          ? 'h-28 w-28 sm:h-32 sm:w-32'
          : 'h-20 w-20 sm:h-24 sm:w-24';
    return (
      <div key={p.id} className="flex w-[180px] flex-col items-center text-center sm:w-[200px]">
        <div
          className={[
            'relative overflow-hidden rounded-full border-[3px] border-[var(--public-primary)] bg-slate-100 shadow-[0_18px_45px_-42px_rgba(15,23,42,0.35)]',
            sizeClass,
          ].join(' ')}
        >
          <PublicCoverImage url={p.photo_url} alt={p.name ?? 'Anggota'} imgClassName="object-cover" />
        </div>
        <div className="mt-3 text-sm font-extrabold tracking-tight text-slate-900">{p.name ?? '-'}</div>
        <div className="mt-1 text-xs font-semibold text-muted-foreground">{p.role ?? '-'}</div>
      </div>
    );
  };

  if (isError) {
    return (
      <PublicPageError title="Gagal memuat fungsionaris" error={structureSwr.error} onRetry={retry} />
    );
  }

  return (
    <PublicLayout>
      <PublicLoadingOverlay show={isLoading} label="Memuat fungsionaris..." />
      <PublicEnter>
        <PublicPageHero
          top="Susunan"
          bottom="Fungsionaris"
          subtitle={subtitleBits.length ? subtitleBits.join(' ΓÇó ') : 'Susunan fungsionaris yang dapat dikelola dari menu Konten Website.'}
          compact
        />
      </PublicEnter>

      {/* Cabinet Switcher */}
      {allCabinets.length > 1 && (
        <PublicEnter>
          <div className="mx-auto -mt-4 max-w-7xl px-4 py-4 sm:px-6">
            <div className="flex flex-wrap items-center justify-center gap-2">
              {allCabinets.map((cab: any) => {
                const isSelected = cabinet?.id === cab.id;
                return (
                  <button
                    key={cab.id}
                    type="button"
                    onClick={() => setSelectedCabinetId(isSelected ? null : cab.id)}
                    className={
                      (isSelected
                        ? "bg-[var(--public-primary)] text-white shadow-[0_10px_22px_rgba(37,99,235,0.35)]"
                        : "bg-white text-slate-900 border border-black/10 hover:border-[var(--public-primary)]/40"
                      ) + " inline-flex items-center gap-2 rounded-xl px-5 py-2.5 text-xs font-semibold uppercase tracking-wide transition"
                    }
                  >
                    {cab.name}
                    <span className="text-[10px] opacity-75">{cab.period}</span>
                    {cab.is_active && !isSelected && <span className="ml-1 h-2 w-2 rounded-full bg-green-500" />}
                  </button>
                );
              })}
            </div>
          </div>
        </PublicEnter>
      )}

      <PublicReveal className="mx-auto -mt-6 max-w-7xl px-4 pb-24 sm:px-6">
        {isLoading ? (
          <div className="mt-6 space-y-10">
            {Array.from({ length: 2 }).map((_, gi) => (
              <div key={gi}>
                <div className="mb-6 flex justify-center">
                  <Skeleton className="h-10 w-56" />
                </div>
                <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
                  {Array.from({ length: 6 }).map((__, idx) => (
                    <div key={idx} className="rounded-2xl border border-black/10 bg-white p-6">
                      <div className="flex items-center gap-4">
                        <Skeleton className="size-16 rounded-full" />
                        <div className="flex-1">
                          <Skeleton className="h-4 w-32" />
                          <Skeleton className="mt-2 h-4 w-44" />
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        ) : groups.length === 0 ? (
          <div className="mt-6">
            <PublicEmptyState
              variant="global"
              title="Struktur organisasi belum diatur"
              description="Admin dapat mengatur grup dan anggota dari menu Konten Website."
            />
          </div>
        ) : (
          <div className="mt-6">
            {subtitleBits.length ? (
              <div className="flex justify-center">
                <div className="flex w-full max-w-5xl items-center justify-center gap-2 overflow-x-auto pb-2 scrollbar-hide">
                  <span className="flex-none rounded-full bg-[var(--public-primary)] px-8 py-2 text-xs font-semibold uppercase tracking-widest text-white shadow-[0_16px_32px_rgba(37,99,235,0.30)]">
                    {subtitleBits[0]}
                  </span>
                </div>
              </div>
            ) : null}

            {advisorPeople.length ? (
              <div className="mt-10">
                <div className="text-center">
                  <div className="text-3xl font-extrabold uppercase tracking-tight text-[var(--public-primary)] sm:text-4xl">
                    DOSEN PEMBIMBING
                  </div>
                </div>
                <div className="mt-8 flex flex-wrap justify-center gap-x-10 gap-y-12">
                  {advisorPeople.map((p) => renderAvatar(p, advisorPeople.length === 1 ? 'xl' : 'lg'))}
                </div>
              </div>
            ) : null}

            <div className="mt-10 text-center">
              <div className="text-5xl font-extrabold uppercase tracking-tight text-[var(--public-primary)] sm:text-6xl">INTI</div>
            </div>

            {corePeople.length ? (
              (() => {
                const leader = pickLeader(corePeople);
                const rest = corePeople.filter((p) => p.id !== leader?.id);
                const vices = rest.filter((p) => String(p.role ?? '').toLowerCase().includes('wakil')).slice(0, 2);
                const rest2 = rest.filter((p) => !vices.some((x) => x.id === p.id));
                const mid = rest2.slice(0, 4);
                const tail = rest2.slice(4);
                return (
                  <div className="mt-10">
                    <div className="grid grid-cols-1 justify-items-center gap-10 sm:grid-cols-5 sm:gap-x-0 sm:gap-y-12">
                      {leader ? <div className="sm:col-start-3">{renderAvatar(leader, 'xl')}</div> : null}
                      {vices[0] ? <div className="sm:col-start-2">{renderAvatar(vices[0], 'lg')}</div> : null}
                      {vices[1] ? <div className="sm:col-start-4">{renderAvatar(vices[1], 'lg')}</div> : null}
                      {mid[0] ? <div className="sm:col-start-1">{renderAvatar(mid[0], 'md')}</div> : null}
                      {mid[1] ? <div className="sm:col-start-2">{renderAvatar(mid[1], 'md')}</div> : null}
                      {mid[2] ? <div className="sm:col-start-4">{renderAvatar(mid[2], 'md')}</div> : null}
                      {mid[3] ? <div className="sm:col-start-5">{renderAvatar(mid[3], 'md')}</div> : null}
                    </div>
                    {tail.length ? (
                      <div className="mt-12 grid grid-cols-2 justify-items-center gap-8 sm:grid-cols-4 lg:grid-cols-6">
                        {tail.map((p) => renderAvatar(p, 'md'))}
                      </div>
                    ) : null}
                  </div>
                );
              })()
            ) : (
              <PublicEmptyState
                variant="search"
                title="Belum ada data inti"
                description="Tambahkan anggota inti dari menu Konten Website."
              />
            )}

            <div className="mt-16 text-center">
              <div className="text-5xl font-extrabold uppercase tracking-tight text-[var(--public-primary)] sm:text-6xl">BIDANG</div>
            </div>

            {bidangGroups.length ? (
              <div className="mt-8">
                <div className="mx-auto flex w-full max-w-5xl items-center gap-2 overflow-x-auto pb-2 scrollbar-hide sm:flex-wrap sm:justify-center sm:overflow-visible">
                  {bidangGroups.map((g: any) => {
                    const active = g.id === activeId;
                    return (
                      <button
                        key={g.id}
                        type="button"
                        onClick={() => setActiveId(g.id)}
                        className={[
                          'flex-none rounded-full px-5 py-2 text-xs font-semibold uppercase tracking-widest transition ring-1 ring-inset',
                          active
                            ? 'bg-[var(--public-primary)] text-white ring-[var(--public-primary)] shadow-[0_12px_22px_rgba(37,99,235,0.28)]'
                            : 'bg-white text-[var(--public-primary)] ring-[var(--public-primary)]/25 hover:ring-[var(--public-primary)]/55',
                        ].join(' ')}
                      >
                        {g.title}
                      </button>
                    );
                  })}
                </div>

                {activeGroup && (activeGroup.members ?? []).length ? (
                  (() => {
                    const people = sortedMembers(activeGroup.members ?? []);
                    const leader = pickLeader(people);
                    const rest = people.filter((p) => p.id !== leader?.id);
                    const divisiHeads = rest.filter((p) => String(p.role ?? '').toLowerCase().includes('kadiv'));
                    const staff = rest.filter((p) => !divisiHeads.some((x) => x.id === p.id));
                    const panel = (
                      <>
                        <div className="flex justify-center">{leader ? renderAvatar(leader, 'xl') : null}</div>

                        {divisiHeads.length ? (
                          <div className="mt-14 text-center">
                            <div className="text-5xl font-extrabold uppercase tracking-tight text-[var(--public-primary)] sm:text-6xl">DIVISI</div>
                            <div className="mt-8 flex flex-wrap justify-center gap-10">
                              {divisiHeads.map((p) => renderAvatar(p, 'lg'))}
                            </div>
                          </div>
                        ) : null}

                        {staff.length ? (
                          <div className="mt-14 flex flex-wrap justify-center gap-x-10 gap-y-12">
                            {staff.map((p) => renderAvatar(p, 'md'))}
                          </div>
                        ) : null}
                      </>
                    );

                    if (reducedMotion) {
                      return (
                        <div key={activeId} className="mt-10">
                          {panel}
                        </div>
                      );
                    }

                    return (
                      <AnimatePresence mode="wait" initial={false}>
                        <m.div
                          key={activeId}
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          exit={{ opacity: 0, y: -10 }}
                          transition={fadeTransition(false)}
                          className="mt-10"
                        >
                          {panel}
                        </m.div>
                      </AnimatePresence>
                    );
                  })()
                ) : (
                  <PublicEmptyState
                    variant="search"
                    title="Anggota belum diisi"
                    description="Pilih bidang lain atau tambahkan anggota dari Konten Website."
                  />
                )}
              </div>
            ) : (
              <PublicEmptyState
                variant="global"
                title="Belum ada bidang"
                description="Tambahkan grup bidang/divisi dari menu Konten Website."
              />
            )}
          </div>
        )}
      </PublicReveal>
    </PublicLayout>
  );
}

import React, { useMemo, useState } from 'react';
