import { createContext, useContext, useEffect, useMemo } from 'react'
import { useTheme as useThemeStore } from '@/hooks/useTheme'

type Theme = 'light' | 'dark'

type ThemeProviderState = {
  theme: Theme
  setTheme: (theme: Theme) => void
  toggleTheme: () => void
}

const ThemeProviderContext = createContext<ThemeProviderState | undefined>(undefined)

/** Menyelesaikan temuan #4 ΓÇö sinkronkan class `dark` ke <html> via Zustand persist */
export function ThemeProvider({
  children,
  defaultTheme = 'light',
}: {
  children: React.ReactNode
  defaultTheme?: Theme
  storageKey?: string
}) {
  const theme = useThemeStore((s) => s.theme)
  const setTheme = useThemeStore((s) => s.setTheme)
  const toggleTheme = useThemeStore((s) => s.toggleTheme)

  useEffect(() => {
    if (!theme && defaultTheme) {
      setTheme(defaultTheme)
    }
  }, [defaultTheme, setTheme, theme])

  const value = useMemo(
    () => ({ theme: theme || defaultTheme, setTheme, toggleTheme }),
    [theme, defaultTheme, setTheme, toggleTheme],
  )

  return (
    <ThemeProviderContext.Provider value={value}>
      {children}
    </ThemeProviderContext.Provider>
  )
}

export function useTheme() {
  const context = useContext(ThemeProviderContext)
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider')
  }
  return context
}

// api.ts ΓÇö perubahan: tambah cooldown mechanism dan device fingerprint
import axios from 'axios';
import { useAuthStore } from '../stores/authStore';
import { useAppStatusStore } from '../stores/appStatusStore';
import { getDeviceFingerprint } from '../lib/storage/deviceFingerprint';

const apiBaseUrl = (import.meta as any)?.env?.VITE_API_BASE_URL || '/api';

const api = axios.create({
  baseURL: apiBaseUrl,
  withCredentials: true,
});

function getCookie(name: string): string | undefined {
  if (typeof document === 'undefined') return undefined;
  const parts = document.cookie.split(';').map((v) => v.trim());
  const hit = parts.find((v) => v.startsWith(`${name}=`));
  if (!hit) return undefined;
  return decodeURIComponent(hit.slice(name.length + 1));
}

function shouldLogoutFromRefresh(status?: number): boolean {
  return status === 401 || status === 403;
}

let maintenanceTimer: ReturnType<typeof setTimeout> | null = null;
const MAINTENANCE_OVERLAY_DELAY_MS = 5000;

function clearPendingMaintenance() {
  if (maintenanceTimer) {
    clearTimeout(maintenanceTimer);
    maintenanceTimer = null;
  }
}

function scheduleMaintenance(reason: string) {
  if (maintenanceTimer) return;
  maintenanceTimer = setTimeout(() => {
    maintenanceTimer = null;
    useAppStatusStore.getState().setMaintenance(reason);
  }, MAINTENANCE_OVERLAY_DELAY_MS);
}

let isRefreshing = false;
let failedQueue: Array<{ resolve: (v?: unknown) => void; reject: (e: unknown) => void }> = [];

// ΓöÇΓöÇΓöÇ BARU: Cooldown setelah refresh berhasil ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// Mencegah rapid re-trigger saat beberapa 401 tiba hampir bersamaan
// (misalnya: request yang terlanjur dikirim sebelum cookie baru di-set)
let lastSuccessfulRefreshAt = 0;
const REFRESH_COOLDOWN_MS = 10_000; // 10 detik
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const processQueue = (error: unknown) => {
  failedQueue.forEach((prom) => {
    if (error) prom.reject(error);
    else prom.resolve();
  });
  failedQueue = [];
};

export const verifySession = async () => {
  const now = Date.now();

  // Guard 1: Jika sedang refresh, antre ΓÇö jangan kirim request kedua ke backend
  if (isRefreshing) {
    return new Promise(function (resolve, reject) {
      failedQueue.push({ resolve, reject });
    });
  }

  // Guard 2: Jika baru saja refresh berhasil, skip
  // Cookie sudah berisi token baru; retry dari interceptor akan langsung berhasil
  // tanpa perlu menyentuh /auth/refresh lagi
  if (now - lastSuccessfulRefreshAt < REFRESH_COOLDOWN_MS) {
    return;
  }

  isRefreshing = true;
  try {
    const device_fingerprint = await getDeviceFingerprint();
    const res = await api.post('/auth/refresh', { device_fingerprint });
    lastSuccessfulRefreshAt = Date.now(); // ΓåÉ catat waktu berhasil
    processQueue(null);
    return res;
  } catch (refreshError) {
    processQueue(refreshError);
    const refreshStatus = (refreshError as { response?: { status?: number } })?.response?.status;
    if (shouldLogoutFromRefresh(refreshStatus)) {
      useAuthStore.getState().logout();
      if (window.location.pathname !== '/login') {
        window.location.href = '/login';
      }
    }
    throw refreshError;
  } finally {
    isRefreshing = false;
  }
};

api.interceptors.request.use((config) => {
  const method = String(config.method || 'get').toUpperCase();
  const isSafe = method === 'GET' || method === 'HEAD' || method === 'OPTIONS';

  if (!isSafe) {
    const token = getCookie('csrfToken');
    if (token) {
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      // @ts-ignore
      const headers = config.headers ?? {};
      if (typeof headers.set === 'function') {
        headers.set('X-CSRF-Token', token);
        config.headers = headers;
      } else {
        headers['X-CSRF-Token'] = token;
        config.headers = headers;
      }
    }
  }

  return config;
});

api.interceptors.response.use(
  (response) => {
    clearPendingMaintenance();
    useAppStatusStore.getState().clearNetworkIssues();
    return response;
  },
  async (error) => {
    const originalRequest = error.config;

    const url = String(originalRequest?.url || '');
    let pathname = url;
    try {
      pathname = new URL(url, window.location.origin).pathname;
    } catch {
      pathname = url;
    }

    const isPublicSiteRequest = pathname.includes('/public-site/');
    const isAdminPublicSiteRequest = pathname.includes('/public-site/admin');
    const isPublicRequest = isPublicSiteRequest && !isAdminPublicSiteRequest;

    if (error?.response) {
      clearPendingMaintenance();
      useAppStatusStore.getState().clearNetworkIssues();
    }

    if (!error?.response) {
      clearPendingMaintenance();
      if (typeof navigator !== 'undefined' && !navigator.onLine) {
        useAppStatusStore.getState().setOffline(true);
      } else {
        if (pathname !== '/status' && !isPublicRequest) {
          scheduleMaintenance('Menghubungkan ke server...');
        }
      }
    }
    const { isAuthenticated } = useAuthStore.getState();

    if (error.response?.status === 429) {
      return Promise.reject(error);
    }

    if (error.response?.status === 403 && !originalRequest._csrfRetry) {
      const apiError = error.response?.data?.error;
      if (apiError === 'CSRF validation failed') {
        originalRequest._csrfRetry = true;
        try {
          await verifySession();
          return api.request(originalRequest);
        } catch (refreshError) {
          return Promise.reject(refreshError);
        }
      }
    }

    if (originalRequest?.url?.includes('/auth/refresh')) {
      return Promise.reject(error);
    }

    if (error.response?.status === 401 && (!isAuthenticated || isPublicRequest)) {
      return Promise.reject(error);
    }

    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;
      try {
        await verifySession();
        return api.request(originalRequest);
      } catch (refreshError) {
        return Promise.reject(refreshError);
      }
    }

    return Promise.reject(error);
  }
);

export default api;

import { create } from 'zustand';
import { OFFLINE_USER_MESSAGE } from '@/lib/perf/networkEvents';

interface AppStatusState {
  isMaintenance: boolean;
  isOffline: boolean;
  reason?: string;
  setOffline: (offline: boolean) => void;
  setMaintenance: (reason?: string) => void;
  clearMaintenance: () => void;
  clearNetworkIssues: () => void;
}

export const useAppStatusStore = create<AppStatusState>((set) => ({
  isMaintenance: false,
  isOffline: false,
  reason: undefined,
  setOffline: (offline) =>
    set((state) =>
      offline
        ? {
            isOffline: true,
            reason: OFFLINE_USER_MESSAGE,
            isMaintenance: false,
          }
        : { isOffline: false }
    ),
  setMaintenance: (reason) => set({ isMaintenance: true, isOffline: false, reason }),
  clearMaintenance: () => set({ isMaintenance: false, reason: undefined }),
  clearNetworkIssues: () => set({ isMaintenance: false, isOffline: false, reason: undefined }),
}));
